sendSuccess: (res, message, data = null) => {
    const responseMessage = {
        code: message.code ? message.code : 500,
        success: message.success,
        message: message.message,
    };
    if (data) { responseMessage.data = data; }
    return res.status(message.code).json(responseMessage);
},

sendError: (res, error) => {
    const responseMessage = {
        code: error.code ? error.code : 500,
        success: false,
        message: error.message,
    };
    return res.status(error.code ? error.code : 500).json(responseMessage);
},

"devDependencies": {
  "@testing-library/jest-dom": "^5.15.0",
  "@testing-library/react": "^12.1.4",
  "@testing-library/user-event": "^7.2.1",
  "react-scripts": "^5.0.0"
},

constructor(props) {
  super(props);
  this.state = {
    todos: [],
  };
}

componentDidMount() {
  axios
    .get("/api")
    .then((response) => {
      this.setState({
        todos: response.data.data,
      });
    })
    .catch((e) => console.log("Error : ", e));
}

handleAddTodo = (value) => {
  axios
    .post("/api/todos", { text: value })
    .then(() => {
      this.setState({
        todos: [...this.state.todos, { text: value }],
      });
    })
    .catch((e) => console.log("Error : ", e));
};

handleSubmit = (e) => {
  e.preventDefault();
  const { value } = e.target.elements.value;
  if (value.length > 0) {
    this.props.handleAddTodo(value);
    e.target.reset();
  }
};

render() {
  return (
    <form
      noValidate
      onSubmit={this.handleSubmit}
      className="new-todo form-group"
    >
      <input
        type="text"
        name="value"
        required
        minLength={1}
        className="form-control"
      />
      <button className="btn btn-primary" type="submit">
        Add Todo
      </button>
    </form>
  );
}

constructor(props) {
  super(props);
  this.state = {
    activeIndex: 0,
  };
}

handleActive(index) {
  this.setState({
    activeIndex: index,
  });
}

renderTodos(todos) {
  return (
    <ul className="list-group">
      {todos.map((todo, i) => (
        <li
          className={
            "list-group-item cursor-pointer " +
            (i === this.state.activeIndex ? "active" : "")
          }
          key={i}
          onClick={() => {
            this.handleActive(i);
          }}
        >
          {todo.text}
        </li>
      ))}
    </ul>
  );
}

render() {
  let { todos } = this.props;
  return todos.length > 0 ? (
    this.renderTodos(todos)
  ) : (
    <div className="alert alert-primary" role="alert">
      No Todos to display
    </div>
  );
}

import React from 'react';
import ReactDOM from 'react-dom';
import './index.css';
import App from './App';
import * as serviceWorker from './serviceWorker';
import './custom.scss';
ReactDOM.render(<App />, document.getElementById('root'));
// If you want your app to work offline and load faster, you can change
// unregister() to register() below. Note this comes with some pitfalls.
// Learn more about service workers: https://bit.ly/CRA-PWA
serviceWorker.unregister();

const isLocalhost = Boolean(
  window.location.hostname === 'localhost' ||
    // [::1] is the IPv6 localhost address.
    window.location.hostname === '[::1]' ||
    // 127.0.0.1/8 is considered localhost for IPv4.
    window.location.hostname.match(
      /^127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/

export function register(config) {
  if (process.env.NODE_ENV === 'production' && 'serviceWorker' in navigator) {
    // The URL constructor is available in all browsers that support SW.
    const publicUrl = new URL(process.env.PUBLIC_URL, window.location.href);
    if (publicUrl.origin !== window.location.origin) {
      // Our service worker won't work if PUBLIC_URL is on a different origin
      // from what our page is served on. This might happen if a CDN is used to
      // serve assets; see https://github.com/facebook/create-react-app/issues/2374
      return;
    }
    window.addEventListener('load', () => {
      const swUrl = `${process.env.PUBLIC_URL}/service-worker.js`;
      if (isLocalhost) {
        // This is running on localhost. Let's check if a service worker still exists or not.
        checkValidServiceWorker(swUrl, config);
        // Add some additional logging to localhost, pointing developers to the
        // service worker/PWA documentation.
        navigator.serviceWorker.ready.then(() => {
          console.log(
            'This web app is being served cache-first by a service ' +
              'worker. To learn more, visit https://bit.ly/CRA-PWA'
          );
        });
      } else {
        // Is not localhost. Just register service worker
        registerValidSW(swUrl, config);
      }
    });
  }
}

function registerValidSW(swUrl, config) {
  navigator.serviceWorker
    .register(swUrl)
    .then(registration => {
      registration.onupdatefound = () => {
        const installingWorker = registration.installing;
        if (installingWorker == null) {
          return;
        }
        installingWorker.onstatechange = () => {
          if (installingWorker.state === 'installed') {
            if (navigator.serviceWorker.controller) {
              // At this point, the updated precached content has been fetched,
              // but the previous service worker will still serve the older
              // content until all client tabs are closed.
              console.log(
                'New content is available and will be used when all ' +
                  'tabs for this page are closed. See https://bit.ly/CRA-PWA.'
              );
              // Execute callback
              if (config && config.onUpdate) {
                config.onUpdate(registration);
              }
            } else {
              // At this point, everything has been precached.
              // It's the perfect time to display a
              // "Content is cached for offline use." message.
              console.log('Content is cached for offline use.');
              // Execute callback
              if (config && config.onSuccess) {
                config.onSuccess(registration);
              }
            }
          }
        };
      };
    })
    .catch(error => {
      console.error('Error during service worker registration:', error);
    });
}

function checkValidServiceWorker(swUrl, config) {
  // Check if the service worker can be found. If it can't reload the page.
  fetch(swUrl)
    .then(response => {
      // Ensure service worker exists, and that we really are getting a JS file.
      const contentType = response.headers.get('content-type');
      if (
        response.status === 404 ||
        (contentType != null && contentType.indexOf('javascript') === -1)
      ) {
        // No service worker found. Probably a different app. Reload the page.
        navigator.serviceWorker.ready.then(registration => {
          registration.unregister().then(() => {
            window.location.reload();
          });
        });
      } else {
        // Service worker found. Proceed as normal.
        registerValidSW(swUrl, config);
      }
    })
    .catch(() => {
      console.log(
        'No internet connection found. App is running in offline mode.'
      );
    });
}

export function unregister() {
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.ready.then(registration => {
      registration.unregister();
    });
  }
}

const http = require("http");
