): Promise<R | PageDto<R> | void> {
  const returnData = await firstValueFrom(
    this.client.send<{ data?: R; meta?: PageMetaDto }>(pattern, data),
    {
      defaultValue: undefined,
    },
  );
  if (returnDataOptions?.isPage && (!returnData?.data || !returnData.meta)) {
    throw new PageTypeException();
  }
  if (!returnDataOptions?.class || returnDataOptions.isPage) {
    return returnData as R;
  }
  return plainToInstance(returnDataOptions.class, returnData);
}

import {
  Column,
  CreateDateColumn,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from 'typeorm';
import { LanguageCode } from '../constants/language-code.ts';
import type {
  AbstractDto,
  AbstractTranslationDto,
} from './dto/abstract.dto.ts';
/**
 * Abstract Entity
 * @author Narek Hakobyan <narek.hakobyan.07@gmail.com>
 *
 * @description This class is an abstract class for all entities.
 * It's experimental and recommended using it only in microservice architecture,
 * otherwise just delete and use your own entity.
 */

@PrimaryGeneratedColumn('uuid')
id!: Uuid;
@CreateDateColumn({
  type: 'timestamp',
})
createdAt!: Date;
@UpdateDateColumn({
  type: 'timestamp',
})
updatedAt!: Date;
translations?: AbstractTranslationEntity[];

toDto(options?: O): DTO {
  const dtoClass = Object.getPrototypeOf(this).dtoClass;
  if (!dtoClass) {
    throw new Error(
      `You need to use @UseDto on class (${this.constructor.name}) be able to call toDto function`,
    );
  }
  return new dtoClass(this, options);
}

@UUIDField()
id!: Uuid;
@DateField()
createdAt!: Date;
@DateField()
updatedAt!: Date;
translations?: AbstractTranslationDto[];
constructor(entity: AbstractEntity, options?: { excludeFields?: boolean }) {
  if (!options?.excludeFields) {
    this.id = entity.id;
    this.createdAt = entity.createdAt;
    this.updatedAt = entity.updatedAt;
  }
  const languageCode = ContextProvider.getLanguage();
  if (languageCode && entity.translations) {
    const translationEntity = entity.translations.find(
      (titleTranslation) => titleTranslation.languageCode === languageCode,
    )!;
    const fields: Record<string, string> = {};
    for (const key of Object.keys(translationEntity)) {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      const metadata = Reflect.getMetadata(
        DYNAMIC_TRANSLATION_DECORATOR_KEY,
        this,
        key,
      );
      if (metadata) {
        fields[key] = (translationEntity as never)[key];
      }
    }
    Object.assign(this, fields);
  } else {
    this.translations = entity.translations?.toDtos();
  }
}

constructor(entity: AbstractEntity) {
  super(entity, { excludeFields: true });
}

import { plainToInstance } from 'class-transformer';
import { validateSync } from 'class-validator';
export type Plain<T> = T extends Date | ((...args: never[]) => unknown)
  ? T
  : T extends Array<infer U>
    ? Array<Plain<U>>
    : T extends object
      ? {
          [K in keyof T as T[K] extends (...args: never[]) => unknown
            ? never
            : K]: Plain<T[K]>;
        }
      : T;
// biome-ignore lint/complexity/noStaticOnlyClass: base class for inheritance; subclasses inherit the static `create` factory

static create<T extends BaseDto>(
  this: new (...args: unknown[]) => T,
  data: Plain<T>,
): T {
  const instance = plainToInstance<T, Plain<T>>(this, data, {
    excludeExtraneousValues: true,
    exposeUnsetFields: false,
  });
  if (process.env.NODE_ENV !== 'production') {
    const errors = validateSync(instance as object);
    if (errors.length > 0) {
      throw new Error(errors.map((e) => e.toString()).join('\n'));
    }
  }
  return instance;
}

@EnumField(() => LanguageCode)
