import type { CustomDecorator } from '@nestjs/common';
import { SetMetadata } from '@nestjs/common';
export const PUBLIC_ROUTE_KEY = 'public_route';
// eslint-disable-next-line @typescript-eslint/naming-convention
export const PublicRoute = (isPublic = false): CustomDecorator =>
  SetMetadata(PUBLIC_ROUTE_KEY, isPublic);

// eslint-disable-next-line max-len
/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-explicit-any,@typescript-eslint/no-unsafe-member-access,@typescript-eslint/no-unsafe-return,@typescript-eslint/no-unsafe-argument */
import type { Type } from '@nestjs/common';
import { applyDecorators, UseInterceptors } from '@nestjs/common';
import { FileInterceptor, FilesInterceptor } from '@nestjs/platform-express';
import {
  ApiBody,
  ApiConsumes,
  ApiExtraModels,
  getSchemaPath,
} from '@nestjs/swagger';
import type {
  ReferenceObject,
  SchemaObject,
} from '@nestjs/swagger/dist/interfaces/open-api-spec.interface';
import _ from 'lodash';
import type { IApiFile } from '../interfaces/IApiFile.ts';
const PARAMTYPES_METADATA = 'design:paramtypes';

function reverseObjectKeys(
  originalObject: Record<string, any>,
): Record<string, any> {
  const reversedObject: any = {};
  const keys = Object.keys(originalObject).reverse();
  for (const key of keys) {
    reversedObject[key] = originalObject[key];
  }
  return reversedObject;
}

function explore(instance: object, propertyKey: string | symbol) {
  const types: Array<Type<unknown>> = Reflect.getMetadata(
    PARAMTYPES_METADATA,
    instance,
    propertyKey,
  );
  const routeArgsMetadata =
    Reflect.getMetadata(
      ROUTE_ARGS_METADATA,
      instance.constructor,
      propertyKey,
    ) || {};
  const parametersWithType = _.mapValues(
    reverseObjectKeys(routeArgsMetadata),
    (param) => ({
      type: types[param.index],
      name: param.data,
      required: true,
    }),
  );
  for (const [key, value] of Object.entries(parametersWithType)) {
    const keyPair = key.split(':');
    if (Number(keyPair[0]) === 3) {
      return value.type;
    }
  }
  return null;
}

function RegisterModels(): MethodDecorator {
  return (target, propertyKey, descriptor: PropertyDescriptor) => {
    const body = explore(target, propertyKey);
    return body && ApiExtraModels(body)(target, propertyKey, descriptor);
  };
}

function ApiFileDecorator(
  files: IApiFile[] = [],
  options: Partial<{ isRequired: boolean }> = {},
): MethodDecorator {

return (target, propertyKey, descriptor: PropertyDescriptor) => {
  const { isRequired = false } = options;
  const fileSchema: SchemaObject = {
    type: 'string',
    format: 'binary',
  };
  const properties: Record<string, SchemaObject | ReferenceObject> = {};
  for (const file of files) {
    properties[file.name] = file.isArray
      ? {
          type: 'array',
          items: fileSchema,
        }
      : fileSchema;
  }
  let schema: SchemaObject = {
    properties,
    type: 'object',
  };
  const body = explore(target, propertyKey);
  if (body) {
    schema = {
      allOf: [
        {
          $ref: getSchemaPath(body),
        },
        { properties, type: 'object' },
      ],
    };
  }
  return ApiBody({
    schema,
    required: isRequired,
  })(target, propertyKey, descriptor);
};

}
export function ApiFile(
  files: _.Many<IApiFile>,
  options: Partial<{ isRequired: boolean }> = {},
): MethodDecorator {
  const filesArray = _.castArray(files);
  const apiFileInterceptors = filesArray.map((file) =>
    file.isArray
      ? UseInterceptors(FilesInterceptor(file.name))
      : UseInterceptors(FileInterceptor(file.name)),
  );
  return applyDecorators(
    RegisterModels(),
    ApiConsumes('multipart/form-data'),
    ApiFileDecorator(filesArray, options),
    ...apiFileInterceptors,
  );
}

export function Trim(trimNewLines: boolean): PropertyDecorator {
  return Transform((params): string[] | string => {
    const value = params.value as string[] | string;
    if (!value) {
      return value;
    }
    if (Array.isArray(value)) {
      return value.map((v) => {
        const trimmedValue = v.trim();
        if (trimNewLines) {
          return trimmedValue.replaceAll(/\s\s+/g, ' ');
        }
        return trimmedValue;
      });
    }
    const trimmedValue = value.trim();
    if (trimNewLines) {
      return trimmedValue.replaceAll(/\s\s+/g, ' ');
    }
    return trimmedValue;
  });
}

export function ToBoolean(): PropertyDecorator {
  return Transform(
    (params) => {
      switch (params.value) {
        case 'true': {
          return true;
        }
        case 'false': {
          return false;
        }
        default: {
          return params.value;
        }
      }
    },
    { toClassOnly: true },
  );
}

export function ToInt(): PropertyDecorator {
  return Transform(
    (params) => {
      const value = params.value as string;
      return Number.parseInt(value, 10);
    },
    { toClassOnly: true },
  );
}

export function ToArray(): PropertyDecorator {
  return Transform(
    (params): unknown[] => {
      const value = params.value;
      if (!value) {
        return value;
      }
      return _.castArray(value);
    },
    { toClassOnly: true },
  );
}

export function ToLowerCase(): PropertyDecorator {
  return Transform(
    (params) => {
      const value = params.value;
      if (!value) {
        return;
      }
      if (!Array.isArray(value)) {
        return value.toLowerCase();
      }
      return value.map((v) => v.toLowerCase());
    },
    {
      toClassOnly: true,
    },
  );
}

export function ToUpperCase(): PropertyDecorator {
  return Transform(
    (params) => {
      const value = params.value;
      if (!value) {
        return;
      }
      if (!Array.isArray(value)) {
        return value.toUpperCase();
      }
      return value.map((v) => v.toUpperCase());
    },
    {
      toClassOnly: true,
    },
  );
}

export function S3UrlParser(): PropertyDecorator {
  return Transform((params) => {
    const key = params.value as string;
    switch (params.type) {
      case TransformationType.CLASS_TO_PLAIN: {
        return GeneratorProvider.getS3PublicUrl(key);
      }
      case TransformationType.PLAIN_TO_CLASS: {
        return GeneratorProvider.getS3Key(key);
      }
      default: {
        return key;
      }
    }
  });
}

export function PhoneNumberSerializer(): PropertyDecorator {
  return Transform(
    (params) => parsePhoneNumberWithError(params.value as string).number,
  );
}

export function LinkCleanupTransform(options?: {
  removeTrailingSlash?: boolean;
  removeQueryParams?: boolean;
}): PropertyDecorator {

return Transform((params) => {
  let value = params.value as string;
  if (!value) {
    return value;
  }
  if (options?.removeQueryParams) {
    value = value.replace(/\?.*$/, '');
  }
  if (options?.removeTrailingSlash ?? true) {
    value = value.replace(/\/+$/, '');
  }
  return value;
});

import type { ITranslationDecoratorInterface } from '../interfaces/ITranslationDecoratorInterface.ts';
export const STATIC_TRANSLATION_DECORATOR_KEY = 'custom:static-translate';
export const DYNAMIC_TRANSLATION_DECORATOR_KEY = 'custom:dynamic-translate';
// FIXME: This is a temporary solution to get the translation decorator working.
export function StaticTranslate(
  data: ITranslationDecoratorInterface = {},
): PropertyDecorator {

return (target, key) => {
  Reflect.defineMetadata(STATIC_TRANSLATION_DECORATOR_KEY, data, target, key);
};

export function DynamicTranslate(): PropertyDecorator {
  return (target, key) => {
    Reflect.defineMetadata(DYNAMIC_TRANSLATION_DECORATOR_KEY, {}, target, key);
  };
}

export function UseDto(dtoClass: Constructor): ClassDecorator {
  return (ctor) => {
    // FIXME make dtoClass function returning dto
    if (!(dtoClass as unknown)) {
      throw new Error('UseDto decorator requires dtoClass');
    }
    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    ctor.prototype.dtoClass = dtoClass;
  };
}

import type { ValidationOptions } from 'class-validator';
import {
  IsPhoneNumber as isPhoneNumber,
  registerDecorator,
  ValidateIf,
} from 'class-validator';
import _ from 'lodash';

export function IsPassword(
  validationOptions?: ValidationOptions,
): PropertyDecorator {
  return (object, propertyName) => {
    registerDecorator({
      propertyName: propertyName as string,
      name: 'isPassword',
      target: object.constructor,
      constraints: [],
      options: validationOptions,
      validator: {
        validate(value: string) {
          return /^[\d!#$%&*@A-Z^a-z]*$/.test(value);
        },
      },
    });
  };
}

export function IsPhoneNumber(
  validationOptions?: ValidationOptions & {
    region?: Parameters<typeof isPhoneNumber>[0];
  },
): PropertyDecorator {
  return isPhoneNumber(validationOptions?.region, {
    message: 'error.phoneNumber',
    ...validationOptions,
  });
}

export function IsTmpKey(
  validationOptions?: ValidationOptions,
): PropertyDecorator {
  return (object, propertyName) => {
    registerDecorator({
      propertyName: propertyName as string,
      name: 'tmpKey',
      target: object.constructor,
      options: validationOptions,
      validator: {
        validate(value: string): boolean {
          return _.isString(value) && value.startsWith('tmp/');
        },
        defaultMessage(): string {
          return 'error.invalidTmpKey';
        },
      },
    });
  };
}

export function IsUndefinable(options?: ValidationOptions): PropertyDecorator {
  return ValidateIf((_obj, value) => value !== undefined, options);
}

export function IsNullable(options?: ValidationOptions): PropertyDecorator {
  return ValidateIf((_obj, value) => value !== null, options);
}

