catch(exception: UnprocessableEntityException, host: ArgumentsHost): void {
  const ctx = host.switchToHttp();
  const response = ctx.getResponse<Response>();
  const statusCode = exception.getStatus();
  const r = exception.getResponse() as { message: ValidationError[] };
  const validationErrors = r.message;
  this.validationFilter(validationErrors);
  response.status(statusCode).json(r);
}

private validationFilter(validationErrors: ValidationError[]): void {
  for (const validationError of validationErrors) {
    const children = validationError.children;
    if (children && !_.isEmpty(children)) {
      this.validationFilter(children);
      return;
    }
    delete validationError.children;
    const constraints = validationError.constraints;
    if (!constraints) {
      return;
    }
    for (const [constraintKey, constraint] of Object.entries(constraints)) {
      // convert default messages
      if (!constraint) {
        // convert error message to error.fields.{key} syntax for i18n translation
        constraints[constraintKey] = `error.fields.${_.snakeCase(
          constraintKey,
        )}`;
      }
    }
  }
}

/* eslint-disable @typescript-eslint/naming-convention */
export const constraintErrors: Record<string, string> = {
  UQ_97672ac88f789774dd47f7c8be3: 'error.unique.email',
};

catch(
  exception: QueryFailedError & { constraint?: string },
  host: ArgumentsHost,
) {
  const ctx = host.switchToHttp();
  const response = ctx.getResponse<Response>();
  const status = exception.constraint?.startsWith('UQ')
    ? HttpStatus.CONFLICT
    : HttpStatus.INTERNAL_SERVER_ERROR;
  response.status(status).json({
    statusCode: status,
    error: STATUS_CODES[status],
    message: exception.constraint
      ? constraintErrors[exception.constraint]
      : undefined,
  });
}

import type { IAuthGuard, Type } from '@nestjs/passport';
import { AuthGuard as NestAuthGuard } from '@nestjs/passport';
export function AuthGuard(
  options?: Partial<{ public: boolean }>,
): Type<IAuthGuard> {
  const strategies = ['jwt'];
  if (options?.public) {
    strategies.push('public');
  }
  return NestAuthGuard(strategies);
}

canActivate(context: ExecutionContext): boolean {
  const roles = this.reflector.get<RoleType[] | undefined>(
    'roles',
    context.getHandler(),
  );
  if (!roles?.length) {
    return true;
  }
  const request = context.switchToHttp().getRequest<{ user: UserEntity }>();
  const user = request.user;
  return roles.includes(user.role);
}

