async validate(args: {
  userId: Uuid;
  role: RoleType;
  type: TokenType;
}): Promise<UserEntity> {
  if (args.type !== TokenType.ACCESS_TOKEN) {
    throw new UnauthorizedException();
  }
  const user = await this.userService.findOne({
    // FIXME: issue with type casts
    id: args.userId as never,
    role: args.role,
  });
  if (!user) {
    throw new UnauthorizedException();
  }
  return user;
}

override validate(): void {
  this.success({ [Symbol.for('isPublic')]: true });
}

import { Controller, Get } from '@nestjs/common';
import type { HealthCheckResult } from '@nestjs/terminus';
import {
  HealthCheck,
  HealthCheckService,
  TypeOrmHealthIndicator,
} from '@nestjs/terminus';
import { ServiceHealthIndicator } from './health-indicators/service.indicator.ts';

constructor(
  private healthCheckService: HealthCheckService,
  private ormIndicator: TypeOrmHealthIndicator,
  private serviceIndicator: ServiceHealthIndicator,
) {}

@Get()
@HealthCheck()
async check(): Promise<HealthCheckResult> {
  return this.healthCheckService.check([
    () => this.ormIndicator.pingCheck('database', { timeout: 1500 }),
    () => this.serviceIndicator.isHealthy('search-service-health'),
  ]);
}

constructor(
  @Optional()
  @Inject('NATS_SERVICE')
  private readonly clientProxy?: ClientProxy,
) {
  super();
}

async isHealthy(eventName: string): Promise<HealthIndicatorResult> {
  try {
    if (!this.clientProxy) {
      return {
        [eventName]: {
          status: 'down',
        },
      };
    }
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
    const result = await firstValueFrom(
      this.clientProxy.send(eventName, { check: true }).pipe(timeout(10_000)),
      {
        defaultValue: undefined,
      },
    );
    return {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      [eventName]: result,
    };
  } catch (error) {
    throw new HealthCheckError(`${eventName} failed`, {
      [eventName]: error,
    });
  }
}

