constructor(
  @InjectRepository(UserEntity)
  private userRepository: Repository<UserEntity>,
  private validatorService: ValidatorService,
  private awsS3Service: AwsS3Service,
  private commandBus: CommandBus,
) {}

/**
 * Find single user
 */
findOne(findData: FindOptionsWhere<UserEntity>): Promise<UserEntity | null> {
  return this.userRepository.findOneBy(findData);
}
findByUsernameOrEmail(
  options: Partial<{ username: string; email: string }>,
): Promise<UserEntity | null> {
  const queryBuilder = this.userRepository
    .createQueryBuilder('user')
    .leftJoinAndSelect<UserEntity, 'user'>('user.settings', 'settings');
  if (options.email) {
    queryBuilder.orWhere('user.email = :email', {
      email: options.email,
    });
  }
  if (options.username) {
    queryBuilder.orWhere('user.username = :username', {
      username: options.username,
    });
  }
  return queryBuilder.getOne();
}

findOne(findData: FindOptionsWhere<UserEntity>): Promise<UserEntity | null> {
  return this.userRepository.findOneBy(findData);
}

@Transactional()
async createUser(
  userRegisterDto: UserRegisterDto,
  file?: Reference<IFile>,
): Promise<UserEntity> {
  const user = this.userRepository.create(userRegisterDto);
  if (file && !this.validatorService.isImage(file.mimetype)) {
    throw new FileNotImageException();
  }
  if (file) {
    user.avatar = await this.awsS3Service.uploadImage(file);
  }
  await this.userRepository.save(user);
  user.settings = await this.createSettings(
    user.id,
    plainToClass(CreateSettingsDto, {
      isEmailVerified: false,
      isPhoneVerified: false,
    }),
  );
  return user;
}

async getUsers(
  pageOptionsDto: UsersPageOptionsDto,
): Promise<PageDto<UserDto>> {
  const queryBuilder = this.userRepository.createQueryBuilder('user');
  if (pageOptionsDto.q) {
    queryBuilder.searchByString(pageOptionsDto.q, ['firstName', 'email']);
  }
  const [items, pageMetaDto] = await queryBuilder.paginate(pageOptionsDto);
  // eslint-disable-next-line sonarjs/argument-type
  return items.toPageDto(pageMetaDto);
}

async getUser(userId: Uuid): Promise<UserDto> {
  const queryBuilder = this.userRepository.createQueryBuilder('user');
  queryBuilder.where('user.id = :userId', { userId });
  const userEntity = await queryBuilder.getOne();
  if (!userEntity) {
    throw new UserNotFoundException();
  }
  return userEntity.toDto();
}

createSettings(
  userId: Uuid,
  createSettingsDto: CreateSettingsDto,
): Promise<UserSettingsEntity> {
  return this.commandBus.execute<CreateSettingsCommand, UserSettingsEntity>(
    new CreateSettingsCommand(userId, createSettingsDto),
  );
}

private static readonly nameSpace = 'request';
private static readonly authUserKey = 'user_key';
private static readonly languageKey = 'language_key';
private static get<T>(key: string) {
  const store = ClsServiceManager.getClsService();
  return store.get<T>(ContextProvider.getKeyWithNamespace(key));
}
// eslint-disable-next-line @typescript-eslint/no-explicit-any

private static get<T>(key: string) {
  const store = ClsServiceManager.getClsService();
  return store.get<T>(ContextProvider.getKeyWithNamespace(key));
}

private static set(key: string, value: any): void {
  const store = ClsServiceManager.getClsService();
  store.set(ContextProvider.getKeyWithNamespace(key), value);
}

private static getKeyWithNamespace(key: string): string {
  return `${ContextProvider.nameSpace}.${key}`;
}

static setAuthUser(user: UserEntity): void {
  ContextProvider.set(ContextProvider.authUserKey, user);
}

static setLanguage(language: string): void {
  ContextProvider.set(ContextProvider.languageKey, language);
}

static getLanguage(): LanguageCode | undefined {
  return ContextProvider.get<LanguageCode>(ContextProvider.languageKey);
}

static getAuthUser(): UserEntity | undefined {
  return ContextProvider.get<UserEntity>(ContextProvider.authUserKey);
}

static uuid(): string {
  return uuid();
}

static fileName(ext: string): string {
  return `${GeneratorProvider.uuid()}.${ext}`;
}

static getS3PublicUrl(key: string): string {
  if (!key) {
    throw new TypeError('key is required');
  }
  return `https://s3.${process.env.AWS_S3_BUCKET_NAME_REGION}.amazonaws.com/${process.env.AWS_S3_BUCKET_NAME}/${key}`;
}

static getS3Key(publicUrl: string): string {
  if (!publicUrl) {
    throw new TypeError('key is required');
  }
  const exec = new RegExp(
    `(?<=https://s3.${process.env.AWS_S3_BUCKET_NAME_REGION}.amazonaws.com/${process.env.AWS_S3_BUCKET_NAME}/).*`,
  ).exec(publicUrl);
  if (!exec) {
    throw new TypeError('publicUrl is invalid');
  }
  return exec[0];
}

static generateVerificationCode(): string {
  return Math.floor(1000 + Math.random() * 9000).toString();
}

static generatePassword(): string {
  const lowercase = 'abcdefghijklmnopqrstuvwxyz';
  const uppercase = lowercase.toUpperCase();
  const numbers = '0123456789';
  let text = '';
  for (let i = 0; i < 4; i++) {
    text += uppercase.charAt(Math.floor(Math.random() * uppercase.length));
    text += lowercase.charAt(Math.floor(Math.random() * lowercase.length));
    text += numbers.charAt(Math.floor(Math.random() * numbers.length));
  }
  return text;
}

static generateRandomString(length: number): string {
  return Math.random()
    .toString(36)
    .replaceAll(/[^\dA-Za-z]+/g, '')
    .slice(0, Math.max(0, length));
}

get isDevelopment(): boolean {
  return this.nodeEnv === 'development';
}

get isProduction(): boolean {
  return this.nodeEnv === 'production';
}

get isTest(): boolean {
  return this.nodeEnv === 'test';
}

private getNumber(key: string): number {
  const value = this.get(key);
  const num = Number(value);
  if (Number.isNaN(num)) {
    throw new TypeError(
      `Environment variable ${key} must be a number. Received: ${value}`,
    );
  }
  return num;
}

private getBoolean(key: string): boolean {
  const value = this.get(key);
  try {
    return Boolean(JSON.parse(value));
  } catch {
    throw new Error(
      `Environment variable ${key} must be a boolean. Received: ${value}`,
    );
  }
}

private getString(key: string, defaultValue?: string): string {
  const value = this.configService.get<string>(key);
  if (value === undefined) {
    if (defaultValue !== undefined) {
      return defaultValue;
    }
    throw new Error(`${key} environment variable doesn't exist`);
  }
  return value.toString().replaceAll(String.raw`\n`, '\n');
}

get fallbackLanguage(): string {
  return this.getString('FALLBACK_LANGUAGE');
}

get postgresConfig(): TypeOrmModuleOptions {
  const entities = [
    path.join(import.meta.dirname, `../../modules/**/*.entity{.ts,.js}`),
    path.join(import.meta.dirname, `../../modules/**/*.view-entity{.ts,.js}`),
  ];
  const migrations = [
    path.join(import.meta.dirname, `../../database/migrations/*{.ts,.js}`),
  ];
  return {
    entities,
    migrations,
    dropSchema: this.isTest,
    type: 'postgres',
    host: this.getString('DB_HOST'),
    port: this.getNumber('DB_PORT'),
    username: this.getString('DB_USERNAME'),
    password: this.getString('DB_PASSWORD'),
    database: this.getString('DB_DATABASE'),
    subscribers: [UserSubscriber],
    migrationsRun: true,
    logging: this.getBoolean('ENABLE_ORM_LOGS'),
    namingStrategy: new SnakeNamingStrategy(),
  };
}

get documentationEnabled(): boolean {
  return this.getBoolean('ENABLE_DOCUMENTATION');
}

get natsEnabled(): boolean {
  return this.getBoolean('NATS_ENABLED');
}

get authConfig() {
  return {
    privateKey: this.getString('JWT_PRIVATE_KEY'),
    publicKey: this.getString('JWT_PUBLIC_KEY'),
    jwtExpirationTime: this.getNumber('JWT_EXPIRATION_TIME'),
  };
}

private get(key: string): string {
  const value = this.configService.get<string>(key);
  if (value == null) {
    throw new Error(`Environment variable ${key} is not set`);
  }
  return value;
}

constructor(
  public configService: ApiConfigService,
  public generatorService: GeneratorService,
) {
  const config = configService.awsS3Config;
  this.s3 = new S3({
    apiVersion: config.bucketApiVersion,
    region: config.bucketRegion,
  });
}

async uploadImage(file: IFile): Promise<string> {
  const fileName = this.generatorService.fileName(
    mime.extension(file.mimetype) as string,
  );
  const key = `images/${fileName}`;
  await this.s3.putObject({
    Bucket: this.configService.awsS3Config.bucketName,
    Body: file.buffer,
    ACL: 'public-read',
    Key: key,
  });
  return key;
}

public uuid(): string {
  return uuid();
}

public fileName(ext: string): string {
  return `${this.uuid()}.${ext}`;
}

translate(key: string, options?: TranslateOptions): Promise<string> {
  return this.i18n.translate(key, {
    ...options,
    lang: ContextProvider.getLanguage(),
  });
}

async translateNecessaryKeys<T extends AbstractDto>(dto: T): Promise<T> {
  await Promise.all(
    _.map(dto, (value, key) => {
      if (_.isString(value)) {
        // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
        const translateDec: ITranslationDecoratorInterface | undefined =
          Reflect.getMetadata(STATIC_TRANSLATION_DECORATOR_KEY, dto, key);
        if (translateDec) {
          return this.translate(
            `${translateDec.translationKey ?? key}.${value}`,
          );
        }
        return;
      }
      if (value instanceof AbstractDto) {
        return this.translateNecessaryKeys(value);
      }
      if (Array.isArray(value)) {
        return Promise.all(
          _.map(value, (v) => {
            if (v instanceof AbstractDto) {
              return this.translateNecessaryKeys(v);
            }
            return null;
          }),
        );
      }
      return null;
    }),
  );
  return dto;
}

public isImage(mimeType: string): boolean {
  const imageMimeTypes = ['image/jpeg', 'image/png'];
  return imageMimeTypes.includes(mimeType);
}

import type { Provider } from '@nestjs/common';
import { Global, Module } from '@nestjs/common';
