function onaborted() {
  if (done) return;
  done = true;
  var err = new Error('Request aborted');
  err.code = 'ECONNABORTED';
  callback(err);
}

function onend() {
  if (done) return;
  done = true;
  callback();
}

function onfinish(err) {
  if (err && err.code === 'ECONNRESET') return onaborted();
  if (err) return onerror(err);
  if (done) return;
  setImmediate(function () {
    if (streaming !== false && !done) {
      onaborted();
      return;
    }
    if (done) return;
    done = true;
    callback();
  });
}

function onstream() {
  streaming = true;
}

