    this.registerService
      .save({ login, email, password, langKey: this.translateService.getCurrentLang() ?? 'en' })
      .subscribe({ next: () => this.success.set(true), error: response => this.processError(response) });
  } else {
    this.doNotMatch.set(true);
  }
}

