constructor(
  public activated: boolean,
  public authorities: string[],
  public email: string,
  public firstName: string | null,
  public langKey: string,
  public lastName: string | null,
  public login: string,
  public imageUrl: string | null,
) {}

private readonly userIdentity = signal<Account | null>(null);
// eslint-disable-next-line @typescript-eslint/member-ordering
readonly account = this.userIdentity.asReadonly();
private accountCache$?: Observable<Account> | null;
private readonly translateService = inject(TranslateService);
private readonly http = inject(HttpClient);
private readonly stateStorageService = inject(StateStorageService);
private readonly router = inject(Router);
save(account: Account): Observable<{}> {
  return this.http.post(`${serverApiUrl}api/account`, account);
}

authenticate(identity: Account | null): void {
  this.userIdentity.set(identity);
  if (!identity) {
    this.accountCache$ = null;
  }
}

identity(force?: boolean): Observable<Account | null> {
  if (!this.accountCache$ || force) {
    this.accountCache$ = this.fetch().pipe(
      tap((account: Account) => {
        this.authenticate(account);
        // After retrieve the account info, the language will be changed to
        // the user's preferred language configured in the account setting
        // unless user have chosen another language in the current session
        if (account.langKey && !this.stateStorageService.getLocale()) {
          this.translateService.use(account.langKey);
        }
        this.navigateToStoredUrl();
      }),
      shareReplay(),
    );
  }
  return this.accountCache$.pipe(catchError(() => of(null)));
}

private fetch(): Observable<Account> {
  return this.http.get<Account>(`${serverApiUrl}api/account`);
}

private navigateToStoredUrl(): void {
  // previousState can be set in the authExpiredInterceptor and in the userRouteAccessService
  // if login is successful, go to stored previousState and clear previousState
  const previousUrl = this.stateStorageService.getUrl();
  if (previousUrl) {
    this.stateStorageService.clearUrl();
    this.router.navigateByUrl(previousUrl);
  }
}

logout(): Observable<void> {
  return new Observable(observer => {
    this.stateStorageService.clearAuthenticationToken();
    observer.complete();
  });
}

private authenticateSuccess(response: JwtToken, rememberMe: boolean): void {
  this.stateStorageService.storeAuthenticationToken(response.id_token, rememberMe);
}

private readonly previousUrlKey = 'previousUrl';
private readonly authenticationKey = AUTHENTICATION_TOKEN_KEY;
private readonly localeKey = 'locale';

storeUrl(url: string): void {
  sessionStorage.setItem(this.previousUrlKey, JSON.stringify(url));
}

storeAuthenticationToken(authenticationToken: string, rememberMe: boolean): void {
  authenticationToken = JSON.stringify(authenticationToken);
  this.clearAuthenticationToken();
  if (rememberMe) {
    localStorage.setItem(this.authenticationKey, authenticationToken);
  } else {
    sessionStorage.setItem(this.authenticationKey, authenticationToken);
  }
}

getAuthenticationToken(): string | null {
  const authenticationToken = localStorage.getItem(this.authenticationKey) ?? sessionStorage.getItem(this.authenticationKey);
  return authenticationToken ? (JSON.parse(authenticationToken) as string | null) : authenticationToken;
}

storeLocale(locale: string): void {
  sessionStorage.setItem(this.localeKey, locale);
}

getLocale(): string | null {
  return sessionStorage.getItem(this.localeKey);
}

export const userRouteAccessService: CanActivateFn = (next: ActivatedRouteSnapshot, state: RouterStateSnapshot) => {
  const accountService = inject(AccountService);
  const router = inject(Router);
  const stateStorageService = inject(StateStorageService);
  return accountService.identity().pipe(
    map(account => {
      if (account) {
        const { authorities } = next.data;
        if (!authorities?.length || accountService.hasAnyAuthority(authorities)) {
          return true;
        }
        if (isDevMode()) {
          console.error('User does not have any of the required authorities:', authorities);
        }
        router.navigate(['accessdenied']);
        return false;
      }
      stateStorageService.storeUrl(state.url);
      router.navigate(['/login']);
      return false;
    }),
  );
};

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const stateStorageService = inject(StateStorageService);
  if (!req.url || (req.url.startsWith('http') && !(serverApiUrl && req.url.startsWith(serverApiUrl)))) {
    return next(req);
  }
  const token = stateStorageService.getAuthenticationToken();
  if (token) {
    req = req.clone({
      setHeaders: {
        Authorization: `Bearer ${token}`,
      },
    });
  }
  return next(req);
};

export const notificationInterceptor: HttpInterceptorFn = (req, next) => {
  const alertService = inject(AlertService);
  return next(req).pipe(
    tap((event: HttpEvent<any>) => {
      if (event instanceof HttpResponse) {
        const headers = Object.fromEntries(event.headers.keys().map(key => [key, event.headers.getAll(key)]));
        const message = getMessageFromHeaders(headers);
        if (message.alertKey) {
          alertService.addAlert({
            type: 'success',
            translationKey: message.alertKey,
            translationParams: { param: message.param },
          });
        } else if (message.alertMessage) {
          alertService.addAlert({
            type: 'success',
            message: message.alertMessage,
          });
        }
      }
    }),
  );
};

