readonly operationsResource = httpResource<RestOperation[]>(() => {
  const params = this.operationsParams();
  if (!params) {
    return undefined;
  }
  return { url: this.resourceUrl, params };
});

protected readonly http = inject(HttpClient);
create(operation: NewOperation): Observable<IOperation> {
  const copy = this.convertValueFromClient(operation);
  return this.http.post<RestOperation>(this.resourceUrl, copy).pipe(map(res => this.convertResponseFromServer(res)));
}
update(operation: IOperation): Observable<IOperation> {
  const copy = this.convertValueFromClient(operation);
  return this.http
    .put<RestOperation>(`${this.resourceUrl}/${encodeURIComponent(this.getOperationIdentifier(operation))}`, copy)
    .pipe(map(res => this.convertResponseFromServer(res)));
}
partialUpdate(operation: PartialUpdateOperation): Observable<IOperation> {
  const copy = this.convertValueFromClient(operation);
  return this.http
    .patch<RestOperation>(`${this.resourceUrl}/${encodeURIComponent(this.getOperationIdentifier(operation))}`, copy)
    .pipe(map(res => this.convertResponseFromServer(res)));
}
find(id: number): Observable<IOperation> {
  return this.http
    .get<RestOperation>(`${this.resourceUrl}/${encodeURIComponent(id)}`)
    .pipe(map(res => this.convertResponseFromServer(res)));
}
query(req?: any): Observable<HttpResponse<IOperation[]>> {
  const options = createRequestOption(req);
  return this.http
    .get<RestOperation[]>(this.resourceUrl, { params: options, observe: 'response' })
    .pipe(map(res => res.clone({ body: this.convertResponseArrayFromServer(res.body!) })));
}
delete(id: number): Observable<undefined> {
  return this.http.delete<undefined>(`${this.resourceUrl}/${encodeURIComponent(id)}`);
}
getOperationIdentifier(operation: Pick<IOperation, 'id'>): number {
  return operation.id;
}
compareOperation(o1: Pick<IOperation, 'id'> | null, o2: Pick<IOperation, 'id'> | null): boolean {
  return o1 && o2 ? this.getOperationIdentifier(o1) === this.getOperationIdentifier(o2) : o1 === o2;
}
addOperationToCollectionIfMissing<Type extends Pick<IOperation, 'id'>>(
  operationCollection: Type[],
  ...operationsToCheck: (Type | null | undefined)[]
): Type[] {
  const operations: Type[] = operationsToCheck.filter(operationItem => operationItem !== null && operationItem !== undefined);
  if (operations.length > 0) {
    const operationCollectionIdentifiers = operationCollection.map(operationItem => this.getOperationIdentifier(operationItem));
    const operationsToAdd = operations.filter(operationItem => {
      const operationIdentifier = this.getOperationIdentifier(operationItem);
      if (operationCollectionIdentifiers.includes(operationIdentifier)) {
        return false;
      }
      operationCollectionIdentifiers.push(operationIdentifier);
      return true;
    });
    return [...operationsToAdd, ...operationCollection];
  }
  return operationCollection;
}

compareOperation(o1: Pick<IOperation, 'id'> | null, o2: Pick<IOperation, 'id'> | null): boolean {
  return o1 && o2 ? this.getOperationIdentifier(o1) === this.getOperationIdentifier(o2) : o1 === o2;
}

import { Service } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import dayjs from 'dayjs/esm';
import { DATE_TIME_FORMAT } from 'app/config';
import { IOperation, NewOperation } from '../operation.model';
/**
 * A partial Type with required key is used as form input.
 */
type PartialWithRequiredKeyOf<T extends { id: unknown }> = Partial<Omit<T, 'id'>> & { id: T['id'] };
/**
 * Type for createFormGroup and resetForm argument.
 * It accepts IOperation for edit and NewOperationFormGroupInput for create.
 */
type OperationFormGroupInput = IOperation | PartialWithRequiredKeyOf<NewOperation>;
/**
 * Type that converts some properties for forms.
 */
type FormValueOf<T extends IOperation | NewOperation> = Omit<T, 'date'> & {
  date?: string | null;
};
type OperationFormRawValue = FormValueOf<IOperation>;
type NewOperationFormRawValue = FormValueOf<NewOperation>;
type OperationFormDefaults = Pick<NewOperation, 'id' | 'date' | 'labels'>;
type OperationFormGroupContent = {
  id: FormControl<OperationFormRawValue['id'] | NewOperation['id']>;
  date: FormControl<OperationFormRawValue['date']>;
  description: FormControl<OperationFormRawValue['description']>;
  amount: FormControl<OperationFormRawValue['amount']>;
  bankAccount: FormControl<OperationFormRawValue['bankAccount']>;
  labels: FormControl<OperationFormRawValue['labels']>;
};

createOperationFormGroup(operation?: OperationFormGroupInput): OperationFormGroup {
  const operationRawValue = this.convertOperationToOperationRawValue({
    ...this.getFormDefaults(),
    ...(operation ?? { id: null }),
  });
  return new FormGroup<OperationFormGroupContent>({
    id: new FormControl(
      { value: operationRawValue.id, disabled: true },
      {
        nonNullable: true,
        validators: [Validators.required],
      },
    ),
    date: new FormControl(operationRawValue.date, {
      validators: [Validators.required],
    }),
    description: new FormControl(operationRawValue.description),
    amount: new FormControl(operationRawValue.amount, {
      validators: [Validators.required],
    }),
    bankAccount: new FormControl(operationRawValue.bankAccount),
    labels: new FormControl(operationRawValue.labels ?? []),
  });
}

getOperation(form: OperationFormGroup): IOperation | NewOperation {
  return this.convertOperationRawValueToOperation(form.getRawValue());
}

resetForm(form: OperationFormGroup, operation: OperationFormGroupInput): void {
  const operationRawValue = this.convertOperationToOperationRawValue({ ...this.getFormDefaults(), ...operation });
  form.reset({
    ...operationRawValue,
    id: { value: operationRawValue.id, disabled: true },
  });
}

private convertOperationRawValueToOperation(rawOperation: OperationFormRawValue | NewOperationFormRawValue): IOperation | NewOperation {
  return {
    ...rawOperation,
    date: dayjs(rawOperation.date, DATE_TIME_FORMAT),
  };
}

