export function provideTranslation(): (Provider | EnvironmentProviders)[] {
  return [
    provideTranslateService({
      loader: {
        provide: TranslateLoader,
        useFactory: translatePartialLoader,
      },
      missingTranslationHandler: {
        provide: MissingTranslationHandler,
        useFactory: missingTranslationHandler,
      },
    }),
    provideAppInitializer(() => {
      const translateService = inject(TranslateService);
      const stateStorageService = inject(StateStorageService);
      translateService.setFallbackLang('en');
      // if the user has changed the language and navigates away from the application and back to it, then use the previously chosen language
      const langKey = stateStorageService.getLocale() ?? 'en';
      translateService.use(langKey);
    }),
  ];
}

/**
 * @param params  Contains parameters for component:
 *                    page          Current page number
 *                    totalItems    Total number of items
 *                    itemsPerPage  Number of items per page
 */
readonly params = input<{
  page?: number;
  totalItems?: number;
  itemsPerPage?: number;
}>();
readonly first = computed(() => {
  const params = this.params();
  if (params?.page && params.totalItems !== undefined && params.itemsPerPage) {
    return (params.page - 1) * params.itemsPerPage + 1;
  }
  return undefined;
});
readonly second = computed(() => {
  const params = this.params();
  if (params?.page && params.totalItems !== undefined && params.itemsPerPage) {
    return Math.min(params.page * params.itemsPerPage, params.totalItems);
  }
  return undefined;
});
readonly total = computed(() => this.params()?.totalItems);

