private async runWebpack(
  configuration: Required<Configuration>,
  appName: string | undefined,
  options: Record<string, any>,
  pathToTsconfig: string,
  debug: boolean,
  watchMode: boolean,
  onSuccess: (() => void) | undefined,
  assetsManager: AssetsManager,
) {
  const { WebpackCompiler } =
    await import('../lib/compiler/webpack-compiler.js');
  const webpackCompiler = new WebpackCompiler(this.pluginsLoader);
  const webpackPath =
    getWebpackConfigPath(configuration, options, appName) ??
    defaultWebpackConfigFilename;
  const webpackConfigFactoryOrConfig =
    await this.getWebpackConfigFactoryByPath(
      webpackPath,
      defaultWebpackConfigFilename,
    );
  return webpackCompiler.run(
    configuration,
    pathToTsconfig,
    appName,
    {
      options,
      webpackConfigFactoryOrConfig,
      debug,
      watchMode,
      assetsManager,
    },
    onSuccess,
  );
}

private async getWebpackConfigFactoryByPath(
  webpackPath: string,
  defaultPath: string,
): Promise<WebpackCompilerExtras['webpackConfigFactoryOrConfig']> {
  return loadBuilderConfig(webpackPath, defaultPath);
}

private async runRspack(
  configuration: Required<Configuration>,
  appName: string | undefined,
  options: Record<string, any>,
  pathToTsconfig: string,
  tsOptions: TsConfigProviderOutput['options'],
  debug: boolean,
  watchMode: boolean,
  onSuccess: (() => void) | undefined,
  assetsManager: AssetsManager,
) {
  const { RspackCompiler } =
    await import('../lib/compiler/rspack-compiler.js');
  const rspackCompiler = new RspackCompiler(this.pluginsLoader);
  const rspackPath =
    getRspackConfigPath(configuration, options, appName) ??
    defaultRspackConfigFilename;
  const rspackConfigFactoryOrConfig = await this.getRspackConfigFactoryByPath(
    rspackPath,
    defaultRspackConfigFilename,
  );
  return rspackCompiler.run(
    configuration,
    pathToTsconfig,
    appName,
    {
      options,
      rspackConfigFactoryOrConfig,
      debug,
      watchMode,
      tsOptions,
      assetsManager,
    },
    onSuccess,
  );
}

private warnOnIgnoredLibraryAssets(
  configuration: Required<Configuration>,
  appNames: (string | undefined)[],
) {
  if (!configuration.projects) {
    return;
  }
  // A library whose assets any of the apps being built opts into via
  // `includeLibraryAssets` *is* copied, so warning about it would be wrong.
  const includedLibraries = new Set<string>();
  for (const appName of appNames) {
    const included =
      getValueOrDefault<string[]>(
        configuration,
        'compilerOptions.includeLibraryAssets',
        appName,
      ) || [];
    for (const libraryName of included) {
      includedLibraries.add(libraryName);
    }
  }
  for (const [projectName, project] of Object.entries(
    configuration.projects,
  )) {
    if (
      appNames.includes(projectName) ||
      includedLibraries.has(projectName)
    ) {
      continue;
    }
    if (
      project.type === 'library' &&
      project.compilerOptions?.assets?.length
    ) {
      console.warn(
        INFO_PREFIX +
          ` Assets configured for library "${projectName}" will not be copied during application build.` +
          ` Add it to "compilerOptions.includeLibraryAssets" or build the library separately.`,
      );
    }
  }
}

import { confirm } from '@inquirer/prompts';
import { red } from 'ansis';
import { DeployCommandContext } from '../commands/index.js';
import { PackageManagerFactory } from '../lib/package-managers/index.js';
import { MauRunner } from '../lib/runners/mau.runner.js';
import { ERROR_PREFIX, INFO_PREFIX, MESSAGES } from '../lib/ui/index.js';
import { gracefullyExitOnPromptError } from '../lib/utils/gracefully-exit-on-prompt-error.js';
import { isInteractive } from '../lib/utils/is-interactive.js';
import { MAU_PACKAGE_NAME, findMauBinary } from '../lib/utils/mau.js';
import { AbstractAction } from './abstract.action.js';
const INSTALL_COMMAND = `npm install --save-dev ${MAU_PACKAGE_NAME}`;

public async handle(context: DeployCommandContext) {
  const binaryPath = findMauBinary() ?? (await this.installMau());
  const runner = new MauRunner(binaryPath);
  // Not collected: mau owns the terminal from here on, so its output and
  // any prompts it shows must reach the user directly.
  await runner.run(['deploy', ...context.args].join(' '));
}

private async installMau(): Promise<string> {
  if (!isInteractive()) {
    console.error(
      `\n${ERROR_PREFIX} ${MESSAGES.MAU_NOT_INSTALLED_NON_INTERACTIVE(
        MAU_PACKAGE_NAME,
        INSTALL_COMMAND,
      )}`,
    );
    throw new Error(MESSAGES.MAU_INSTALLATION_FAILED(MAU_PACKAGE_NAME));
  }
  const shouldInstall = await confirm({
    message: MESSAGES.MAU_INSTALLATION_QUESTION(MAU_PACKAGE_NAME),
    default: true,
  }).catch(gracefullyExitOnPromptError);
  if (!shouldInstall) {
    console.error(
      `\n${ERROR_PREFIX} ${MESSAGES.MAU_INSTALLATION_DECLINED(
        MAU_PACKAGE_NAME,
        INSTALL_COMMAND,
      )}`,
    );
    throw new Error(MESSAGES.MAU_INSTALLATION_FAILED(MAU_PACKAGE_NAME));
  }
  console.info(
    `${INFO_PREFIX} ${MESSAGES.MAU_INSTALLATION_IN_PROGRESS(MAU_PACKAGE_NAME)}`,
  );
  try {
    const manager = await PackageManagerFactory.find();
    await manager.addDevelopment([MAU_PACKAGE_NAME], 'latest');
  } catch (error) {
    if (error instanceof Error && error.message) {
      console.error(red(error.message));
    }
    throw new Error(MESSAGES.MAU_INSTALLATION_FAILED(MAU_PACKAGE_NAME));
  }
  // Resolve again rather than assuming a path: the package manager decides
  // where the package physically lands.
  const binaryPath = findMauBinary();
  if (!binaryPath) {
    throw new Error(MESSAGES.MAU_INSTALLATION_FAILED(MAU_PACKAGE_NAME));
  }
  return binaryPath;
}

