  }
  const processArgs = [outputFilePath, ...childProcessArgs];
  if (debug) {
    const inspectFlag =
      typeof debug === 'string' ? `--inspect=${debug}` : '--inspect';
    processArgs.unshift(inspectFlag);
  }
  if (options.envFile && options.envFile.length > 0) {
    const envFileNodeArgs = options.envFile
      .filter(envFileExists)
      .map((envFilePath) => `--env-file=${envFilePath}`);
    processArgs.unshift(...envFileNodeArgs);
  }
  processArgs.unshift('--enable-source-maps');
  const spawnOptions: SpawnOptions = {
    stdio: 'inherit',
    shell: options.shell,
  };
  if (options.shell) {
    const command = [binaryToRun, ...processArgs].join(' ');
    return spawn(command, spawnOptions);
  }
  return spawn(binaryToRun, processArgs, spawnOptions);
}

import { green, red } from 'ansis';
import { UpgradeCommandContext } from '../commands/index.js';
import {
  AbstractCollection,
  Collection,
  CollectionFactory,
  SchematicOption,
} from '../lib/schematics/index.js';
import { INFO_PREFIX, MESSAGES } from '../lib/ui/index.js';
import { isInteractive } from '../lib/utils/is-interactive.js';
import { loadConfiguration } from '../lib/utils/load-configuration.js';
import {
  hasObserveDependency,
  offerObserveLink,
  printObservabilityNextSteps,
} from '../lib/utils/observe-link.js';
import { AbstractAction } from './abstract.action.js';
const schematicName = 'upgrade';

public async handle(context: UpgradeCommandContext) {
  const configuration = await loadConfiguration();
  const collectionName =
    context.collection || configuration.collection || Collection.NESTJS;
  const schematicOptions = this.mapSchematicOptions(context);
  const hadObserve = hasObserveDependency();
  console.info(MESSAGES.UPGRADE_IN_PROGRESS);
  try {
    const collection: AbstractCollection =
      CollectionFactory.create(collectionName);
    await collection.execute(schematicName, schematicOptions);
  } catch (error) {
    if (error instanceof Error) {
      console.error(red(error.message));
    }
    throw error;
  }
  if (context.dryRun) {
    console.info();
    console.info(green(MESSAGES.DRY_RUN_MODE));
    console.info();
    return;
  }
  // The schematic only bumps the project's local @nestjs/cli.
  console.info(`\n${INFO_PREFIX} ${MESSAGES.UPGRADE_GLOBAL_CLI_HINT}\n`);
  // The schematic wired @nestjs/observe in if asked to, reading the key pair
  // from the environment. Offer to fetch that pair now, the same way
  // `nest new` does, instead of leaving a wired agent with no key.
  if (!hadObserve && hasObserveDependency()) {
    const linked = !context.skipInstall && (await offerObserveLink('.'));
    if (!linked) {
      printObservabilityNextSteps(MESSAGES.OBSERVABILITY_UPGRADE_KEYS_HINT);
    }
  }
}

private mapSchematicOptions(
  context: UpgradeCommandContext,
): SchematicOption[] {
  const options: SchematicOption[] = [];
  if (context.dryRun) options.push(new SchematicOption('dry-run', true));
  if (context.skipInstall) {
    options.push(new SchematicOption('skip-install', true));
  }
  if (context.tag !== undefined) {
    options.push(new SchematicOption('tag', context.tag));
  }
  if (context.observe !== undefined) {
    options.push(new SchematicOption('observe', context.observe));
  } else if (!isInteractive()) {
    // The schematic's `x-prompt` would block forever without a TTY (CI,
    // pipes), so answer it up front and leave prompting to TTY sessions.
    options.push(new SchematicOption('observe', false));
  }
  return options;
}

public load(program: Command): void {
  program
    .command('add <library>')
    .allowUnknownOption()
    // Unknown options are collected into `args`, which commander otherwise
    // rejects as excess arguments — that would break the documented
    // library-specific options this command forwards via `extraFlags`.
    .allowExcessArguments()
    .description('Adds support for an external library to your project.')
    .option(
      '-d, --dry-run',
      'Report actions that would be performed without writing out results.',
    )
    .option('-s, --skip-install', 'Skip package installation.', false)
    .option('-p, --project [project]', 'Project in which to generate files.')
    .usage('<library> [options] [library-specific-options]')
    .action(
      async (
        library: string,
        options: Record<string, any>,
        command: Command,
      ) => {
        const context: AddCommandContext = {
          library,
          dryRun: !!options.dryRun,
          skipInstall: options.skipInstall,
          project: options.project,
          extraFlags: getRemainingFlags(command),
        };
        try {
          await this.action.handle(context);
        } catch {
          process.exit(1);
        }
      },
    );
}

