constructor(
  pluginsLoader: PluginsLoader,
  private readonly tsConfigProvider: TsConfigProvider,
  private readonly typescriptLoader: TypeScriptBinaryLoader,
) {
  super(pluginsLoader);
}

public run(
  configuration: Required<Configuration>,
  tsConfigPath: string,
  appName: string | undefined,
  _extras: unknown,
  onSuccess?: () => void,
) {
  const tsBinary = this.typescriptLoader.load();
  const formatHost: ts.FormatDiagnosticsHost = {
    getCanonicalFileName: (path) => path,
    getCurrentDirectory: tsBinary.sys.getCurrentDirectory,
    getNewLine: () => tsBinary.sys.newLine,
  };
  const { options, fileNames, projectReferences } =
    this.tsConfigProvider.getByConfigFilename(tsConfigPath);
  const createProgram =
    tsBinary.createIncrementalProgram || tsBinary.createProgram;
  const program = createProgram.call(ts, {
    rootNames: fileNames,
    projectReferences,
    options,
  });
  const plugins = this.loadPlugins(configuration, tsConfigPath, appName);
  const tsconfigPathsPlugin = tsconfigPathsBeforeHookFactory(options);
  const programRef = program.getProgram
    ? program.getProgram()
    : (program as any as ts.Program);
  const before = plugins.beforeHooks.map((hook) => hook(programRef));
  const after = plugins.afterHooks.map((hook) => hook(programRef));
  const afterDeclarations = plugins.afterDeclarationsHooks.map((hook) =>
    hook(programRef),
  );
  const emitResult = program.emit(
    undefined,
    undefined,
    undefined,
    undefined,
    {
      before: tsconfigPathsPlugin ? [tsconfigPathsPlugin, ...before] : before,
      after,
      afterDeclarations: tsconfigPathsPlugin
        ? [tsconfigPathsPlugin, ...afterDeclarations]
        : afterDeclarations,
    },
  );
  const errorsCount = this.reportAfterCompilationDiagnostic(
    program as any,
    emitResult,
    tsBinary,
    formatHost,
  );
  if (errorsCount) {
    throw new Error(`Found ${errorsCount} compilation error(s).`);
  } else if (onSuccess) {
    onSuccess();
  }
}

private reportAfterCompilationDiagnostic(
  program: ts.EmitAndSemanticDiagnosticsBuilderProgram,
  emitResult: ts.EmitResult,
  tsBinary: typeof ts,
  formatHost: ts.FormatDiagnosticsHost,
): number {
  const diagnostics = tsBinary
    .getPreEmitDiagnostics(program as unknown as ts.Program)
    .concat(emitResult.diagnostics);
  if (diagnostics.length > 0) {
    console.error(
      tsBinary.formatDiagnosticsWithColorAndContext(diagnostics, formatHost),
    );
  }
  return diagnostics.length;
}

export function getPackageName(request: string): string | undefined {
  if (
    request.startsWith('.') ||
    request.startsWith('node:') ||
    isAbsolute(request)
  ) {
    return undefined;
  }
  const parts = request.split('/');
  return request.startsWith('@') ? parts.slice(0, 2).join('/') : parts[0];
}

export function findPackageDir(name: string, from: string): string | undefined {
  let dir = from;
  for (;;) {
    const candidate = join(dir, 'node_modules', name);
    if (existsSync(join(candidate, 'package.json'))) {
      return candidate;
    }
    const parent = dirname(dir);
    if (parent === dir) {
      return undefined;
    }
    dir = parent;
  }
}

export function isMissingOptionalPackage(
  request: string,
  from = process.cwd(),
): boolean {
  const name = getPackageName(request);
  if (!name || !optionalPackages.includes(name)) {
    return false;
  }
  return !findPackageDir(name, from);
}

function readPackageJson(dir: string): Record<string, any> | undefined {
  try {
    return JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'));
  } catch {
    return undefined;
  }
}

function isNativePackage(dir: string, pkg: Record<string, any>): boolean {
  return (
    pkg.gypfile === true ||
    existsSync(join(dir, 'binding.gyp')) ||
    hasNodeFile(dir) ||
    hasPlatformDependency(dir, pkg)
  );
}

export function findExternalPackages(
  cwd = process.cwd(),
  exclude: string[] = [],
): ExternalPackage[] {
  const root = readPackageJson(cwd);
  if (!root) {
    return [];
  }
  const externalPackages = new Map<string, ExternalPackage>();
  const otherVersions = new Map<string, Set<string>>();
  const visited = new Set<string>();
  const queue: Array<{ names: string[]; from: string }> = [
    {
      names: Object.keys({
        ...root.dependencies,
        ...root.optionalDependencies,
      }),
      from: cwd,
    },
  ];
  while (queue.length) {
    const { names, from } = queue.shift()!;
    for (const name of names) {
      // pnpm links packages into `node_modules`, and their dependencies are
      // only found next to the real directory
      const found = findPackageDir(name, from);
      const dir = found && realpathSync(found);
      if (!dir || visited.has(dir)) {
        continue;
      }
      visited.add(dir);
      const pkg = readPackageJson(dir);
      if (!pkg) {
        continue;
      }
      if (
        exclude.includes(name) ||
        runtimeFilePackages.includes(name) ||
        isNativePackage(dir, pkg)
      ) {

): ExternalPackage[] {
      visited.add(dir);
      const pkg = readPackageJson(dir);
      if (!pkg) {
        continue;
      }
      if (
        exclude.includes(name) ||
        runtimeFilePackages.includes(name) ||
        isNativePackage(dir, pkg)
      ) {
        const pinned = externalPackages.get(name);
        if (!pinned) {
          externalPackages.set(name, {
            name,
            version: pkg.version,
            ...((pkg.os || pkg.cpu) && { optional: true }),
          });
        } else if (pinned.version !== pkg.version) {
          otherVersions.set(
            name,
            (otherVersions.get(name) ?? new Set()).add(pkg.version),
          );
        }
        continue;
      }
      queue.push({
        names: Object.keys({
          ...pkg.dependencies,
          ...pkg.optionalDependencies,
        }),
        from: dir,
      });
    }
  }
  for (const [name, versions] of otherVersions) {
    const { version } = externalPackages.get(name)!;
    console.warn(
      INFO_PREFIX +
        ` "${name}" is installed in several versions. package.json pins ${version}, ` +
        `the one closest to the project, not ${[...versions].join(', ')}.`,

): ExternalPackage[] {
        from: dir,
      });
    }
  }
  for (const [name, versions] of otherVersions) {
    const { version } = externalPackages.get(name)!;
    console.warn(
      INFO_PREFIX +
        ` "${name}" is installed in several versions. package.json pins ${version}, ` +
        `the one closest to the project, not ${[...versions].join(', ')}.`,
    );
  }
  return [...externalPackages.values()].sort((a, b) =>
    a.name.localeCompare(b.name),
  );
}

export function createBundleExternals(
  isEsm: boolean,
  externalPackages: ExternalPackage[],
) {
  const externalNames = new Set(externalPackages.map(({ name }) => name));
  const type = isEsm ? 'node-commonjs' : 'commonjs';
  return (
    { request }: { request?: string },
    callback: (error?: Error | null, result?: string) => void,
  ) => {
    if (!request) {
      return callback();
    }
    const isBuiltin =
      request.startsWith('node:') || builtinModules.includes(request);
    const name = getPackageName(request);
    if (isBuiltin || (name && externalNames.has(name))) {
      return callback(null, `${type} ${request}`);
    }
    callback();
  };
}

isEsm: boolean;
externalPackages: ExternalPackage[];
/** Collects the optional packages that were ignored in this compilation. */
ignored: Set<string>;

apply(compiler: any) {
  const { isEsm, externalPackages, ignored } = this.options;
  const name = 'NestBundleDependenciesPlugin';
  const { Compilation, sources } = compiler.rspack;
  compiler.hooks.thisCompilation.tap(name, (compilation: any) => {
    ignored.clear();
    compilation.hooks.processAssets.tap(
      { name, stage: Compilation.PROCESS_ASSETS_STAGE_ADDITIONAL },
      () => {
        const pin = (optional: boolean) =>
          Object.fromEntries(
            externalPackages
              .filter((pkg) => !!pkg.optional === optional)
              .map((pkg) => [pkg.name, pkg.version]),
          );
        const optionalDependencies = pin(true);
        const manifest = {
          private: true,
          type: isEsm ? 'module' : 'commonjs',
          dependencies: pin(false),
          ...(Object.keys(optionalDependencies).length > 0 && {
            optionalDependencies,
          }),
        };
        compilation.emitAsset(
          'package.json',
          new sources.RawSource(JSON.stringify(manifest, null, 2) + '\n'),
        );
      },
    );
  });
  compiler.hooks.done.tap(name, (stats: any) => {
    if (stats.hasErrors()) {
      return;
    }
    const list = (items: string[]) => (items.length ? items.join(', ') : '-');
    console.log(
      `${INFO_PREFIX} Dependencies are bundled.\n` +
        `  optional packages not installed, ignored: ${list([...ignored].sort())}\n` +
        `  packages kept external, pinned in package.json: ${list(
          externalPackages.map(({ name, version }) => `${name}@${version}`),
        )}\n` +
        `  run "npm install --omit=dev" in the output directory to install them`,
    );
  });
}

export function isMissingLazyImport(resource: string): boolean {
  if (!lazyImports.includes(resource)) {
    return false;
  }
  try {
    require.resolve(resource, {
      paths: [process.cwd()],
    });
  } catch {
    return true;
  }
  return false;
}

import { builtinModules, createRequire } from 'module';
import { join } from 'path';
import type * as ts from 'typescript';
import type nodeExternals from 'webpack-node-externals';
import type { CompilerOptions } from '../../configuration/index.js';
import { defaultTsconfigFilename } from '../../configuration/defaults.js';
import {
  BundleDependenciesPlugin,
  createBundleExternals,
  findExternalPackages,
  isMissingOptionalPackage,
} from './bundle-dependencies.js';
import { appendTsExtension } from '../helpers/append-extension.js';
import { MultiNestCompilerPlugins } from '../plugins/plugins-loader.js';
import { isMissingLazyImport } from './lazy-imports.js';
const require = createRequire(import.meta.url);

function loadRspackDeps() {
  try {
    const rspack = require('@rspack/core');
    const externals = require('webpack-node-externals') as typeof nodeExternals;
    return { nodeExternals: externals, rspack };
  } catch (e: any) {
    if (e?.code !== 'MODULE_NOT_FOUND' && e?.code !== 'ERR_MODULE_NOT_FOUND') {
      // Only the "package missing" branch is wrapped with install advice.
      // Surfacing unrelated errors as "package not found" would mislead
      // users into reinstalling perfectly valid dependencies.
      throw e;
    }
    // Use a non-greedy match so error messages that contain multiple
    // quoted paths (e.g. ESM "Cannot find package 'foo' imported from
    // '/abs/path.mjs'") still extract the package name rather than the
    // importing file path.
    const pkg =
      e?.message?.match?.(/Cannot find.*?'([^']+)'/)?.[1] ??
      'webpack-node-externals';
    throw new Error(
      `The "${pkg}" package is required when using the rspack compiler but could not be found. ` +
        `Please install it:\n\n  npm install --save-dev @rspack/core webpack-node-externals\n`,
      { cause: e },
    );
  }
}

export const rspackDefaultsFactory = (
  sourceRoot: string,
  relativeSourceRoot: string,
  entryFilename: string,
  isDebugEnabled = false,
  tsConfigFile = defaultTsconfigFilename,
  // builtin:swc-loader cannot run the TypeScript transformers of CLI plugins
  _plugins: MultiNestCompilerPlugins,
  isEsm = false,
  tsOptions?: ts.CompilerOptions,
  bundleDependenciesOption: CompilerOptions['bundleDependencies'] = false,
  typeCheck = false,
): Record<string, any> => {
  const { nodeExternals: externals } = loadRspackDeps();
  const sourceMaps =
    tsOptions?.sourceMap || (tsOptions?.inlineSourceMap && 'inline');
  const devtool =
    sourceMaps === 'inline'
      ? 'inline-source-map'
      : sourceMaps
        ? 'source-map'
        : false;
  const bundleDependencies = !!bundleDependenciesOption;
  const externalPackages = bundleDependencies
    ? findExternalPackages(
        process.cwd(),
        typeof bundleDependenciesOption === 'object'
          ? bundleDependenciesOption.exclude
          : undefined,
      )
    : [];
  const ignoredOptionalPackages = new Set<string>();

const rspackConfiguration: Record<string, any> = {
  entry: appendTsExtension(join(sourceRoot, entryFilename)),
  devtool,
  target: 'node',
  output: {
    filename: join(relativeSourceRoot, `${entryFilename}.js`).replace(
      /\\/g,
      '/',
    ),
    ...(isEsm && {
      module: true,
      library: { type: 'module' },
      chunkFormat: 'module',
      chunkLoading: 'import',
    }),
    ...(!isEsm && { library: { type: 'commonjs2' } }),
  },

...(isEsm && {
  experiments: { outputModule: true, topLevelAwait: true },
}),
ignoreWarnings: [/^(?!CriticalDependenciesWarning$)/],
externals: bundleDependencies
  ? [createBundleExternals(isEsm, externalPackages)]
  : [
      externals(isEsm ? { importType: 'module' } : {}) as any,
      ...(isEsm
        ? [
            ({ request }: { request?: string }, callback: Function) => {
              if (!request) return callback();
              const bare = request.startsWith('node:')
                ? request.slice(5)
                : request;
              if (builtinModules.includes(bare)) {
                return callback(null, `module ${request}`);
              }
              callback();
            },

          ]
        : []),
    ],
externalsPresets: { node: !isEsm && !bundleDependencies },
module: {
  // ESM dependencies load CommonJS peers through `createRequire(import.meta.url)`;
  // left unparsed, those requires resolve from the build machine at runtime
  ...(bundleDependencies && {
    parser: { javascript: { createRequire: true } },
  }),
  rules: [
    {
      test: /\.tsx?$/,
      use: [
        {
          loader: 'builtin:swc-loader',
          options: {
            jsc: {
              parser: {
                syntax: 'typescript',
                decorators: true,
              },
              transform: {
                legacyDecorator: true,
                decoratorMetadata: true,
              },
              target: 'es2021',
            },
            sourceMaps,
          },
        },
      ],
      exclude: /node_modules/,
      ...(isEsm && { type: 'javascript/esm' as const }),
    },
  ],
},
resolve: {
  extensions: ['.tsx', '.ts', '.js'],
  ...(isEsm && {

      extensionAlias: {
        '.js': ['.ts', '.js'],
        '.mjs': ['.mts', '.mjs'],
      },
    }),
    tsConfig: tsConfigFile,
  },
  mode: 'none',
  optimization: {
    nodeEnv: false,
  },
  node: {
    __filename: false,
    __dirname: false,
  },
  plugins: [],
};
// rspack has built-in IgnorePlugin (compatible with webpack's)
try {
  const rspack = require('@rspack/core');
  rspackConfiguration.plugins!.push(
    new rspack.IgnorePlugin({
      // `context` is the importer's directory: pnpm links the dependencies
      // of a package (`file-type` of `@nestjs/common`) only next to it

checkResource(resource: string, context: string) {
  if (
    !isMissingLazyImport(resource) &&
    !(bundleDependencies && isMissingOptionalPackage(resource, context))
  ) {
    return false;
  }
  ignoredOptionalPackages.add(resource);
  return true;
},

    }),
  );
} catch {
  // @rspack/core not available, skip IgnorePlugin
}
if (bundleDependencies) {
  rspackConfiguration.plugins!.push(
    new BundleDependenciesPlugin({
      isEsm,
      externalPackages,
      ignored: ignoredOptionalPackages,
    }),
  );
}
// builtin:swc-loader only strips types, so the checker runs even when CLI
// plugins are registered (unlike webpack, where ts-loader then checks them).
// With `typeCheck`, the CLI type-checks the program itself instead
if (!typeCheck) {
  try {
    const ForkTsCheckerWebpackPlugin = require('fork-ts-checker-webpack-plugin');
    rspackConfiguration.plugins!.push(
      new ForkTsCheckerWebpackPlugin({
        typescript: {
          configFile: tsConfigFile,
        },
      }),
    );
  } catch {
    // fork-ts-checker-webpack-plugin not available, skip
  }
}

export const swcDefaultsFactory = (
  tsOptions?: ts.CompilerOptions,
  configuration?: Configuration,
  tsConfigExclude: string[] = [],
  appName?: string,
) => {
  const builder = configuration
    ? getValueOrDefault<Builder | undefined>(
        configuration as Required<Configuration>,
        'compilerOptions.builder',
        appName,
      )
    : undefined;
  const builderOptions =
    typeof builder === 'object' && builder?.type === 'swc'
      ? (builder.options ?? {})
      : {};
  const esm = resolveSwcModuleType(tsOptions) === 'es6';
  // In a monorepo the root "sourceRoot" is the default project's, so reading
  // it directly makes every other project compile the default project's
  // sources into its own outDir. Resolve it per application, the way the rest
  // of the compiler does.
  const sourceRoot = configuration
    ? (getValueOrDefault<string | undefined>(
        configuration as Required<Configuration>,
        'sourceRoot',
        appName,
        'sourceRoot',
      ) ?? 'src')
    : 'src';
  return {
    swcOptions: {
      sourceMaps:
        tsOptions?.sourceMap || (tsOptions?.inlineSourceMap && 'inline'),
      module: esm
        ? {
            type: 'es6',
            // Node's ESM resolver requires full specifiers, so give the ones
            // swc rewrites from "paths" (and any extensionless relative ones)
            // the extension of the emitted file, or "/index.js" for directories.

) => {
  return {
    swcOptions: {
      sourceMaps:
        tsOptions?.sourceMap || (tsOptions?.inlineSourceMap && 'inline'),
      module: esm
        ? {
            type: 'es6',
            // Node's ESM resolver requires full specifiers, so give the ones
            // swc rewrites from "paths" (and any extensionless relative ones)
            // the extension of the emitted file, or "/index.js" for directories.
            resolveFully: true,
          }
        : {
            type: 'commonjs',
          },
      jsc: {
        target: 'es2021',
        parser: {
          syntax: 'typescript',
          decorators: true,
          dynamicImport: true,
        },
        transform: {
          legacyDecorator: true,
          decoratorMetadata: true,
          useDefineForClassFields: false,
        },
        keepClassNames: true,
        baseUrl: resolveBaseUrl(tsOptions),
        paths: tsOptions?.paths,
        // swc drops import attributes by default, but Node needs
        // `with { type: 'json' }` to import JSON from ES modules.
        ...(esm && { experimental: { keepImportAttributes: true } }),
      },
      minify: false,
      swcrc: true,
    },
    cliOptions: {
      outDir: tsOptions?.outDir ? convertPath(tsOptions.outDir) : 'dist',
      filenames: [sourceRoot],

) => {
        // swc drops import attributes by default, but Node needs
        // `with { type: 'json' }` to import JSON from ES modules.
        ...(esm && { experimental: { keepImportAttributes: true } }),
      },
      minify: false,
      swcrc: true,
    },
    cliOptions: {
      outDir: tsOptions?.outDir ? convertPath(tsOptions.outDir) : 'dist',
      filenames: [sourceRoot],
      sync: false,
      extensions: ['.js', '.ts'],
      copyFiles: false,
      includeDotfiles: false,
      ignore: tsConfigExclude.length ? tsConfigExclude : undefined,
      quiet: false,
      watch: false,
      stripLeadingPaths: shouldStripLeadingPaths(
        tsOptions?.rootDir,
        sourceRoot,
      ),
      ...builderOptions,
    },
  };
};

export function resolveSwcModuleType(
  tsOptions?: ts.CompilerOptions,
  esmPackage = isEsmProject(),
): 'es6' | 'commonjs' {
  if (!esmPackage) {
    return 'commonjs';
  }
  const moduleKind = tsOptions?.module;
  if (moduleKind !== undefined && moduleKind < ts.ModuleKind.ES2015) {
    return 'commonjs';
  }
  return 'es6';
}

function resolveBaseUrl(tsOptions?: ts.CompilerOptions): string | undefined {
  if (tsOptions?.baseUrl || !tsOptions?.paths) {
    return tsOptions?.baseUrl;
  }
  const pathsBasePath = tsOptions.pathsBasePath;
  return typeof pathsBasePath === 'string' ? pathsBasePath : undefined;
}

function shouldStripLeadingPaths(
  rootDir: string | undefined,
  sourceRoot: string,
): boolean {
  const normalizedSourceRoot = convertPath(sourceRoot)
    .replace(/^\.\//, '')
    .replace(/\/+$/, '');
  if (normalizedSourceRoot.includes('/')) {
    return false;
  }
  if (!rootDir) {
    return true;
  }
  const normalizedRootDir = convertPath(rootDir).replace(/\/+$/, '');
  return (
    normalizedRootDir === normalizedSourceRoot ||
    normalizedRootDir.endsWith(`/${normalizedSourceRoot}`)
  );
}

function convertPath(windowsPath: string) {
  return windowsPath
    .replace(/^\\\\\?\\/, '')
    .replace(/\\/g, '/')
    .replace(/\/\/+/g, '/');
}

function withInstallAdvice<T>(load: () => T): T {
  try {
    return load();
  } catch (e: any) {
    if (e?.code !== 'MODULE_NOT_FOUND' && e?.code !== 'ERR_MODULE_NOT_FOUND') {
      // Only the "package missing" branch is wrapped with install advice.
      // Surfacing unrelated errors as "package not found" would mislead
      // users into reinstalling perfectly valid dependencies.
      throw e;
    }
    // Use a non-greedy match so error messages that contain multiple
    // quoted paths (e.g. ESM "Cannot find package 'foo' imported from
    // '/abs/path.mjs'") still extract the package name rather than the
    // importing file path.
    const pkg =
      e?.message?.match?.(/Cannot find.*?'([^']+)'/)?.[1] ?? 'webpack';
    throw new Error(
      `The "${pkg}" package is required when using the webpack compiler but could not be found. ` +
        `Please install it:\n\n  npm install --save-dev webpack webpack-node-externals tsconfig-paths-webpack-plugin ts-loader fork-ts-checker-webpack-plugin\n`,
      { cause: e },
    );
  }
}

function loadWebpackDeps() {
  return withInstallAdvice(() => {
    const wp = require('webpack') as typeof webpack;
    const externals = require('webpack-node-externals') as typeof nodeExternals;
    const { TsconfigPathsPlugin } =
      require('tsconfig-paths-webpack-plugin') as {
        TsconfigPathsPlugin: typeof TsconfigPathsPluginType;
      };
    return { webpack: wp, nodeExternals: externals, TsconfigPathsPlugin };
  });
}

function getBaseUrl(tsConfigFile: string) {
  try {
    const { compilerOptions } = JSON.parse(readFileSync(tsConfigFile, 'utf8'));
    return compilerOptions?.baseUrl ?? '.';
  } catch {
    return '.';
  }
}

export const webpackDefaultsFactory = (
  sourceRoot: string,
  relativeSourceRoot: string,
  entryFilename: string,
  isDebugEnabled = false,
  tsConfigFile = defaultTsconfigFilename,
  plugins: MultiNestCompilerPlugins,
): webpack.Configuration => {
  const {
    webpack: wp,
    nodeExternals: externals,
    TsconfigPathsPlugin,
  } = loadWebpackDeps();
  const isPluginRegistered = isAnyPluginRegistered(plugins);
  const webpackConfiguration: webpack.Configuration = {
    entry: appendTsExtension(join(sourceRoot, entryFilename)),
    devtool: isDebugEnabled ? 'inline-source-map' : false,
    target: 'node',
    output: {
      filename: join(relativeSourceRoot, `${entryFilename}.js`).replace(
        /\\/g,
        '/',
      ),
      library: { type: 'commonjs2' },
    },
    ignoreWarnings: [/^(?!CriticalDependenciesWarning$)/],
    externals: [externals() as any],
    externalsPresets: { node: true },
    module: {
      rules: [
        {
          test: /.tsx?$/,
          use: [
            {
              loader: 'ts-loader',
              options: {
                transpileOnly: !isPluginRegistered,
                configFile: tsConfigFile,
                getCustomTransformers: (program: any) => ({
                  before: plugins.beforeHooks.map((hook: any) => hook(program)),

): webpack.Configuration => {
        {
          test: /.tsx?$/,
          use: [
            {
              loader: 'ts-loader',
              options: {
                transpileOnly: !isPluginRegistered,
                configFile: tsConfigFile,
                getCustomTransformers: (program: any) => ({
                  before: plugins.beforeHooks.map((hook: any) => hook(program)),
                  after: plugins.afterHooks.map((hook: any) => hook(program)),
                  afterDeclarations: plugins.afterDeclarationsHooks.map(
                    (hook: any) => hook(program),
                  ),
                }),
              },
            },
          ],
          exclude: /node_modules/,
        },
      ],
    },
    resolve: {
      extensions: ['.tsx', '.ts', '.js'],
      plugins: [
        new TsconfigPathsPlugin({
          configFile: tsConfigFile,
          baseUrl: getBaseUrl(tsConfigFile),
        }),
      ],
    },
    mode: 'none',
    optimization: {
      nodeEnv: false,
    },
    node: {
      __filename: false,
      __dirname: false,
    },
    plugins: [

): webpack.Configuration => {
    },
    mode: 'none',
    optimization: {
      nodeEnv: false,
    },
    node: {
      __filename: false,
      __dirname: false,
    },
    plugins: [
      new wp.IgnorePlugin({
        checkResource: isMissingLazyImport,
      }),
    ],
  };
  if (!isPluginRegistered) {
    const ForkTsCheckerWebpackPlugin = withInstallAdvice(() =>
      require('fork-ts-checker-webpack-plugin'),
    );
    webpackConfiguration.plugins!.push(
      new ForkTsCheckerWebpackPlugin({
        typescript: {
          configFile: tsConfigFile,
        },
      }),
    );
  }
  return webpackConfiguration;
};

function isAnyPluginRegistered(plugins: MultiNestCompilerPlugins) {
  return (
    (plugins.afterHooks && plugins.afterHooks.length > 0) ||
    (plugins.beforeHooks && plugins.beforeHooks.length > 0) ||
    (plugins.afterDeclarationsHooks &&
      plugins.afterDeclarationsHooks.length > 0)
  );
}

export function appendTsExtension(path: string): string {
  return extname(path) === '.ts' ? path : path + '.ts';
}

hasErrors(): boolean;
toString(options: {
  chunks: boolean;
  colors: boolean;
  modules: boolean;
  assets: boolean;
}): string;

bundlerName: string;
onSuccess: (() => void) | undefined;
assetsManager: AssetsManager;
watchMode: boolean;
watch: boolean | undefined;
onComplete?: BundlerCallbackCompletion;

/**
 * Creates the completion callback shared by `RspackCompiler` and
 * `WebpackCompiler` for both `compiler.run()` and `compiler.watch()`.
 */
export function createBundlerAfterCallback({
  bundlerName,
  onSuccess,
  assetsManager,
  watchMode,
  watch,
  onComplete,
}: BundlerAfterCallbackOptions) {

const closeWatchersSafely = async () => {
  try {
    await assetsManager.closeWatchers();
  } catch (error: unknown) {
    console.error(
      `${ERROR_PREFIX} Failed to close asset watchers. ` +
        `${error instanceof Error ? error.message : String(error)}`,
    );
  }
};

return (err: Error | null | undefined, stats: BundlerStats | undefined) => {
  const isWatch = watchMode || !!watch;
  if (err && stats === undefined) {
    // Could not complete the compilation
    // The error caught is most likely thrown by underlying tasks
    console.log(err);
    if (isWatch) {
      // Both webpack and rspack stop watching without re-arming after a
      // fatal watch error; exit so watch mode does not stay up dead.
      return process.exit(1);
    }
    if (!onSuccess) {
      void closeWatchersSafely().finally(() => onComplete?.reject(err));
    } else {
      onComplete?.reject(err);
    }
    return;
  }
  const statsOutput = stats!.toString({
    chunks: false,
    colors: true,
    modules: false,
    assets: false,
  });
  if (!err && !stats!.hasErrors()) {
    if (onSuccess) {
      onSuccess();
    }
    console.log(statsOutput);
    if (!onSuccess && !isWatch) {
      // Bundlers ignore whatever this callback returns, so the close is
      // handled here while resolving the outer non-watch Promise once done.
      void closeWatchersSafely().finally(() => onComplete?.resolve());
    } else {
      onComplete?.resolve();
    }
    return;
  }
  console.log(statsOutput);
  if (!isWatch) {
    const failure = err ?? new Error(`${bundlerName} compilation failed.`);
    if (!onSuccess) {
      void closeWatchersSafely().finally(() => onComplete?.reject(failure));
    } else {
      onComplete?.reject(failure);
    }
  }
};

export function copyPathResolve(filePath: string, outDir: string, up: number) {
  return path.join(outDir, dealWith(filePath, up));
}

function dealWith(inPath: string, up: number) {
  if (!up) {
    return inPath;
  }
  if (depth(inPath) < up - 1) {
    throw new Error('Path outside of project folder is not allowed');
  }
  return path.join(...path.normalize(inPath).split(path.sep).slice(up));
}

function depth(string: string) {
  return path.normalize(string).split(path.sep).length - 1;
}

import { rm } from 'fs/promises';
import * as ts from 'typescript';
import { Configuration } from '../../configuration/index.js';
import { getValueOrDefault } from './get-value-or-default.js';
import {
  areOutsidePathsAllowed,
  assertPathInsideProject,
} from './path-confinement.js';
/**
 * A recursive delete is not atomic: it walks the tree, and anything created
 * between the "readdir" of a directory and its "rmdir" makes the removal fail
 * with ENOTEMPTY. Concurrent writers into "outDir" are common in monorepos
 * (a sibling "tsc --noEmit --incremental" dropping its buildinfo there, for
 * instance), which turns "deleteOutDir" into a flaky build. Node already
 * treats ENOTEMPTY - along with EBUSY, EMFILE, ENFILE and EPERM, the errors
 * Windows raises for a file another process still holds - as retryable, but
 * only retries when "maxRetries" is set; it defaults to 0.
 *
 * See https://github.com/nestjs/nest-cli/issues/3509
 */
const RM_MAX_RETRIES = 3;

export async function deleteOutDirIfEnabled(
  configuration: Required<Configuration>,
  appName: string | undefined,
  dirPath: string,
  tsOptions?: ts.CompilerOptions,
) {
  const isDeleteEnabled = getValueOrDefault<boolean>(
    configuration,
    'compilerOptions.deleteOutDir',
    appName,
  );
  if (!isDeleteEnabled) {
    return;
  }
  const shouldValidate = !areOutsidePathsAllowed(configuration, appName);
  // With "incremental" enabled but no explicit "tsBuildInfoFile", TypeScript
  // derives a default location that can fall outside "outDir" (with "outDir"
  // and "rootDir" both set, "tsconfig.build.tsbuildinfo" lands next to the
  // tsconfig), so the recursive delete below would leave it behind. Reuse the
  // compiler's own resolution to remove the buildinfo wherever it actually is.
  const tsBuildInfoFile =
    tsOptions &&
    (tsOptions.tsBuildInfoFile ??
      ts.getTsBuildInfoEmitOutputFilePath(tsOptions));
  // Both paths are validated before anything is removed, so that a rejected
  // "tsBuildInfoFile" cannot leave a half-deleted output directory behind.
  const outDirToDelete = shouldValidate
    ? assertPathInsideProject(dirPath, 'outDir')
    : dirPath;
  const tsBuildInfoFileToDelete =
    shouldValidate && tsBuildInfoFile
      ? assertPathInsideProject(tsBuildInfoFile, 'tsBuildInfoFile')
      : tsBuildInfoFile;
  await rm(outDirToDelete, {
    recursive: true,
    force: true,
    maxRetries: RM_MAX_RETRIES,
  });
  if (tsBuildInfoFileToDelete) {
    await rm(tsBuildInfoFileToDelete, {
      force: true,
      maxRetries: RM_MAX_RETRIES,
    });
  }
}

import {
  AVAILABLE_BUILDERS,
  Builder,
  BuilderVariant,
  Configuration,
} from '../../configuration/index.js';
import { getValueOrDefault } from './get-value-or-default.js';

function isValidBuilderVariant(value: unknown): value is BuilderVariant {
  return (
    typeof value === 'string' &&
    (AVAILABLE_BUILDERS as readonly string[]).includes(value)
  );
}

export function getBuilder(
  configuration: Required<Configuration>,
  cmdOptions: Record<string, any>,
  appName: string | undefined,
): Exclude<Builder, string> {
  const builderValue = getValueOrDefault<unknown>(
    configuration,
    'compilerOptions.builder',
    appName,
    'builder',
    cmdOptions,
    'tsc',
  );
  const normalized =
    typeof builderValue === 'string'
      ? { type: builderValue }
      : typeof builderValue === 'object' &&
          builderValue !== null &&
          !Array.isArray(builderValue)
        ? (builderValue as Record<string, unknown>)
        : undefined;
  if (!normalized || !isValidBuilderVariant(normalized.type)) {
    const projectSuffix =
      appName !== undefined ? ` for project "${appName}"` : '';
    const detail =
      typeof builderValue === 'string'
        ? `"${builderValue}"`
        : JSON.stringify(builderValue);
    throw new Error(
      `Invalid builder ${detail}${projectSuffix}. Available builders: ${AVAILABLE_BUILDERS.join(', ')}.`,
    );
  }
  return normalized as Exclude<Builder, string>;
}

export function getEffectiveRootDir(
  explicitRootDir: string | undefined,
  fileNames: readonly string[] | undefined,
  cwd: string = process.cwd(),
): string | undefined {
  if (explicitRootDir) {
    return normalize(
      isAbsolute(explicitRootDir)
        ? explicitRootDir
        : resolve(cwd, explicitRootDir),
    );
  }
  if (!fileNames || fileNames.length === 0) {
    return undefined;
  }
  // Declaration files are excluded from the common source directory, matching
  // TypeScript: they produce no emit, so a `typings/**/*.d.ts` entry outside
  // `src` must not drag the computed root up to the project root and push
  // every copied asset into a `dist/src` subdirectory.
  const emittedFiles = fileNames.filter((file) => !isDeclarationFileName(file));
  if (emittedFiles.length === 0) {
    return undefined;
  }
  const absolutePaths = emittedFiles.map((file) =>
    normalize(isAbsolute(file) ? file : resolve(cwd, file)),
  );
  let commonDir = dirname(absolutePaths[0]);
  for (let i = 1; i < absolutePaths.length; i++) {
    commonDir = commonParentDir(commonDir, dirname(absolutePaths[i]));
    if (!commonDir) {
      return undefined;
    }
  }
  return commonDir;
}

function isDeclarationFileName(fileName: string): boolean {
  return /\.d\.[cm]?ts$/i.test(fileName);
}

function commonParentDir(a: string, b: string): string {
  const aSegments = a.split(sep);
  const bSegments = b.split(sep);
  const length = Math.min(aSegments.length, bSegments.length);
  let i = 0;
  while (i < length && aSegments[i] === bSegments[i]) {
    i++;
  }
  return aSegments.slice(0, i).join(sep);
}

export function getRspackConfigPath(
  configuration: Required<Configuration>,
  cmdOptions: Record<string, any>,
  appName: string | undefined,
) {
  if (cmdOptions?.rspackPath) {
    return cmdOptions.rspackPath as string;
  }
  const builder = getValueOrDefault<Builder>(
    configuration,
    'compilerOptions.builder',
    appName,
  );
  const rspackPath =
    typeof builder === 'object' && builder?.type === 'rspack'
      ? builder.options?.configPath
      : undefined;
  return rspackPath;
}

export function getTscConfigPath(
  configuration: Required<Configuration>,
  cmdOptions: Record<string, any>,
  appName: string | undefined,
) {
  let tsconfigPath = getValueOrDefault<string | undefined>(
    configuration,
    'compilerOptions.tsConfigPath',
    appName,
    'path',
    cmdOptions,
  );
  if (tsconfigPath) {
    return tsconfigPath;
  }
  const builder = getValueOrDefault<Builder>(
    configuration,
    'compilerOptions.builder',
    appName,
  );
  tsconfigPath =
    typeof builder === 'object' && builder?.type === 'tsc'
      ? builder.options?.configPath
      : undefined;
  return tsconfigPath ?? getDefaultTsconfigPath();
}

import { Configuration } from '../../configuration/index.js';
export function getValueOrDefault<T = any>(
  configuration: Required<Configuration>,
  propertyPath: string,
  appName: string | undefined,
  key?:
    | 'path'
    | 'webpack'
    | 'webpackPath'
    | 'entryFile'
    | 'sourceRoot'
    | 'exec'
    | 'builder'
    | 'typeCheck'
    | 'emitDeclarations'
    | 'bundleDependencies',
  options: Record<string, any> = {},
  defaultValue?: T,
): T {
  const origValue = key != null ? (options[key] as unknown as T) : undefined;
  if (origValue !== undefined && origValue !== null) {
    return origValue as T;
  }
  if (configuration.projects && configuration.projects[appName as string]) {
    // Wrap the application name in double-quotes to prevent splitting it
    // into separate chunks
    appName = appName && !appName.includes('"') ? `"${appName}"` : appName;

    const perAppValue = getValueOfPath(
      configuration,
      `projects.${appName}.`.concat(propertyPath),
    );
    if (perAppValue !== undefined) {
      return perAppValue as T;
    }
  }
  let value = getValueOfPath(configuration, propertyPath);
  if (value === undefined) {
    value = defaultValue;
  }
  return value;
}

export function getValueOfPath<T = any>(
  object: Record<string, any>,
  propertyPath: string,
): T {
  const fragments = propertyPath.split('.');
  let propertyValue = object;
  let isConcatInProgress = false;
  let path = '';
  for (const fragment of fragments) {
    if (!propertyValue) {
      break;
    }
    /**
     * When path is escaped with "" double quotes,
     * concatenate the property path.
     * Reference: https://github.com/nestjs/nest-cli/issues/947
     */
    if (fragment.startsWith('"') && fragment.endsWith('"')) {
      path = stripDoubleQuotes(fragment);
    } else if (fragment.startsWith('"')) {
      path += stripDoubleQuotes(fragment) + '.';
      isConcatInProgress = true;
      continue;
    } else if (isConcatInProgress && !fragment.endsWith('"')) {
      path += fragment + '.';
      continue;
    } else if (fragment.endsWith('"')) {
      path += stripDoubleQuotes(fragment);
      isConcatInProgress = false;
    } else {
      path = fragment;
    }
    propertyValue = propertyValue[path];
    path = '';
  }
  return propertyValue as T;
}

function stripDoubleQuotes(text: string) {
  return text.replace(/"/g, '');
}

export function getWebpackConfigPath(
  configuration: Required<Configuration>,
  cmdOptions: Record<string, any>,
  appName: string | undefined,
) {
  let webpackPath = getValueOrDefault<string | undefined>(
    configuration,
    'compilerOptions.webpackConfigPath',
    appName,
    'webpackPath',
    cmdOptions,
  );
  if (webpackPath) {
    return webpackPath;
  }
  const builder = getValueOrDefault<Builder>(
    configuration,
    'compilerOptions.builder',
    appName,
  );
  if (typeof builder === 'object' && builder?.type === 'webpack') {
    const webpackConfigPath = builder.options?.configPath;
    if (webpackConfigPath) {
      return webpackConfigPath;
    }
    // If builder.type is 'webpack' but no config path is specified, return undefined
    // to let webpack use its default behavior
    return undefined;
  }
  return undefined;
}

/** A single glob pattern; every path matching it is removed from the result. */
ignore?: string;
/** When true, `*` and `**` also match entries whose name starts with a dot. */
dot?: boolean;

/** Absolute path, always `/`-separated regardless of platform. */
path: string;
isFile: boolean;
isDirectory: boolean;

/**
 * Characters that make a path segment a pattern rather than a literal, under
 * minimatch's default options (no extglob).
 *
 * Matches the literal chars `*`, `?`, `[`, `{` anywhere, plus `!`, `+`, `@`,
 * `?`, or `*` immediately followed by `(` (an extglob-looking prefix, which
 * minimatch still treats specially even without extglob enabled). Chars like
 * `@`, `(`, `)`, `]`, `}` on their own are NOT magic here: treating them as
 * such previously collapsed the literal base far above the real directory
 * (e.g. an `@` in a username segment), causing `readdir` to walk huge trees
 * and silently return no matches on the first unreadable subdirectory.
 */
const MAGIC_CHARS = /[*?[{]|[!+@?*]\(/;
const toPosix = (value: string): string => value.replace(/\\/g, '/');
/**
 * Splits a pattern into the literal prefix we can hand to `readdir` and the
 * trailing segments that still need matching: `/src/a/*.hbs` -> `/src/a`.
 */
export function splitPattern(pattern: string): {
  base: string;
  rest: string[];
} {
  const segments = pattern.split('/');
  const magicIndex = segments.findIndex((segment) => MAGIC_CHARS.test(segment));
  if (magicIndex === -1) {
    return { base: pattern, rest: [] };
  }
  return {
    base: segments.slice(0, magicIndex).join('/') || '/',
    rest: segments.slice(magicIndex),
  };
}

function expandGlobstarSuffix(pattern: string): string[] {
  return pattern.endsWith('/**') ? [pattern, pattern.slice(0, -3)] : [pattern];
}

/** Always `/`-separated. */
parent: string;
entry: Dirent;

function symlinkDepthBudget(rest: string[]): number {
  for (let index = rest.length - 1; index >= 0; index--) {
    if (rest[index].includes('**')) {
      return rest.length - index - 1;
    }
  }
  return rest.length;
}

function walk(
  dir: string,
  recursive: boolean,
  budget: number,
  depth = 0,
): WalkedEntry[] {
  let entries: Dirent[];
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    // Unreadable or missing directory: contribute nothing here, but let
    // sibling directories elsewhere in the walk still report their matches.
    return [];
  }
  const results: WalkedEntry[] = entries.map((entry) => ({
    parent: dir,
    entry,
  }));
  if (!recursive) {
    return results;
  }
  for (const entry of entries) {
    const full = `${dir}/${entry.name}`;
    // Below a symlink every further level costs budget; above one, plain
    // directory recursion is unbounded.
    if (entry.isDirectory()) {
      const childDepth = depth === 0 ? 0 : depth + 1;
      if (childDepth <= budget) {
        results.push(...walk(full, true, budget, childDepth));
      }
      continue;
    }
    // `Dirent.isDirectory()` is false for a symlink (it reports on the link
    // itself), so a symlinked directory only ever reaches this branch.
    if (entry.isSymbolicLink() && depth + 1 <= budget) {
      let stats;
      try {
        stats = statSync(full);
      } catch {
        continue;
      }
      if (stats.isDirectory()) {
        results.push(...walk(full, true, budget, depth + 1));
      }
    }
  }
  return results;
}

/**
 * Expands `pattern` to every matching path, with the type of each entry.
 * See the file header for the compatibility rules this preserves.
 */
export function globEntriesSync(
  pattern: string,
  options: GlobSyncOptions = {},
): GlobEntry[] {
  const { ignore, dot = false } = options;
  const normalized = toPosix(pattern);
  const { base, rest } = splitPattern(normalized);
  const includeMatchers = expandGlobstarSuffix(normalized);
  const ignoreMatchers = ignore ? expandGlobstarSuffix(toPosix(ignore)) : [];
  const accept = (candidate: string): boolean =>
    includeMatchers.some((matcher) => minimatch(candidate, matcher, { dot })) &&
    !ignoreMatchers.some((matcher) => minimatch(candidate, matcher, { dot }));
  // No wildcard anywhere: the pattern names one concrete path.
  if (rest.length === 0) {
    const stats = statSync(normalized, { throwIfNoEntry: false });
    if (!stats || !accept(normalized)) {
      return [];
    }
    return [
      {
        path: normalized,
        isFile: stats.isFile(),
        isDirectory: stats.isDirectory(),
      },
    ];
  }

  // Only the immediate children of `base` can match a single trailing
  // wildcard segment, so skip the deep walk in that (common) case.
  const recursive =
    rest.length > 1 || rest.some((segment) => segment.includes('**'));
  // An asset may be configured for a directory that does not exist, or one
  // that turns out to be unreadable; `walk` reports no matches for it (and
  // any nested directories that fail) rather than failing the whole build.
  const walked = walk(base, recursive, symlinkDepthBudget(rest));
  const matches: GlobEntry[] = [];
  // A trailing `**` matches zero segments, so `base` itself can be a result.
  if (accept(base)) {
    matches.push({ path: base, isFile: false, isDirectory: true });
  }
  for (const { parent, entry } of walked) {
    const full = `${toPosix(parent)}/${entry.name}`;
    if (accept(full)) {
      matches.push({
        path: full,
        isFile: entry.isFile(),
        isDirectory: entry.isDirectory(),
      });
    }
  }
  return matches;
}

/** Expands `pattern` to every matching path. */
export function globSync(
  pattern: string,
  options: GlobSyncOptions = {},
): string[] {
  return globEntriesSync(pattern, options).map((entry) => entry.path);
}

export function listenForManualRestart(callback: () => void) {
  const stdinListener = (data: Buffer) => {
    if (data.toString().trim() === 'rs') {
      process.stdin.removeListener('data', stdinListener);
      callback();
    }
  };
  process.stdin.on('data', stdinListener);
}

export function displayManualRestartTip(): void {
  console.log(`To restart at any time, enter ${gray`rs`}.\n`);
}

export function areOutsidePathsAllowed(
  configuration: Required<Configuration>,
  appName: string | undefined,
): boolean {
  return (
    getValueOrDefault<boolean>(
      configuration,
      'compilerOptions.allowOutsidePaths',
      appName,
    ) ?? false
  );
}

/**
 * Resolves `targetPath` against the project directory and asserts that it stays
 * within it. Returns the resolved absolute path.
 *
 * @throws when the path resolves to the project directory itself or escapes it
 */
export function assertPathInsideProject(
  targetPath: string,
  propertyName: string,
  {
    resolveSymlinks = false,
    projectRoot = process.cwd(),
  }: PathConfinementOptions = {},
): string {
  const resolvedPath = resolve(projectRoot, targetPath);
  const comparableRoot = resolveSymlinks
    ? realpathOrClosestExisting(projectRoot)
    : resolve(projectRoot);
  const comparablePath = resolveSymlinks
    ? realpathOrClosestExisting(resolvedPath)
    : resolvedPath;
  const relativePath = relative(comparableRoot, comparablePath);
  const isProjectRoot = relativePath === '';
  const isOutsideProject =
    relativePath === '..' ||
    relativePath.startsWith(`..${sep}`) ||
    isAbsolute(relativePath);

  if (isProjectRoot || isOutsideProject) {
    throw new Error(
      `Refusing to use "${propertyName}" path outside of or equal to the project directory: ${targetPath}. ` +
        `Set "compilerOptions.allowOutsidePaths" to true if this is intentional.`,
    );
  }
  return resolvedPath;
}
/**
 * Resolves symlinks in `targetPath`. Output paths routinely do not exist yet, so
 * the closest existing ancestor is resolved instead and the remaining segments
 * are appended back — enough to catch a symlinked ancestor while still working
 * for a directory that is about to be created.
 */

function realpathOrClosestExisting(targetPath: string): string {
  let current = resolve(targetPath);
  const trailingSegments: string[] = [];
  for (;;) {
    try {
      return resolve(realpathSync(current), ...trailingSegments);
    } catch {
      const parent = dirname(current);
      if (parent === current) {
        // Reached the root without finding an existing path; nothing to resolve.
        return resolve(targetPath);
      }
      trailingSegments.unshift(basename(current));
      current = parent;
    }
  }
}

export function requiresExplicitImportExtensions(
  options: ts.CompilerOptions,
  tsBinary: typeof ts,
): boolean {
  const moduleResolution = getModuleResolution(options, tsBinary);
  return (
    moduleResolution === tsBinary.ModuleResolutionKind.Node16 ||
    moduleResolution === tsBinary.ModuleResolutionKind.NodeNext
  );
}

function getModuleResolution(
  options: ts.CompilerOptions,
  tsBinary: typeof ts,
): ts.ModuleResolutionKind | undefined {
  const { getEmitModuleResolutionKind } = tsBinary as typeof ts & {
    getEmitModuleResolutionKind?: (
      options: ts.CompilerOptions,
    ) => ts.ModuleResolutionKind;
  };
  return typeof getEmitModuleResolutionKind === 'function'
    ? getEmitModuleResolutionKind(options)
    : options.moduleResolution;
}

import { existsSync } from 'fs';
import { dirname, isAbsolute, join, relative, resolve } from 'path';
import * as ts from 'typescript';
import { CLI_ERRORS } from '../../ui/index.js';
import { TypeScriptBinaryLoader } from '../typescript-loader.js';
export type TsConfigProviderOutput = Pick<
  ts.ParsedCommandLine,
  'options' | 'fileNames' | 'projectReferences'
> & {
  exclude: string[];
};

public getByConfigFilename(configFilename: string): TsConfigProviderOutput {
  const configPath = resolve(process.cwd(), configFilename);
  if (!existsSync(configPath)) {
    throw new Error(CLI_ERRORS.MISSING_TYPESCRIPT(configFilename));
  }
  const tsBinary = this.typescriptLoader.load();
  const parsedCmd = tsBinary.getParsedCommandLineOfConfigFile(
    configPath,
    undefined!,
    tsBinary.sys as unknown as ts.ParseConfigFileHost,
  );
  if (!parsedCmd) {
    throw new Error(
      `Could not parse TypeScript configuration file "${configFilename}". Please, ensure that the file contains valid JSON and compiler options.`,
    );
  }
  const { options, fileNames, projectReferences, raw } = parsedCmd;
  const exclude = this.normalizeExclude(
    this.parseExclude(raw?.exclude),
    configPath,
  );
  return { options, fileNames, projectReferences, exclude };
}

private parseExclude(exclude: unknown): string[] {
  const passesTypeValidation =
    Array.isArray(exclude) &&
    exclude.every((item) => typeof item === 'string');
  if (!passesTypeValidation) {
    return [];
  }
  return exclude;
}

private normalizeExclude(exclude: string[], configPath: string): string[] {
  const configDir = dirname(configPath);
  const relativeConfigDir = relative(process.cwd(), configDir);
  return exclude.map((pattern) => {
    const normalized = isAbsolute(pattern)
      ? relative(process.cwd(), pattern)
      : join(relativeConfigDir, pattern);
    return normalized.replace(/\\/g, '/');
  });
}

