const forkedTypeChecker = new ForkedTypeChecker(pluginsLoader);
const applicationName = appName === 'undefined' ? '' : appName;
const options: Partial<Configuration> = {
  sourceRoot,
};
if (applicationName) {
  options.projects = {};
  options.projects[applicationName] = {
    compilerOptions: {
      plugins: JSON.parse(plugins),
    },
  };
} else {
  options.compilerOptions = {
    plugins: JSON.parse(plugins),
  };
}
forkedTypeChecker.run(
  options as unknown as Required<Configuration>,
  tsConfigPath,
  applicationName,
  { watch: true, typeCheck: true },
);

import { cyan } from 'ansis';
import { spawnSync } from 'child_process';
import { readFileSync } from 'fs';
import { stat } from 'fs/promises';
import {
  parse as parseJsonc,
  printParseErrorCode,
  type ParseError,
} from 'jsonc-parser';
import { minimatch } from 'minimatch';
import { createRequire } from 'module';
import * as path from 'path';
import { isAbsolute, join, posix, relative } from 'path';
import { Configuration } from '../../configuration/index.js';
import { ERROR_PREFIX } from '../../ui/index.js';
import { AssetsManager } from '../assets-manager.js';
import { BaseCompiler } from '../base-compiler.js';
import { swcDefaultsFactory } from '../defaults/swc-defaults.js';
import { getValueOrDefault } from '../helpers/get-value-or-default.js';
import type { TsConfigProviderOutput } from '../helpers/tsconfig-provider.js';
import { PluginsLoader } from '../plugins/plugins-loader.js';
import { watchDirectoryRecursively } from '../watchers/recursive-directory-watcher.js';
import { SWC_LOG_PREFIX } from './constants.js';
const require = createRequire(import.meta.url);
export type SwcCompilerExtras = {
  watch: boolean;
  typeCheck: boolean;
  emitDeclarations: boolean;
  assetsManager: AssetsManager;
  tsOptions: TsConfigProviderOutput['options'];
  tsConfigExclude: string[];
  silent?: boolean;
};

public async run(
  configuration: Required<Configuration>,
  tsConfigPath: string,
  appName: string | undefined,
  extras: SwcCompilerExtras,
  onSuccess?: () => void,
) {
  const swcOptions = swcDefaultsFactory(
    extras.tsOptions,
    configuration,
    extras.tsConfigExclude,
    appName,
  );
  const swcrcFilePath = getValueOrDefault<string | undefined>(
    configuration,
    'compilerOptions.builder.options.swcrcPath',
    appName,
  );
  if (extras.watch) {
    if (extras.typeCheck) {
      this.runTypeChecker(configuration, tsConfigPath, appName, extras);
    }
    await this.runSwc(swcOptions, extras, swcrcFilePath);
    if (extras.emitDeclarations) {
      this.emitDeclarations(tsConfigPath);
    }
    if (onSuccess) {
      onSuccess();
      const debounceTime = 150;
      const callback = this.debounce(onSuccess, debounceTime);
      void this.watchFilesInOutDir(swcOptions, callback);
    }
  } else {
    if (extras.typeCheck) {
      await this.runTypeChecker(configuration, tsConfigPath, appName, extras);
    }
    await this.runSwc(swcOptions, extras, swcrcFilePath);
    if (extras.emitDeclarations) {
      this.emitDeclarations(tsConfigPath);
    }
    if (onSuccess) {
      onSuccess();
    }
    await extras.assetsManager?.closeWatchers();
  }
}

private async runSwc(
  options: ReturnType<typeof swcDefaultsFactory>,
  extras: SwcCompilerExtras,
  swcrcFilePath?: string,
) {
  if (this.shouldLogSwcStatus(extras)) {
    process.nextTick(() => console.log(SWC_LOG_PREFIX, cyan('Running...')));
  }
  const swcCli = this.loadSwcCliBinary();
  const swcRcFile = await this.getSwcRcFileContentIfExists(swcrcFilePath);
  const swcOptions = this.deepMerge(options.swcOptions, swcRcFile);
  if (swcOptions?.jsc?.baseUrl && !isAbsolute(swcOptions?.jsc?.baseUrl)) {
    // jsc.baseUrl should be resolved by the caller, if it's passed as an object.
    // https://github.com/swc-project/swc/pull/7827
    const rootDir = process.cwd();
    swcOptions.jsc.baseUrl = path.join(rootDir, swcOptions.jsc.baseUrl);
  }
  const swcCliOpts = {
    ...options,
    swcOptions,
    cliOptions: {
      ...options.cliOptions,
      watch: extras.watch,
    },
  };
  if (extras.watch) {
    // This is required since SWC no longer supports auto-compiling of newly added files in watch mode.
    // We need to watch the source directory and trigger SWC compilation manually.
    await this.watchFilesInSrcDir(options, async (file) => {
      // Transpile newly added file (one-shot: inheriting "watch" here would
      // register one more permanent @swc/cli watcher per added file, and each
      // async invocation constructs a Piscina pool that is never destroyed)
      try {
        await swcCli.default({
          ...swcCliOpts,
          cliOptions: {
            ...swcCliOpts.cliOptions,
            filenames: [file],
            watch: false,
            sync: true,
          },
        });
      } catch {
        // Outside of watch mode "@swc/cli" rejects when a file fails to
        // compile, after having reported the failure itself. Swallow it so
        // that adding a file that does not compile yet does not tear down
        // the watch process.
      }
    });
  }
  await swcCli.default(swcCliOpts);
}

private shouldLogSwcStatus(extras: SwcCompilerExtras): boolean {
  if (extras.silent) {
    return false;
  }
  const npmLogLevel = process.env.npm_config_loglevel?.toLowerCase();
  return npmLogLevel !== 'silent';
}

private loadSwcCliBinary() {
  try {
    return require('@swc/cli/lib/swc/dir');
  } catch {
    console.error(
      ERROR_PREFIX +
        ' Failed to load "@swc/cli" and/or "@swc/core" required packages. Please, make sure to install them as development dependencies.',
    );
    process.exit(1);
  }
}

private getSwcRcFileContentIfExists(swcrcFilePath?: string) {
  const isCustomPath = swcrcFilePath !== undefined;
  const resolvedPath = join(process.cwd(), swcrcFilePath ?? '.swcrc');
  let content: string;
  try {
    content = readFileSync(resolvedPath, 'utf8');
  } catch (err) {
    // Only treat ENOENT on the default `.swcrc` as "no user overrides to
    // merge". Any other read error (EACCES, EISDIR, …) or a missing
    // user-specified `swcrcPath` is a fatal misconfiguration.
    const isMissing = (err as NodeJS.ErrnoException)?.code === 'ENOENT';
    if (isCustomPath || !isMissing) {
      console.error(
        ERROR_PREFIX +
          ` Failed to load "${swcrcFilePath ?? '.swcrc'}". Please, check if the file exists and is readable.`,
      );
      process.exit(1);
    }
    return {};
  }
  // SWC strips a leading UTF-8 BOM before parsing
  // (`s.trim_start_matches('\u{feff}')`), so match that here — otherwise
  // `jsonc-parser` fails with `InvalidSymbol` on files SWC accepts.
  const stripped = content.replace(/^﻿/, '');
  // .swcrc is JSON-with-comments in SWC itself, which uses jsonc_parser
  // with `allow_comments` + `allow_trailing_commas` enabled (see swc's
  // `parse_swcrc` in crates/swc/src/lib.rs). Match that here so we don't
  // silently reject a valid `.swcrc` that carries `//` / `/* */` comments
  // or a trailing comma.
  const errors: ParseError[] = [];
  const parsed = parseJsonc(stripped, errors, { allowTrailingComma: true });
  if (errors.length > 0) {
    const first = errors[0];
    const before = stripped.slice(0, first.offset).split('\n');
    const position = `${before.length}:${before[before.length - 1].length + 1}`;
    console.error(
      ERROR_PREFIX +
        ` Failed to parse "${swcrcFilePath ?? '.swcrc'}": ` +
        `${printParseErrorCode(first.error)} at ${position}. ` +
        `The file must be valid JSON with comments (JSONC).`,
    );
    process.exit(1);
  }
  return parsed ?? {};
}

private deepMerge<T>(target: T, source: T): T {
  if (
    typeof target !== 'object' ||
    target === null ||
    typeof source !== 'object' ||
    source === null
  ) {
    return source;
  }
  if (Array.isArray(target) && Array.isArray(source)) {
    return source.reduce((acc, value, index) => {
      acc[index] = this.deepMerge(target[index], value);
      return acc;
    }, target);
  }
  const merged = { ...target };
  for (const key in source) {
    if (Object.hasOwn(source, key)) {
      if (key in target) {
        merged[key] = this.deepMerge(target[key], source[key]);
      } else {
        merged[key] = source[key];
      }
    }
  }
  return merged;
}

private debounce(callback: () => void, wait: number) {
  let timeout: NodeJS.Timeout;
  return () => {
    clearTimeout(timeout);
    timeout = setTimeout(callback, wait);
  };
}

private async watchFilesInSrcDir(
  options: ReturnType<typeof swcDefaultsFactory>,
  onFileAdded: (file: string) => Promise<unknown>,
) {
  const srcDir = options.cliOptions?.filenames?.[0];
  const isDirectory = await stat(srcDir)
    .then((stats) => stats.isDirectory())
    .catch(() => false);
  if (!srcDir || !isDirectory) {
    // Skip watching if source directory is not a default "src" folder
    // or any other specified directory
    return;
  }
  const extensions = options.cliOptions?.extensions ?? ['.ts'];
  await watchDirectoryRecursively(srcDir, {
    extensions,
    onAdd: async (file) => {
      if (this.isIgnoredBySwc(file, options.cliOptions?.ignore)) {
        return;
      }
      await onFileAdded(file);
    },
  });
}

private isIgnoredBySwc(
  file: string,
  ignore: string[] = [],
  cwd = process.cwd(),
): boolean {
  if (!ignore.length) {
    return false;
  }
  const relativeFile = isAbsolute(file) ? relative(cwd, file) : file;
  const normalizedFile = this.normalizeSwcIgnorePath(relativeFile);
  return ignore.some((pattern) => {
    const normalizedPattern = this.normalizeSwcIgnorePath(pattern);
    return [normalizedPattern, posix.join(normalizedPattern, '**')].some(
      (pattern) => minimatch(normalizedFile, pattern),
    );
  });
}

private normalizeSwcIgnorePath(value: string): string {
  return posix.normalize(value.replace(/\\/g, '/'));
}

private async watchFilesInOutDir(
  options: ReturnType<typeof swcDefaultsFactory>,
  onChange: () => void,
) {
  const dir = isAbsolute(options.cliOptions.outDir!)
    ? options.cliOptions.outDir!
    : join(process.cwd(), options.cliOptions.outDir!);
  await watchDirectoryRecursively(dir, {
    extensions: ['.js', '.mjs'],
    onAdd: onChange,
    onChange: onChange,
  });
}

import { red } from 'ansis';
import ora from 'ora';
import * as ts from 'typescript';
import { TsConfigProvider } from '../helpers/tsconfig-provider.js';
import { TypeScriptBinaryLoader } from '../typescript-loader.js';
import {
  INITIALIZING_TYPE_CHECKER,
  TSC_LOG_ERROR_PREFIX,
  TSC_NO_ERRORS_MESSAGE,
} from './constants.js';

watch?: boolean;
onTypeCheck?: (program: ts.Program) => void;
onProgramInit?: (program: ts.Program) => boolean | void;

private readonly typescriptLoader = new TypeScriptBinaryLoader();
private readonly tsConfigProvider = new TsConfigProvider(
  this.typescriptLoader,
);

public run(
  tsconfigPath: string | undefined,
  options: TypeCheckerHostRunOptions,
) {
  if (!tsconfigPath) {
    throw new Error(
      '"tsconfigPath" is required when "tsProgramRef" is not provided.',
    );
  }
  const tsBinary = this.typescriptLoader.load();
  // Discarding stdin puts the terminal in raw mode, where Ctrl+C sends no
  // SIGINT; the spinner only wraps synchronous work, so it discards nothing.
  const spinner = ora({
    text: INITIALIZING_TYPE_CHECKER,
    discardStdin: false,
  });
  if (options.watch) {
    console.log();
    spinner.start();
    try {
      this.runInWatchMode(tsconfigPath, tsBinary, options);
      spinner.succeed();
    } catch (err) {
      spinner.fail();
      throw err;
    }
    return;
  }
  spinner.start();
  try {
    this.runOnce(tsconfigPath, tsBinary, options);
    spinner.succeed();
  } catch (err) {
    spinner.fail();
    throw err;
  }
}

private runInWatchMode(
  tsconfigPath: string,
  tsBinary: typeof ts,
  options: TypeCheckerHostRunOptions,
) {
  const { options: tsOptions } =
    this.tsConfigProvider.getByConfigFilename(tsconfigPath);
  let builderProgram: ts.WatchOfConfigFile<ts.BuilderProgram> | undefined =
    undefined;
  const reportWatchStatusCallback = (diagnostic: ts.Diagnostic) => {
    if (diagnostic.messageText !== TSC_NO_ERRORS_MESSAGE) {
      if ((diagnostic.messageText as string)?.includes('Found')) {
        console.error(
          TSC_LOG_ERROR_PREFIX,
          red(diagnostic.messageText.toString()),
        );
      }
      return;
    }
    if (!builderProgram) {
      return;
    }
    const tsProgram = builderProgram.getProgram().getProgram();
    options.onTypeCheck?.(tsProgram);
  };
  const host = this.createWatchCompilerHost(
    tsBinary,
    tsconfigPath,
    tsOptions,
    reportWatchStatusCallback,
  );
  builderProgram = tsBinary.createWatchProgram(host);
  process.nextTick(() => {
    options.onProgramInit?.(builderProgram!.getProgram().getProgram());
  });
}

private runOnce(
  tsconfigPath: string,
  tsBinary: typeof ts,
  options: TypeCheckerHostRunOptions,
) {
  const {
    options: tsOptions,
    fileNames,
    projectReferences,
  } = this.tsConfigProvider.getByConfigFilename(tsconfigPath);
  const createProgram =
    tsBinary.createIncrementalProgram ?? tsBinary.createProgram;
  let program = createProgram.call(ts, {
    rootNames: fileNames,
    projectReferences,
    options: tsOptions,
  });
  let programRef = program.getProgram
    ? program.getProgram()
    : (program as any as ts.Program);
  if (options.onProgramInit) {
    const shouldRebuild = options.onProgramInit(programRef);
    const refreshed = this.tsConfigProvider.getByConfigFilename(tsconfigPath);
    if (
      shouldRebuild !== false ||
      refreshed.fileNames.length !== fileNames.length
    ) {
      program = createProgram.call(ts, {
        rootNames: refreshed.fileNames,
        projectReferences: refreshed.projectReferences,
        options: refreshed.options,
      });
      programRef = program.getProgram
        ? program.getProgram()
        : (program as any as ts.Program);
    }
  }
  const diagnostics = tsBinary.getPreEmitDiagnostics(programRef);
  if (diagnostics.length > 0) {
    const formatDiagnosticsHost: ts.FormatDiagnosticsHost = {
      getCanonicalFileName: (path) => path,
      getCurrentDirectory: tsBinary.sys.getCurrentDirectory,
      getNewLine: () => tsBinary.sys.newLine,
    };
    const formattedDiagnostics =
      tsBinary.formatDiagnosticsWithColorAndContext(
        diagnostics,
        formatDiagnosticsHost,
      );
    console.log();
    console.log(formattedDiagnostics);
    throw new Error(
      `Found ${diagnostics.length} type error(s) during compilation.`,
    );
  }
  options.onTypeCheck?.(programRef);
}

private createWatchCompilerHost(
  tsBinary: typeof ts,
  tsConfigPath: string,
  options: ts.CompilerOptions,
  reportWatchStatusCallback: ts.WatchStatusReporter,
) {
  const origDiagnosticReporter = (tsBinary as any).createDiagnosticReporter(
    tsBinary.sys,
    true,
  );
  const tsOptions = {
    ...options,
    preserveWatchOutput: true,
    noEmit: true,
  };
  return tsBinary.createWatchCompilerHost(
    tsConfigPath,
    tsOptions,
    tsBinary.sys,
    undefined,
    origDiagnosticReporter,
    reportWatchStatusCallback,
  );
}

public load(): typeof ts {
  if (this.tsBinary) {
    return this.tsBinary;
  }
  let tsBinary: typeof ts;
  try {
    const tsBinaryPath = require.resolve('typescript', {
      paths: [process.cwd(), ...this.getModulePaths()],
    });
    tsBinary = require(tsBinaryPath);
  } catch {
    throw new Error(
      'TypeScript could not be found! Please, install "typescript" package.',
    );
  }
  this.assertProgrammaticApiIsSupported(tsBinary);
  this.tsBinary = tsBinary;
  return tsBinary;
}

private assertProgrammaticApiIsSupported(tsBinary: typeof ts): void {
  if (typeof tsBinary.getParsedCommandLineOfConfigFile !== 'function') {
    throw new Error(
      CLI_ERRORS.UNSUPPORTED_TYPESCRIPT_VERSION(tsBinary.version),
    );
  }
}

public getModulePaths() {
  const modulePaths = require.resolve.paths('typescript') ?? [];
  const packageDeps = modulePaths.slice(0, 3);
  return [
    ...packageDeps.reverse(),
    ...modulePaths.slice(3, modulePaths.length).reverse(),
  ];
}

