public load(name?: string): Required<Configuration> {
  const cacheEntryKey = `${this.reader.constructor.name}:${name}`;
  const cachedConfig = loadedConfigsCache.get(cacheEntryKey);
  if (cachedConfig) {
    return cachedConfig;
  }
  let loadedConfig: Required<Configuration> = defaultConfiguration;
  const contentOrError = name
    ? this.reader.read(name)
    : this.reader.readAnyOf(['nest-cli.json', '.nest-cli.json']);
  if (contentOrError) {
    const isMissingPermissionsError =
      contentOrError instanceof ReaderFileLackPermissionsError;
    if (isMissingPermissionsError) {
      console.error(contentOrError.message);
      process.exit(1);
    }
    const configFilename = name ?? 'nest-cli.json';
    let fileConfig: Configuration;
    try {
      fileConfig = JSON.parse(contentOrError);
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      throw new Error(
        `Could not parse Nest CLI configuration file "${configFilename}". Please, ensure that the file contains valid JSON. Reason: ${reason}`,
      );
    }
    loadedConfig = {
      ...defaultConfiguration,
      ...fileConfig,
    };
    if (fileConfig.compilerOptions) {
      loadedConfig.compilerOptions = {
        ...defaultConfiguration.compilerOptions,
        ...fileConfig.compilerOptions,
      };
    }
    if (fileConfig.generateOptions) {
      loadedConfig.generateOptions = {
        ...defaultConfiguration.generateOptions,
        ...fileConfig.generateOptions,
      };
    }
  }
  loadedConfigsCache.set(cacheEntryKey, loadedConfig);
  return loadedConfig;
}

public async install(directory: string, packageManager: string) {
  const spinner = ora({
    spinner: {
      interval: 120,
      frames: ['▹▹▹▹▹', '▸▹▹▹▹', '▹▸▹▹▹', '▹▹▸▹▹', '▹▹▹▸▹', '▹▹▹▹▸'],
    },
    text: MESSAGES.PACKAGE_MANAGER_INSTALLATION_IN_PROGRESS,
  });
  spinner.start();
  try {
    const commandArgs = `${this.cli.install} ${this.cli.silentFlag}`;
    const collect = true;
    await this.runner.run(
      commandArgs,
      collect,
      join(process.cwd(), directory),
    );
    spinner.succeed();
    console.info();
    console.info(MESSAGES.PACKAGE_MANAGER_INSTALLATION_SUCCEED(directory));
    console.info(MESSAGES.GET_STARTED_INFORMATION);
    console.info();
    console.info(gray(MESSAGES.CHANGE_DIR_COMMAND(directory)));
    console.info(gray(MESSAGES.START_COMMAND(packageManager)));
    console.info();
  } catch {
    spinner.fail();
    const commandArgs = this.cli.install;
    const commandToRun = this.runner.rawFullCommand(commandArgs);
    console.error(
      red(MESSAGES.PACKAGE_MANAGER_INSTALLATION_FAILED(bold(commandToRun))),
    );
  }
}

