public async execute(
  name: string,
  options: SchematicOption[],
  extraFlags?: string,
) {
  let command = this.buildCommandLine(name, options);
  command = extraFlags ? command.concat(` ${extraFlags}`) : command;
  await this.runner.run(command);
}

private buildCommandLine(name: string, options: SchematicOption[]): string {
  return `${this.collection}:${name}${this.buildOptions(options)}`;
}

private buildOptions(options: SchematicOption[]): string {
  return options.reduce((line, option) => {
    return line.concat(` ${option.toCommandString()}`);
  }, '');
}

public static create(collection: Collection | string): AbstractCollection {
  const schematicRunner = RunnerFactory.create(
    Runner.SCHEMATIC,
  ) as SchematicRunner;
  if (collection === Collection.NESTJS) {
    return new NestCollection(schematicRunner);
  } else {
    return new CustomCollection(collection, schematicRunner);
  }
}

schema: string;
description: string;
aliases: string[];

public getSchematics(): Schematic[] {
  // Without `resolvePaths`, the workflow resolves collections relative to the
  // CLI's own install rather than the project.
  const workflow = new NodeWorkflow(process.cwd(), {
    resolvePaths: [process.cwd()],
  });
  const collection = workflow.engine.createCollection(this.collection);
  const collectionDescriptions = [
    collection.description,
    ...(collection.baseDescriptions ?? []),
  ];
  const usedNames = new Set<string>();
  const schematics: Schematic[] = [];
  for (const collectionDesc of collectionDescriptions) {
    const schematicsDescs = Object.entries(collectionDesc.schematics);
    for (const [name, { description, aliases = [] }] of schematicsDescs) {
      if (usedNames.has(name)) {
        continue;
      }
      usedNames.add(name);
      const alias = aliases.find((a) => !usedNames.has(a)) ?? name;
      for (const alias of aliases) {
        usedNames.add(alias);
      }
      schematics.push({ name, alias, description });
    }
  }
  return schematics.sort((a, b) =>
    a.name < b.name ? -1 : a.name > b.name ? 1 : 0,
  );
}

