constructor(runner: AbstractRunner) {
  super('@nestjs/schematics', runner);
}

public async execute(
  name: string,
  options: SchematicOption[],
  extraFlags?: string,
) {
  const schematic: string = this.validate(name);
  await super.execute(schematic, options, extraFlags);
}

public getSchematics(): Schematic[] {
  // "upgrade" is executed through "nest update"; it is not offered as a
  // "nest generate" schematic.
  return NestCollection.schematics.filter(
    (item) => item.name !== 'angular-app' && item.name !== 'upgrade',
  );
}

private validate(name: string) {
  const schematic = NestCollection.schematics.find(
    (s) => s.name === name || s.alias === name,
  );
  if (schematic === undefined || schematic === null) {
    throw new Error(
      `Invalid schematic "${name}". Please, ensure that "${name}" exists in this collection.`,
    );
  }
  return schematic.name;
}

export async function getSkippedPrompts(
  collection: string,
  schematic: string,
  options: SchematicOption[],
): Promise<SkippedPrompt[]> {
  try {
    const { NodeWorkflow } =
      await import('@angular-devkit/schematics/tools/index.js');
    // The project's own install first, then the one next to the CLI, the
    // same order the schematics binary resolves collections in.
    const workflow = new NodeWorkflow(process.cwd(), {
      resolvePaths: [process.cwd(), dirname(fileURLToPath(import.meta.url))],
    });
    const { schemaJson } = workflow.engine
      .createCollection(collection)
      .createSchematic(schematic).description;
    const properties = (schemaJson?.properties ?? {}) as Record<
      string,
      Record<string, unknown>
    >;
    const given = new Set(options.map((option) => option.normalizedName));
    return Object.entries(properties)
      .filter(
        ([name, property]) =>
          property['x-prompt'] !== undefined &&
          !given.has(normalizeToKebabOrSnakeCase(name)),
      )
      .map(([name, property]) => ({ name, default: property.default }));
  } catch {
    return [];
  }
}

/** How a skipped prompt was answered, as the flag that answers it the same. */
export function describeSkippedPrompt({
  name,
  default: value,
}: SkippedPrompt): string {
  const flag = `--${normalizeToKebabOrSnakeCase(name)}`;
  if (value === undefined) {
    return `${flag} (the schematic's own default)`;
  }
  if (typeof value === 'boolean') {
    return value ? flag : `--no-${normalizeToKebabOrSnakeCase(name)}`;
  }
  return `${flag} ${String(value)}`;
}

constructor(
  private name: string,
  private value: boolean | string,
) {}

get normalizedName() {
  return normalizeToKebabOrSnakeCase(this.name);
}

public toCommandString(): string {
  if (typeof this.value === 'string') {
    if (this.name === 'name') {
      return `--${this.normalizedName}=${this.format()}`;
    } else if (this.name === 'version' || this.name === 'path') {
      return `--${this.normalizedName}=${this.value}`;
    } else {
      return `--${this.normalizedName}="${this.value}"`;
    }
  } else if (typeof this.value === 'boolean') {
    const str = this.normalizedName;
    // Must stay `=false` rather than `--no-<flag>`: schematics-cli parses
    // with parseArgs under `allowNegative`, which turns `--no-x` into `x`
    // with no value and then coerces it to true — inverting the option.
    return this.value ? `--${str}` : `--${str}=false`;
  } else {
    return `--${this.normalizedName}=${this.value}`;
  }
}

private format() {
  return normalizeToKebabOrSnakeCase(this.value as string)
    .split('')
    .reduce((content, char) => {
      if (char === '(' || char === ')' || char === '[' || char === ']') {
        return `${content}\\${char}`;
      }
      return `${content}${char}`;
    }, '');
}

