export function gracefullyExitOnPromptError(err: Error) {
  if (err.name === 'ExitPromptError') {
    process.exit(1);
  } else {
    throw err;
  }
}

export function isCollectionInstalled(collection: string): boolean {
  // Without `resolvePaths`, the workflow resolves collections relative to the
  // CLI's own install rather than the project.
  const workflow = new NodeWorkflow(process.cwd(), {
    resolvePaths: [process.cwd()],
  });
  try {
    workflow.engine.createCollection(collection);
    return true;
  } catch {
    return false;
  }
}

export function isEsmProject(cwd: string = process.cwd()): boolean {
  try {
    const raw = readFileSync(join(cwd, 'package.json'), 'utf-8');
    const pkg = JSON.parse(raw);
    return pkg.type === 'module';
  } catch {
    return false;
  }
}

export function disablePrompts(disabled = true): void {
  promptsDisabled = disabled;
}

export function isInteractive(): boolean {
  return (
    !promptsDisabled &&
    Boolean(process.stdin.isTTY) &&
    Boolean(process.stdout.isTTY) &&
    !isCI()
  );
}

function isCI(): boolean {
  const ci = process.env.CI;
  return ci !== undefined && ci !== '' && ci !== '0' && ci !== 'false';
}

export async function loadBuilderConfig<T = any>(
  configPath: string,
  defaultPath: string,
  cwd = process.cwd(),
): Promise<T> {
  const pathToConfigFile = join(cwd, configPath);
  // `require.resolve` handles extensionless and directory-index paths, but
  // does not know about ESM-only extensions, hence the `existsSync` fallback.
  const resolvedPath =
    resolveModulePath(pathToConfigFile) ??
    (existsSync(pathToConfigFile) ? pathToConfigFile : undefined);
  if (!resolvedPath) {
    if (configPath === defaultPath) {
      return ((_config: any) => ({})) as T;
    }
    throw new Error(
      `Could not find the builder configuration file "${configPath}".`,
    );
  }
  if (extname(resolvedPath) === '.json') {
    return require(resolvedPath);
  }
  const imported = await import(pathToFileURL(resolvedPath).href);
  const result = imported.default ?? imported;
  // A CommonJS file compiled from TypeScript exposes its real export under a
  // second `default`, behind the `__esModule` marker Node preserves as-is.
  return (isTranspiledEsModule(result) ? result.default : result) as T;
}

function isTranspiledEsModule(
  value: unknown,
): value is { default: unknown; __esModule: true } {

  return (
    !!value &&
    typeof value === 'object' &&
    (value as Record<string, unknown>).__esModule === true &&
    'default' in value
  );
}

export async function loadConfiguration(): Promise<Required<Configuration>> {
  const loader: ConfigurationLoader = new NestConfigurationLoader(
    new FileSystemReader(process.cwd()),
  );
  return loader.load();
}

