> {
  const commandsPath = join(...localBinPathSegments, 'commands', 'index.js');
  const commandsFile = await import(pathToFileURL(commandsPath).href);
  return commandsFile.CommandLoader;
}

import { existsSync, readFileSync } from 'fs';
import { createRequire } from 'module';
import { dirname, join } from 'path';
const require = createRequire(import.meta.url);
export const MAU_PACKAGE_NAME = '@nestjs/mau';
type PackageJsonBin = string | Record<string, string> | undefined;
/**
 * Resolves the `mau` executable shipped by `@nestjs/mau`, looking in the
 * user's project first and then next to the CLI itself.
 *
 * The path comes from the package's own `bin` field rather than a hardcoded
 * `node_modules/.bin/mau`: that shim is absent under pnpm's layout, lives in a
 * parent directory in hoisted monorepos, and is not directly executable on
 * Windows.
 *
 * @returns The absolute path to the executable, or `undefined` when
 * `@nestjs/mau` is not installed.
 */

export function findMauBinary(cwd: string = process.cwd()): string | undefined {
  const searchPaths = [
    cwd,
    join(cwd, 'node_modules'),
    ...(require.resolve.paths(MAU_PACKAGE_NAME) ?? []),
  ];
  let packageJsonPath: string;
  try {
    packageJsonPath = require.resolve(`${MAU_PACKAGE_NAME}/package.json`, {
      paths: searchPaths,
    });
  } catch {
    return undefined;
  }
  let bin: PackageJsonBin;
  try {
    bin = (
      JSON.parse(readFileSync(packageJsonPath, 'utf8')) as {
        bin?: PackageJsonBin;
      }
    ).bin;
  } catch {
    return undefined;
  }
  const relativeBinPath =
    typeof bin === 'string' ? bin : (bin?.mau ?? Object.values(bin ?? {})[0]);
  if (!relativeBinPath) {
    return undefined;
  }
  const binaryPath = join(dirname(packageJsonPath), relativeBinPath);
  return existsSync(binaryPath) ? binaryPath : undefined;
}

import { confirm } from '@inquirer/prompts';
import ansis from 'ansis';
import { spawn } from 'child_process';
import * as fs from 'fs';
import { join } from 'path';
import { MESSAGES } from '../ui/index.js';
import { gracefullyExitOnPromptError } from './gracefully-exit-on-prompt-error.js';
import { isInteractive } from './is-interactive.js';
const OBSERVE_PACKAGE = '@nestjs/observe';
/**
 * Offers to link the project to NestJS Observe right away, by running the
 * SDK's own `observe link` - which prints a code to approve in the dashboard
 * and writes the key pair into `.env`. Resolves whether it linked.
 *
 * Only where someone is there to approve it, and only when the installed SDK
 * ships the command: an older one, or `--skip-install`, falls back to the
 * printed next steps.
 */

export const offerObserveLink = async (dir: string): Promise<boolean> => {
  if (!isInteractive()) {
    return false;
  }
  const cwd = join(process.cwd(), dir);
  const bin = join(
    'node_modules',
    '.bin',
    process.platform === 'win32' ? 'observe.cmd' : 'observe',
  );
  if (!fs.existsSync(join(cwd, bin))) {
    return false;
  }
  console.info();
  const wantsLink = (await confirm({
    message: MESSAGES.OBSERVABILITY_LINK_QUESTION,
    default: true,
  }).catch(gracefullyExitOnPromptError)) as boolean;
  if (!wantsLink) {
    return false;
  }
  // Run by its path inside the project rather than an absolute one: Windows
  // needs a shell for a `.cmd`, and a shell splits an unquoted path at its
  // first space - `C:\Users\Jane Doe\...`.
  return new Promise<boolean>((resolve) => {
    const child = spawn(bin, ['link'], {
      cwd,
      stdio: 'inherit',
      shell: process.platform === 'win32',
    });
    child.on('error', () => resolve(false));
    child.on('exit', (code) => resolve(code === 0));
  });
};

export const printObservabilityNextSteps = (
  keysHint: string = MESSAGES.OBSERVABILITY_KEYS_HINT,
) => {
  console.info();
  console.info(MESSAGES.OBSERVABILITY_NEXT_STEPS);
  console.info();
  console.info(ansis.bold(MESSAGES.OBSERVABILITY_LINK_COMMAND));
  console.info(ansis.gray(keysHint));
  // Without a TTY, whoever reads this is most likely a coding agent, which
  // can start the link and hand the user the code to approve.
  if (!isInteractive()) {
    console.info();
    console.info(MESSAGES.OBSERVABILITY_AGENT_HINT);
  }
  console.info();
};

export const hasObserveDependency = (dir = process.cwd()): boolean => {
  try {
    const pkg = JSON.parse(
      fs.readFileSync(join(dir, 'package.json'), 'utf8'),
    ) as Record<string, Record<string, string> | undefined>;
    return ['dependencies', 'devDependencies'].some(
      (section) => !!pkg[section]?.[OBSERVE_PACKAGE],
    );
  } catch {
    return false;
  }
};

export default function osName(platform: string, release: string): string {
  switch (platform) {
    case 'darwin':
      return Number(release.split('.')[0]) > 15 ? 'macOS' : 'OS X';
    case 'linux':
      return 'Linux';
    case 'win32':
      return 'Windows';
    case 'freebsd':
      return 'FreeBSD';
    case 'openbsd':
      return 'OpenBSD';
    case 'sunos':
      return 'Solaris';
    case 'android':
      return 'Android';
    default:
      return platform;
  }
}

import { select } from '@inquirer/prompts';
import * as fs from 'fs';
import { join } from 'path';
import { getValueOrDefault } from '../compiler/helpers/get-value-or-default.js';
import { Configuration, ProjectConfiguration } from '../configuration/index.js';
import { generateSelect } from '../questions/questions.js';
import { gracefullyExitOnPromptError } from './gracefully-exit-on-prompt-error.js';
export function shouldAskForProject(
  schematic: string,
  configurationProjects: { [key: string]: ProjectConfiguration },
  appName: string,
) {
  return (
    ['app', 'sub-app', 'library', 'lib'].includes(schematic) === false &&
    configurationProjects &&
    Object.entries(configurationProjects).length !== 0 &&
    !appName
  );
}

export function shouldGenerateSpec(
  configuration: Required<Configuration>,
  schematic: string,
  appName: string,
  specValue: boolean,
  specPassedAsInput?: boolean,
) {
  if (specPassedAsInput === true || specPassedAsInput === undefined) {
    // CLI parameters has the highest priority
    return specValue;
  }
  let specConfiguration = getValueOrDefault(
    configuration,
    'generateOptions.spec',
    appName || '',
  );
  if (typeof specConfiguration === 'boolean') {
    return specConfiguration;
  }
  if (
    typeof specConfiguration === 'object' &&
    specConfiguration[schematic] !== undefined
  ) {
    return specConfiguration[schematic];
  }
  if (typeof specConfiguration === 'object' && appName) {
    // The appName has a generateOption spec, but not for the schematic trying to generate
    // Check if the global generateOptions has a spec to use instead
    specConfiguration = getValueOrDefault(
      configuration,
      'generateOptions.spec',
      '',
    );
    if (typeof specConfiguration === 'boolean') {
      return specConfiguration;
    }
    if (
      typeof specConfiguration === 'object' &&
      specConfiguration[schematic] !== undefined
    ) {
      return specConfiguration[schematic];
    }
  }
  return specValue;
}

export function hasTestingPackage(dir = process.cwd()): boolean {
  try {
    const pkg = JSON.parse(
      fs.readFileSync(join(dir, 'package.json'), 'utf8'),
    ) as Record<string, Record<string, string> | undefined>;
    return ['dependencies', 'devDependencies'].some(
      (section) => !!pkg[section]?.['@nestjs/testing'],
    );
  } catch {
    return true;
  }
}

export function shouldGenerateFlat(
  configuration: Required<Configuration>,
  appName: string,
  flatValue: boolean,
): boolean {
  // CLI parameters have the highest priority
  if (flatValue === true) {
    return flatValue;
  }
  const flatConfiguration = getValueOrDefault(
    configuration,
    'generateOptions.flat',
    appName || '',
  );
  if (typeof flatConfiguration === 'boolean') {
    return flatConfiguration;
  }
  return flatValue;
}

export function getSpecFileSuffix(
  configuration: Required<Configuration>,
  appName: string,
  specFileSuffixValue: string,
): string {
  // CLI parameters have the highest priority
  if (specFileSuffixValue) {
    return specFileSuffixValue;
  }
  const specFileSuffixConfiguration = getValueOrDefault(
    configuration,
    'generateOptions.specFileSuffix',
    appName || '',
    undefined,
    undefined,
    'spec',
  );
  if (typeof specFileSuffixConfiguration === 'string') {
    return specFileSuffixConfiguration;
  }
  return specFileSuffixValue;
}

