export function moveDefaultProjectToStart(
  configuration: Configuration,
  defaultProjectName: string,
  defaultLabel: string,
) {
  let projects: string[] =
    configuration.projects != null ? Object.keys(configuration.projects) : [];
  if (configuration.sourceRoot !== 'src') {
    projects = projects.filter(
      (p) => p !== defaultProjectName.replace(defaultLabel, ''),
    );
  }
  projects.unshift(defaultProjectName);
  return projects;
}

export function getRemainingFlags(cli: Command) {
  // Commander records `rawArgs` on the root command only.
  const commands: Command[] = [];
  for (let cmd: Command | null = cli; cmd; cmd = cmd.parent) {
    commands.push(cmd);
  }
  const rawArgs = [...((commands.at(-1) as any).rawArgs ?? [])];
  const spliceIndex = rawArgs.findIndex((item: string) =>
    item.startsWith('--'),
  );
  if (spliceIndex === -1) {
    return [];
  }
  const findOption = (flag: string) => {
    const flagName = flag.split('=', 1)[0];
    for (const cmd of commands) {
      const match = cmd.options?.find(
        (o: any) => o.short === flagName || o.long === flagName,
      );
      if (match) {
        return match;
      }
    }
    return undefined;
  };
  return rawArgs
    .splice(spliceIndex)
    .filter((item: string, index: number, array: string[]) => {
      // If the option is consumed by commander.js, then we skip it
      if (findOption(item)) {
        return false;
      }
      // If it's an argument of an option consumed by commander.js, then we
      // skip it too
      const prevKeyRaw = array[index - 1];
      if (prevKeyRaw?.startsWith('-')) {
        const matchedOption = findOption(prevKeyRaw);
        const keySource = matchedOption?.long ?? prevKeyRaw;
        const previousKey = camelCase(
          keySource.replace(/--/g, '').replace('no', ''),
        );
        const isConsumedValue = commands.some((cmd) => {
          const optionValue = cmd.getOptionValue?.(previousKey);
          return Array.isArray(optionValue)
            ? optionValue.includes(item)
            : optionValue === item;
        });
        if (isConsumedValue) {
          return false;
        }
      }
      return true;
    });
}

function camelCase(flag: string) {
  const words = flag.split('-').filter((word) => word.length > 0);
  if (words.length === 0) {
    return '';
  }
  return words.reduce((str, word) => {
    return str + word[0].toUpperCase() + word.slice(1);
  });
}

export function resolveModulePath(path: string): string | undefined {
  try {
    return require.resolve(path);
  } catch {
    return undefined;
  }
}

export function treeKillSync(pid: number, signal?: string | number): void {
  if (process.platform === 'win32') {
    taskkill(pid);
    return;
  }
  const children = getAllChildren(pid);
  children.forEach(function (pid) {
    killPid(pid, signal);
  });
  killPid(pid, signal);
  return;
}

function getAllPid(): {
  pid: number;
  ppid: number;
}[] {
  const result = spawnSync('ps', ['-A', '-o', 'pid,ppid'], {
    encoding: 'utf-8',
    stdio: 'pipe',
  });
  if (result.error || !result.stdout) {
    return [];
  }
  const rows = result.stdout.trim().split('\n').slice(1);

return rows
  .map(function (row) {
    const parts = row.match(/\s*(\d+)\s*(\d+)/);
    if (parts === null) {
      return null;
    }
    return {
      pid: Number(parts[1]),
      ppid: Number(parts[2]),
    };
  })
  .filter(<T>(input: null | undefined | T): input is T => {
    return input != null;
  });

return rows
  .map(function (row) {
    const parts = row.match(/\s*(\d+)\s*(\d+)/);
    if (parts === null) {
      return null;
    }
    return {
      pid: Number(parts[1]),
      ppid: Number(parts[2]),
    };
  })

function getAllChildren(pid: number) {
  const allpid = getAllPid();
  const ppidHash: {
    [key: number]: number[];
  } = {};
  const result: number[] = [];
  allpid.forEach(function (item) {
    ppidHash[item.ppid] = ppidHash[item.ppid] || [];
    ppidHash[item.ppid].push(item.pid);
  });
  const find = function (pid: number) {
    ppidHash[pid] = ppidHash[pid] || [];
    ppidHash[pid].forEach(function (childPid) {
      result.push(childPid);
      find(childPid);
    });
  };
  find(pid);
  return result;
}

function killPid(pid: number, signal?: string | number) {
  try {
    process.kill(pid, signal);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code !== 'ESRCH') {
      throw err;
    }
  }
}

function taskkill(pid: number) {
  try {
    execSync('taskkill /pid ' + pid + ' /T /F', { stdio: 'pipe' });
  } catch (err) {
    if (
      (err as { status?: number } | null)?.status !== TASKKILL_PROCESS_NOT_FOUND
    ) {
      throw err;
    }
  }
}

export function assertNonArray<T>(
  value: T,
): asserts value is Exclude<T, any[]> {
  if (Array.isArray(value)) {
    throw new TypeError('Expected a non-array value');
  }
}

