}): Promise<void> {
  await this.sessionModel.deleteMany({
    user: userId.toString(),
    _id: { $not: { $eq: excludeSessionId.toString() } },
  });
}

async deleteById(id: Session['id']): Promise<void> {
  await this.sessionModel.deleteOne({ _id: id.toString() });
}

