public Page(int offset, int limit) {
  setOffset(offset);
  setLimit(limit);
}

private void setOffset(int offset) {
  if (offset > 0) {
    this.offset = offset;
  }
}

private void setLimit(int limit) {
  if (limit > MAX_LIMIT) {
    this.limit = MAX_LIMIT;
  } else if (limit > 0) {
    this.limit = limit;
  }
}

public PageCursor(T data) {
  this.data = data;
}

public T getData() {
