async def __call__(self) -> None:
    if self.is_async:
        await self.func(*self.args, **self.kwargs)
    else:
        await run_in_threadpool(self.func, *self.args, **self.kwargs)

def add_task(self, func: Callable[P, Any], *args: P.args, **kwargs: P.kwargs) -> None:
    task = BackgroundTask(func, *args, **kwargs)
    self.tasks.append(task)

async def __call__(self) -> None:
    for task in self.tasks:
        await task()

async def run_in_threadpool(func: Callable[P, T], *args: P.args, **kwargs: P.kwargs) -> T:
    func = functools.partial(func, *args, **kwargs)
    return await anyio.to_thread.run_sync(func)

def _next(iterator: Iterator[T]) -> T:
    # We can't raise `StopIteration` from within the threadpool iterator
    # and catch it outside that context, so we coerce them into a different
    # exception type.
    try:
        return next(iterator)
    except StopIteration:
        raise _StopIteration

async def iterate_in_threadpool(
    iterator: Iterable[T],
) -> AsyncIterator[T]:
    as_iterator = iter(iterator)
    while True:
        try:
            yield await anyio.to_thread.run_sync(_next, as_iterator)
        except _StopIteration:
            break

def __init__(self, environ: MutableMapping[str, str] = os.environ):
    self._environ = environ
    self._has_been_read: set[str] = set()

def __setitem__(self, key: str, value: str) -> None:
    if key in self._has_been_read:
        raise EnvironError(f"Attempting to set environ['{key}'], but the value has already been read.")
    self._environ.__setitem__(key, value)

def __delitem__(self, key: str) -> None:
    if key in self._has_been_read:
        raise EnvironError(f"Attempting to delete environ['{key}'], but the value has already been read.")
    self._environ.__delitem__(key)

def __call__(
    self,
    key: str,
    cast: Callable[[Any], Any] | None = None,
    default: Any = undefined,
) -> Any:
    return self.get(key, cast, default)

def get(
    self,
    key: str,
    cast: Callable[[Any], Any] | None = None,
    default: Any = undefined,
) -> Any:
    key = self.env_prefix + key
    if key in self.environ:
        value = self.environ[key]
        return self._perform_cast(key, value, cast)
    if key in self.file_values:
        value = self.file_values[key]
        return self._perform_cast(key, value, cast)
    if default is not undefined:
        return self._perform_cast(key, default, cast)
    raise KeyError(f"Config '{key}' is missing, and has no default.")

def _perform_cast(
    self,
    key: str,
    value: Any,
    cast: Callable[[Any], Any] | None = None,
) -> Any:
    if cast is None or value is None:
        return value
    elif cast is bool and isinstance(value, str):
        mapping = {"true": True, "1": True, "false": False, "0": False}
        value = value.lower()
        if value not in mapping:
            raise ValueError(f"Config '{key}' has value '{value}'. Not a valid bool.")
        return mapping[value]
    try:
        return cast(value)
    except (TypeError, ValueError):
        cast_name = getattr(cast, "__name__", type(cast).__name__)
        raise ValueError(f"Config '{key}' has value '{value}'. Not a valid {cast_name}.")

def to_string(self, value: int) -> str:
    value = int(value)
    assert value >= 0, "Negative integers are not supported"
    return str(value)

def __init__(
    self,
    url: str = "",
    scope: Scope | None = None,
    **components: Any,
) -> None:
    if scope is not None:
        assert not url, 'Cannot set both "url" and "scope".'
        assert not components, 'Cannot set both "scope" and "**components".'
        scheme = scope.get("scheme", "http")
        server = scope.get("server", None)
        path = scope["path"].replace("?", "%3F").replace("#", "%23").replace("\\", "%5C")
        query_string = scope.get("query_string", b"")
        host_header = None
        for key, value in scope["headers"]:
            if key == b"host":
                host_header = value.decode("latin-1")
                break
        parsed_host = parse_host_header(host_header)
        if parsed_host is not None and parsed_host.is_valid_port:
            netloc = parsed_host.authority
        elif server is not None:
            host, port = server
            if ":" in host and not host.startswith("["):
                host = f"[{host}]"
            default_port = {"http": 80, "https": 443, "ws": 80, "wss": 443}[scheme]
            netloc = host if port == default_port else f"{host}:{port}"
        else:
            netloc = None
        query = query_string.decode()
        if netloc is not None:
            url = SplitResult(scheme=scheme, netloc=netloc, path=path, query=query, fragment="").geturl()
        else:
            if path.startswith("//"):
                # Without a host, a leading `//` would be parsed as the authority.
                path = "/%2F" + path[2:]
            url = f"{path}?{query}" if query else path
    elif components:
        assert not url, 'Cannot set both "url" and "**components".'
        url = URL("").replace(**components).components.geturl()
    self._url = url

def __init__(self, path: str, protocol: Literal["http", "websocket", ""] = "", host: str = "") -> None:
    self.protocol = protocol
    self.host = host

def __init__(
    self,
    *args: ImmutableMultiDict[_KeyType, _CovariantValueType]
    | Mapping[_KeyType, _CovariantValueType]
    | Iterable[tuple[_KeyType, _CovariantValueType]],
    **kwargs: Any,
) -> None:
    assert len(args) < 2, "Too many arguments."
    value: Any = args[0] if args else []
    if kwargs:
        value = ImmutableMultiDict(value).multi_items() + ImmutableMultiDict(kwargs).multi_items()
    if not value:
        _items: list[tuple[Any, Any]] = []
    elif hasattr(value, "multi_items"):
        value = cast(ImmutableMultiDict[_KeyType, _CovariantValueType], value)
        _items = list(value.multi_items())
    elif hasattr(value, "items"):
        value = cast(Mapping[_KeyType, _CovariantValueType], value)
        _items = list(value.items())
    else:
        value = cast("list[tuple[Any, Any]]", value)
        _items = list(value)
    self._dict = {k: v for k, v in _items}
    self._list = _items

def setdefault(self, key: Any, default: Any = None) -> Any:
    if key not in self:
        self._dict[key] = default
        self._list.append((key, default))
    return self[key]

def update(self, other: Mapping[str, str]) -> None:
    for key, val in other.items():
        self[key] = val

def __init__(self, state: dict[str, Any] | None = None):
    if state is None:
        state = {}
    super().__setattr__("_state", state)

async def method_not_allowed(self, request: Request) -> Response:
    # If we're running inside a starlette application then raise an
    # exception, so that the configurable exception handler can deal with
    # returning the response. For plain ASGI apps, just return the response.
    headers = {"Allow": ", ".join(self._allowed_methods)}
    if "app" in self.scope:
        raise HTTPException(status_code=405, headers=headers)
    return PlainTextResponse("Method Not Allowed", status_code=405, headers=headers)

async def decode(self, websocket: WebSocket, message: Message) -> Any:
    if self.encoding == "text":
        if message.get("text") is None:
            await websocket.close(code=status.WS_1003_UNSUPPORTED_DATA)
            raise RuntimeError("Expected text websocket messages, but got bytes")
        return message["text"]
    elif self.encoding == "bytes":
        if message.get("bytes") is None:
            await websocket.close(code=status.WS_1003_UNSUPPORTED_DATA)
            raise RuntimeError("Expected bytes websocket messages, but got text")
        return message["bytes"]
    elif self.encoding == "json":
        if message.get("text") is not None:
            text = message["text"]
        else:
            text = message["bytes"].decode("utf-8")
        try:
            return json.loads(text)
        except json.decoder.JSONDecodeError:
            await websocket.close(code=status.WS_1003_UNSUPPORTED_DATA)
            raise RuntimeError("Malformed JSON data received.")
    assert self.encoding is None, f"Unsupported 'encoding' attribute {self.encoding}"
    return message["text"] if message.get("text") is not None else message["bytes"]

def __init__(self, status_code: int, detail: str | None = None, headers: Mapping[str, str] | None = None) -> None:
    if detail is None:
        detail = http.client.responses.get(status_code, "")
    self.status_code = status_code
    self.detail = detail
    self.headers = headers

def __repr__(self) -> str:
    class_name = self.__class__.__name__
    return f"{class_name}(status_code={self.status_code!r}, detail={self.detail!r})"

def __init__(self, code: int, reason: str | None = None) -> None:
    self.code = code
    self.reason = reason or ""

def __repr__(self) -> str:
    class_name = self.__class__.__name__
    return f"{class_name}(code={self.code!r}, reason={self.reason!r})"

def _user_safe_decode(src: bytes | bytearray, codec: str) -> str:
    try:
        return src.decode(codec)
    except (UnicodeDecodeError, LookupError):
        return src.decode("latin-1")

def on_field_name(self, data: bytes, start: int, end: int) -> None:
    self._current_field_size += end - start
    if self._current_field_size > self.max_part_size:
        raise MultiPartException(f"Field exceeded maximum size of {int(self.max_part_size / 1024)}KB.")
    self._field_name += data[start:end]

def on_field_data(self, data: bytes, start: int, end: int) -> None:
    self._current_field_size += end - start
    if self._current_field_size > self.max_part_size:
        raise MultiPartException(f"Field exceeded maximum size of {int(self.max_part_size / 1024)}KB.")
    self._field_value += data[start:end]

def __iter__(self) -> Iterator[Any]:
    as_tuple = (self.cls, self.args, self.kwargs)
    return iter(as_tuple)

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] not in ["http", "websocket"]:
        await self.app(scope, receive, send)
        return
    conn = HTTPConnection(scope)
    try:
        auth_result = await self.backend.authenticate(conn)
    except AuthenticationError as exc:
        response = self.on_error(conn, exc)
        if scope["type"] == "websocket":
            await send({"type": "websocket.close", "code": 1000})
        else:
            await response(scope, receive, send)
        return
    if auth_result is None:
        auth_result = AuthCredentials(), UnauthenticatedUser()
    scope["auth"], scope["user"] = auth_result
    await self.app(scope, receive, send)

@staticmethod
def default_on_error(conn: HTTPConnection, exc: Exception) -> Response:
    return PlainTextResponse(str(exc), status_code=400)

def __init__(self, app: ASGIApp, dispatch: DispatchFunction | None = None) -> None:
    self.app = app
    self.dispatch_func = self.dispatch if dispatch is None else dispatch

async def receive_or_disconnect() -> Message:
    if response_sent.is_set():
        return {"type": "http.disconnect"}
    async with anyio.create_task_group() as task_group:
        async def wrap(func: Callable[[], Awaitable[T]]) -> T:
            result = await func()
            task_group.cancel_scope.cancel()
            return result
        task_group.start_soon(wrap, response_sent.wait)
        message = await wrap(wrapped_receive)
    if response_sent.is_set():
        return {"type": "http.disconnect"}
    return message

async def send_no_error(message: Message) -> None:
    try:
        await send_stream.send(message)
    except anyio.BrokenResourceError:
        # recv_stream has been closed, i.e. response_sent has been set.
        return
    if message["type"] == "http.response.pathsend" or (
        message["type"] == "http.response.body" and not message.get("more_body", False)
    ):
        await response_sent.wait()

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] != "http":
        return await self.app(scope, receive, send)
    responder = RequestBodyLimitResponder(self.app, self.max_body_size)
    await responder(scope, receive, send)

@property
def scope(self) -> Scope:
    assert self._scope is not None
    return self._scope

@property
def receive(self) -> Receive:
    assert self._receive is not None
    return self._receive

@property
def send(self) -> Send:
    assert self._send is not None
    return self._send

async def receive_with_limit(self) -> Message:
    if self.content_length is not None and self.content_length > self.max_body_size:
        raise _RequestBodyTooLarge
    message = await self.receive()
    if message["type"] == "http.request":
        self.total_size += len(message.get("body", b""))
        if self.total_size > self.max_body_size:
            raise _RequestBodyTooLarge
    return message

def _get_content_length(scope: Scope) -> int | None:
    content_length = Headers(scope=scope).get("content-length")
    if content_length is None:
        return None
    try:
        return int(content_length)
    except ValueError:
        return None

def is_allowed_origin(self, origin: str) -> bool:
    if self.allow_all_origins:
        return True
    if self.allow_origin_regex is not None and self.allow_origin_regex.fullmatch(origin):
        return True
    return origin in self.allow_origins

def preflight_response(self, request_headers: Headers) -> Response:
    requested_origin = request_headers["origin"]
    requested_method = request_headers["access-control-request-method"]
    requested_headers = request_headers.get("access-control-request-headers")
    requested_private_network = request_headers.get("access-control-request-private-network")
    headers = dict(self.preflight_headers)
    failures: list[str] = []
    if self.is_allowed_origin(origin=requested_origin):
        if self.preflight_explicit_allow_origin:
            # The "else" case is already accounted for in self.preflight_headers
            # and the value would be "*".
            headers["Access-Control-Allow-Origin"] = requested_origin
    else:
        failures.append("origin")
    if requested_method not in self.allow_methods:
        failures.append("method")
    # If we allow all headers, then we have to mirror back any requested
    # headers in the response.
    if self.allow_all_headers and requested_headers is not None:
        headers["Access-Control-Allow-Headers"] = requested_headers
    elif requested_headers is not None:
        for header in [h.lower() for h in requested_headers.split(",")]:
            if header.strip() not in self.allow_headers:
                failures.append("headers")
                break
    if requested_private_network is not None:
        if self.allow_private_network:
            headers["Access-Control-Allow-Private-Network"] = "true"
        else:
            failures.append("private-network")
    # We don't strictly need to use 400 responses here, since its up to
    # the browser to enforce the CORS policy, but its more informative
    # if we do.
    if failures:
        failure_text = "Disallowed CORS " + ", ".join(failures)
        return PlainTextResponse(failure_text, status_code=400, headers=headers)
    return PlainTextResponse("OK", status_code=200, headers=headers)

@staticmethod
def allow_explicit_origin(headers: MutableHeaders, origin: str) -> None:
    headers["Access-Control-Allow-Origin"] = origin
    headers["Vary"] = ", ".join([*headers.getlist("Vary"), "Origin"])

