JS = """
<script type="text/javascript">
    function collapse(element){
        const frameId = element.getAttribute("data-frame-id");
        const frame = document.getElementById(frameId);

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] != "http":
        await self.app(scope, receive, send)
        return
    response_started = False
    async def _send(message: Message) -> None:
        nonlocal response_started, send
        if message["type"] == "http.response.start":
            response_started = True
        await send(message)
    try:
        await self.app(scope, receive, _send)
    except Exception as exc:
        request = Request(scope)
        if self.debug:
            # In debug mode, return traceback responses.
            response = await run_in_threadpool(self.debug_response, request, exc)
        elif self.handler is None:
            # Use our default 500 error handler.
            response = self.error_response(request, exc)
        else:
            # Use an installed 500 error handler.
            if is_async_callable(self.handler):
                response = await self.handler(request, exc)  # type: ignore[assignment, arg-type]
            else:
                response = await run_in_threadpool(self.handler, request, exc)  # type: ignore[arg-type]
        if not response_started:
            await response(scope, receive, send)
        # We always continue to raise the exception.
        # This allows servers to log the error, or allows test clients
        # to optionally raise the error within the test case.
        raise exc

def format_line(self, index: int, line: str, frame_lineno: int, frame_index: int) -> str:
    values = {
        # HTML escape - line could contain < or >
        "line": html.escape(line).replace(" ", "&nbsp"),
        "lineno": (frame_lineno - frame_index) + index,
    }
    if index != frame_index:
        return LINE.format(**values)
    return CENTER_LINE.format(**values)

def generate_frame_html(self, frame: inspect.FrameInfo, is_collapsed: bool) -> str:
    code_context = "".join(
        self.format_line(
            index,
            line,
            frame.lineno,
            frame.index,  # type: ignore[arg-type]
        )
        for index, line in enumerate(frame.code_context or [])
    )
    values = {
        # HTML escape - filename could contain < or >, especially if it's a virtual
        # file e.g. <stdin> in the REPL
        "frame_filename": html.escape(frame.filename),
        "frame_lineno": frame.lineno,
        # HTML escape - if you try very hard it's possible to name a function with <
        # or >
        "frame_name": html.escape(frame.function),
        "code_context": code_context,
        "collapsed": "collapsed" if is_collapsed else "",
        "collapse_button": "+" if is_collapsed else "&#8210;",
    }
    return FRAME_TEMPLATE.format(**values)

def debug_response(self, request: Request, exc: Exception) -> Response:
    accept = request.headers.get("accept", "")
    if "text/html" in accept:
        content = self.generate_html(exc)
        return HTMLResponse(content, status_code=500)
    content = self.generate_plain_text(exc)
    return PlainTextResponse(content, status_code=500)

def __init__(
    self,
    app: ASGIApp,
    handlers: Mapping[Any, ExceptionHandler] | None = None,
    debug: bool = False,
) -> None:
    self.app = app
    self.debug = debug  # TODO: We ought to handle 404 cases if debug is set.
    self._status_handlers: StatusHandlers = {}
    self._exception_handlers: ExceptionHandlers = {
        HTTPException: self.http_exception,
        WebSocketException: self.websocket_exception,
    }
    if handlers is not None:  # pragma: no branch
        for key, value in handlers.items():
            self.add_exception_handler(key, value)

def add_exception_handler(
    self,
    exc_class_or_status_code: int | type[Exception],
    handler: ExceptionHandler,
) -> None:
    if isinstance(exc_class_or_status_code, int):
        self._status_handlers[exc_class_or_status_code] = handler
    else:
        assert issubclass(exc_class_or_status_code, Exception)
        self._exception_handlers[exc_class_or_status_code] = handler

async def http_exception(self, request: Request, exc: Exception) -> Response:
    assert isinstance(exc, HTTPException)
    if exc.status_code in {204, 304}:
        return Response(status_code=exc.status_code, headers=exc.headers)
    return PlainTextResponse(exc.detail, status_code=exc.status_code, headers=exc.headers)

async def send_with_compression(self, message: Message) -> None:
    message_type = message["type"]
    if message_type == "http.response.start":
        # Don't send the initial message until we've determined how to
        # modify the outgoing headers correctly.
        self.initial_message = message
        message.setdefault("headers", [])
        headers = Headers(raw=self.initial_message["headers"])
        self.content_encoding_set = "content-encoding" in headers
        self.partial_response = message["status"] == 206
        media_type = headers.get("content-type", "").partition(";")[0].strip().lower()
        media_types = {media_type, media_type.partition("/")[0] + "/*"}
        if media_type.startswith("application/grpc+"):
            media_types.add("application/grpc")
        self.content_type_is_excluded = not media_types.isdisjoint(self.exclude_content_types)
        if self.content_encoding_set or self.partial_response or self.content_type_is_excluded:
            await self.send(self.initial_message)
    elif message_type in ("http.response.body", "http.response.pathsend") and (
        self.content_encoding_set or self.partial_response or self.content_type_is_excluded
    ):
        await self.send(message)
    elif message_type == "http.response.body" and not self.started:
        self.started = True
        body = message.get("body", b"")
        more_body = message.get("more_body", False)
        if len(body) < self.minimum_size and not more_body:
            # Don't apply compression to small outgoing responses.
            await self.send(self.initial_message)
            await self.send(message)
        elif not more_body:
            # Standard response.
            body = await self.apply_compression(body, more_body=False)
            headers = MutableHeaders(raw=self.initial_message["headers"])
            headers.add_vary_header("Accept-Encoding")
            if body != message["body"]:
                headers["Content-Encoding"] = self.content_encoding
                if self.initial_message.get("trailers", False):
                    del headers["Content-Length"]
                else:
                    headers["Content-Length"] = str(len(body))

async def apply_compression(self, body: bytes, *, more_body: bool) -> bytes:
    if len(body) >= self.thread_minimum_size:
        # Compressing large chunks inline would block the event loop.
        limiter = _get_gzip_capacity_limiter()
        return await anyio.to_thread.run_sync(self._compress_body, body, more_body, limiter=limiter)
    return self._compress_body(body, more_body)

def _compress_body(self, body: bytes, more_body: bool) -> bytes:
    if more_body:
        return self.compressor.compress(body) + self.compressor.flush(zlib.Z_SYNC_FLUSH)
    return self.compressor.compress(body) + self.compressor.flush()

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] != "http" or scope.get("starlette.opentelemetry"):
        return await self.app(scope, receive, send)
    scope["starlette.opentelemetry"] = True
    try:
        tracer_provider = self._tracer_provider
        if isinstance(tracer_provider, trace.NoOpTracerProvider):
            return await self.app(scope, receive, send)
        url = URL(scope=scope)
        if any(pattern.search(str(url)) for pattern in self._excluded_urls):
            return await self.app(scope, receive, send)
        original_method = scope.get("method", "")
        method = original_method.upper()
        headers: dict[str, list[str]] = {}
        for name, value in scope.get("headers", []):
            headers.setdefault(name.decode("latin-1").lower(), []).append(value.decode("latin-1"))
        attributes: dict[str, str | int] = {
            "http.request.method": method,
            "url.path": scope.get("path", ""),
            "url.scheme": scope.get("scheme", "http"),
        }
        if original_method != method:
            attributes["http.request.method_original"] = original_method
        if url.query:
            attributes["url.query"] = url.query
        if url.hostname is not None:
            attributes["server.address"] = url.hostname
            server = scope.get("server")
            server_port = url.port if url.port is not None else server[1] if server is not None else None
            if server_port is not None:
                attributes["server.port"] = server_port
        if scope.get("http_version"):
            attributes["network.protocol.version"] = scope["http_version"]
        if scope.get("client") is not None:
            attributes["client.address"] = scope["client"][0]
        if headers.get("user-agent"):
            attributes["user_agent.original"] = headers["user-agent"][0]

class Session(dict[str, typing.Any]):
    accessed: bool = False
    modified: bool = False

def mark_modified(self) -> None:
    self.accessed = True
    self.modified = True

def __setitem__(self, key: str, value: typing.Any) -> None:
    self.mark_modified()
    super().__setitem__(key, value)

def __delitem__(self, key: str) -> None:
    self.mark_modified()
    super().__delitem__(key)

def clear(self) -> None:
    self.mark_modified()
    super().clear()

def pop(self, key: str, *args: typing.Any) -> typing.Any:
    if key in self:
        self.mark_modified()
    return super().pop(key, *args)

def setdefault(self, key: str, default: typing.Any = None) -> typing.Any:
    if key not in self:
        self.mark_modified()
    return super().setdefault(key, default)

def update(self, *args: typing.Any, **kwargs: typing.Any) -> None:
    self.mark_modified()
    super().update(*args, **kwargs)

def __ior__(self, other: typing.Any, /) -> Session:  # type: ignore[override,misc]
    self.mark_modified()
    return super().__ior__(other)

def __init__(
    self,
    app: ASGIApp,
    allowed_hosts: Sequence[str] | None = None,
    www_redirect: bool = True,
) -> None:
    if allowed_hosts is None:
        allowed_hosts = ["*"]
    for pattern in allowed_hosts:
        assert "*" not in pattern[1:], ENFORCE_DOMAIN_WILDCARD
        if pattern.startswith("*") and pattern != "*":
            assert pattern.startswith("*."), ENFORCE_DOMAIN_WILDCARD
    self.app = app
    self.allowed_hosts = [pattern.lower() for pattern in allowed_hosts]
    self.allow_any = "*" in allowed_hosts
    self.www_redirect = www_redirect

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if self.allow_any or scope["type"] not in (
        "http",
        "websocket",
    ):  # pragma: no cover
        await self.app(scope, receive, send)
        return
    headers = Headers(scope=scope)
    parsed_host = parse_host_header(headers.get("host"))
    if parsed_host is None:
        await PlainTextResponse("Invalid host header", status_code=400)(scope, receive, send)
        return
    host = parsed_host.host.lower()
    is_valid_host = False
    found_www_redirect = False
    for pattern in self.allowed_hosts:
        if host == pattern or (pattern.startswith("*") and host.endswith(pattern[1:])):
            is_valid_host = True
            break
        elif "www." + host == pattern:
            found_www_redirect = True
    if is_valid_host:
        await self.app(scope, receive, send)
    else:
        response: Response
        if found_www_redirect and self.www_redirect:
            url = URL(scope=scope)
            redirect_url = url.replace(netloc="www." + url.netloc)
            response = RedirectResponse(url=str(redirect_url))
        else:
            response = PlainTextResponse("Invalid host header", status_code=400)
        await response(scope, receive, send)

class WSGIResponder:
    stream_send: ObjectSendStream[MutableMapping[str, Any]]
    stream_receive: ObjectReceiveStream[MutableMapping[str, Any]]

def wsgi(
    self,
    environ: dict[str, Any],
    start_response: Callable[..., Any],
) -> None:
    for chunk in self.app(environ, start_response):
        anyio.from_thread.run(
            self.stream_send.send,
            {"type": "http.response.body", "body": chunk, "more_body": True},
        )
    anyio.from_thread.run(self.stream_send.send, {"type": "http.response.body", "body": b""})

def __init__(self, scope: Scope, receive: Receive | None = None) -> None:
    assert scope["type"] in ("http", "websocket")
    self.scope = scope

@property
def query_params(self) -> QueryParams:
    if not hasattr(self, "_query_params"):  # pragma: no branch
        self._query_params = QueryParams(self.scope["query_string"])
    return self._query_params

@property
def user(self) -> Any:
    assert "user" in self.scope, "AuthenticationMiddleware must be installed to access request.user"
    return self.scope["user"]

@property
def state(self) -> StateT:
    if not hasattr(self, "_state"):
        # Ensure 'state' has an empty dict if it's not already populated.
        self.scope.setdefault("state", {})
        # Create a state instance with a reference to the dict in which it should
        # store info
        self._state = State(self.scope["state"])
    return cast(StateT, self._state)

def url_for(self, name: str, /, **path_params: Any) -> URL:
    url_path_provider: Router | Starlette | None = self.scope.get("router") or self.scope.get("app")
    if url_path_provider is None:
        raise RuntimeError("The `url_for` method can only be used inside a Starlette application or with a router.")
    url_path = url_path_provider.url_path_for(name, **path_params)
    return url_path.make_absolute_url(base_url=self.base_url)

def render(self, content: Any) -> bytes:
    return json.dumps(
        content,
        ensure_ascii=False,
        allow_nan=False,
        indent=None,
        separators=(",", ":"),
    ).encode("utf-8")

        if len(ranges) == 0:
            send_file = partial(self._handle_simple, send, send_header_only, send_pathsend)
        elif len(ranges) == 1:
            start, end = ranges[0]
            send_file = partial(self._handle_single_range, send, start, end, stat_result.st_size, send_header_only)
            send_pathsend = False
        else:
            send_file = partial(self._handle_multiple_ranges, send, ranges, stat_result.st_size, send_header_only)
            send_pathsend = False
    spec_version = tuple(map(int, scope.get("asgi", {}).get("spec_version", "2.0").split(".")))
    if scope_type != "http" or send_header_only or send_pathsend or spec_version >= (2, 4):
        await send_file()
    else:
        async with create_collapsing_task_group() as task_group:
            async def stream_file() -> None:
                await send_file()
                task_group.cancel_scope.cancel()
            task_group.start_soon(stream_file)
            while True:
                if (await receive())["type"] == "http.disconnect":
                    task_group.cancel_scope.cancel()
                    break
    if self.background is not None:
        await self.background()
# TODO: Remove this wrapper once minimum AnyIO includes https://github.com/agronholm/anyio/pull/1314.

async def _handle_simple(self, send: Send, send_header_only: bool, send_pathsend: bool) -> None:
    await send({"type": "http.response.start", "status": self.status_code, "headers": self.raw_headers})
    if send_header_only:
        await send({"type": "http.response.body", "body": b"", "more_body": False})
    elif send_pathsend:
        await send({"type": "http.response.pathsend", "path": str(self.path)})
    else:
        async with self._open_file() as file:
            more_body = True
            while more_body:
                chunk = await file.read(self.chunk_size)
                more_body = len(chunk) == self.chunk_size
                await send({"type": "http.response.body", "body": chunk, "more_body": more_body})

def matches(self, scope: Scope) -> tuple[Match, Scope]:
    path_params: dict[str, Any]
    if scope["type"] == "websocket":
        route_path = get_route_path(scope)
        match = self.path_regex.match(route_path)
        if match:
            matched_params = match.groupdict()
            for key, value in matched_params.items():
                matched_params[key] = self.param_convertors[key].convert(value)
            path_params = dict(scope.get("path_params", {}))
            path_params.update(matched_params)
            child_scope = {"endpoint": self.endpoint, "path_params": path_params}
            return Match.FULL, child_scope
    return Match.NONE, {}

def url_path_for(self, name: str, /, **path_params: Any) -> URLPath:
    seen_params = set(path_params.keys())
    expected_params = set(self.param_convertors.keys())
    if name != self.name or seen_params != expected_params:
        raise NoMatchFound(name, path_params)
    path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
    assert not remaining_params
    return URLPath(path=path, protocol="websocket")

def render(self, content: Any) -> bytes:
    assert yaml is not None, "`pyyaml` must be installed to use OpenAPIResponse."
    assert isinstance(content, dict), "The schema passed to OpenAPIResponse should be a dictionary."
    return yaml.dump(content, default_flow_style=False).encode("utf-8")

def get_endpoints(self, routes: list[BaseRoute]) -> list[EndpointInfo]:
    """
    Given the routes, yields the following information:
    - path
        eg: /users/
    - http_method
        one of 'get', 'post', 'put', 'patch', 'delete', 'options', 'query'
    - func
        method ready to extract the docstring
    """
    endpoints_info: list[EndpointInfo] = []
    for route in routes:
        if isinstance(route, Mount | Host):
            routes = route.routes or []
            if isinstance(route, Mount):
                path = self._remove_converter(route.path)
            else:
                path = ""
            sub_endpoints = [
                EndpointInfo(
                    path="".join((path, sub_endpoint.path)),
                    http_method=sub_endpoint.http_method,
                    func=sub_endpoint.func,
                )
                for sub_endpoint in self.get_endpoints(routes)
            ]
            endpoints_info.extend(sub_endpoints)
            continue
        if not isinstance(route, Route) or not route.include_in_schema:
            continue
        endpoint = route.endpoint
        while isinstance(endpoint, functools.partial):
            endpoint = endpoint.func
        path = self._remove_converter(route.path)
        if inspect.isfunction(endpoint) or inspect.ismethod(endpoint):
            for method in route.methods or ["GET"]:
                if method == "HEAD":
                    continue
                endpoints_info.append(EndpointInfo(path, method.lower(), endpoint))
        else:
            for method in ["get", "post", "put", "patch", "delete", "options", "query"]:
                if hasattr(endpoint, method):
                    endpoints_info.append(EndpointInfo(path, method.lower(), getattr(endpoint, method)))
    return endpoints_info

def OpenAPIResponse(self, request: Request) -> Response:
    routes = request.app.routes
    schema = self.get_schema(routes=routes)
    return OpenAPIResponse(schema)

def get_schema(self, routes: list[BaseRoute]) -> dict[str, Any]:
    schema = dict(self.base_schema)
    schema.setdefault("paths", {})
    openapi_version_match = re.match(r"^(\d+)\.(\d+)", str(schema.get("openapi", "")))
    supports_query = openapi_version_match is not None and tuple(map(int, openapi_version_match.groups())) >= (3, 2)
    endpoints_info = self.get_endpoints(routes)
    for endpoint in endpoints_info:
        if endpoint.http_method == "query" and not supports_query:
            continue
        parsed = self.parse_docstring(endpoint.func)
        if not parsed:
            continue
        if endpoint.path not in schema["paths"]:
            schema["paths"][endpoint.path] = {}
        schema["paths"][endpoint.path][endpoint.http_method] = parsed
    return schema

def __init__(self, headers: Headers):
    super().__init__(
        status_code=304,
        headers={name: value for name, value in headers.items() if name in self.NOT_MODIFIED_HEADERS},
    )

async def get_response(self, path: str, scope: Scope) -> Response:
    """
    Returns an HTTP response, given the incoming path, method and request headers.
    """
    if scope["method"] not in ("GET", "HEAD"):
        raise HTTPException(status_code=405, headers={"Allow": "GET, HEAD"})
    try:
        full_path, stat_result = await anyio.to_thread.run_sync(self.lookup_path, path)
    except PermissionError:
        raise HTTPException(status_code=401)
    except OSError as exc:
        # Filename is too long, so it can't be a valid static file.
        if exc.errno == errno.ENAMETOOLONG:
            raise HTTPException(status_code=404)
        raise exc
    except ValueError:
        # Null bytes or other invalid characters in the path.
        raise HTTPException(status_code=404)
    if stat_result and stat.S_ISREG(stat_result.st_mode):
        # We have a static file to serve.
        return self.file_response(full_path, stat_result, scope)
    elif stat_result and stat.S_ISDIR(stat_result.st_mode) and self.html:
        # We're in HTML mode, and have got a directory URL.
        # Check if we have 'index.html' file to serve.
        index_path = os.path.join(path, "index.html")
        full_path, stat_result = await anyio.to_thread.run_sync(self.lookup_path, index_path)
        if stat_result is not None and stat.S_ISREG(stat_result.st_mode):
            if not scope["path"].endswith("/"):
                # Directory URLs should redirect to always end in "/".
                url = URL(scope=scope)
                url = url.replace(path=url.path + "/")
                return RedirectResponse(url=url)
            return self.file_response(full_path, stat_result, scope)
    if self.html:
        # Check for '404.html' if we're in HTML mode.
        full_path, stat_result = await anyio.to_thread.run_sync(self.lookup_path, "404.html")
        if stat_result and stat.S_ISREG(stat_result.st_mode):
            return FileResponse(full_path, stat_result=stat_result, status_code=404)
    raise HTTPException(status_code=404)

def lookup_path(self, path: str) -> tuple[str, os.stat_result | None]:
    # Reject absolute paths so they cannot escape the served directory.
    if path.startswith(("/", "\\")):
        return "", None
    for directory in self.all_directories:
        joined_path = os.path.join(directory, path)
        if self.follow_symlink:
            full_path = os.path.abspath(joined_path)
            directory = os.path.abspath(directory)
        else:
            full_path = os.path.realpath(joined_path)
            directory = os.path.realpath(directory)
        if os.path.commonpath([full_path, directory]) != str(directory):
            # Don't allow misbehaving clients to break out of the static files directory.
            continue
        try:
            return full_path, os.stat(full_path)
        except (FileNotFoundError, NotADirectoryError):
            continue
    return "", None

def file_response(
    self,
    full_path: PathLike,
    stat_result: os.stat_result,
    scope: Scope,
    status_code: int = 200,
) -> Response:
    request_headers = Headers(scope=scope)
    response = FileResponse(full_path, status_code=status_code, stat_result=stat_result)
    if self.is_not_modified(response.headers, request_headers):
        return NotModifiedResponse(response.headers)
    return response

def is_not_modified(self, response_headers: Headers, request_headers: Headers) -> bool:
    """
    Given the request and response headers, return `True` if an HTTP
    "Not Modified" response could be returned instead.
    """
    if if_none_match := request_headers.get("if-none-match"):
        if if_none_match.strip() == "*":
            return True
        # The "etag" header is added by FileResponse, so it's always present.
        etag = response_headers["etag"]
        return etag in [tag.strip().removeprefix("W/") for tag in if_none_match.split(",")]
    try:
        if_modified_since = parsedate(request_headers["if-modified-since"])
        last_modified = parsedate(response_headers["last-modified"])
        if if_modified_since is not None and last_modified is not None and if_modified_since >= last_modified:
            return True
    except KeyError:
        pass
    return False

def __getattr__(name: str) -> int:
    deprecation_changes = {
        "HTTP_413_REQUEST_ENTITY_TOO_LARGE": "HTTP_413_CONTENT_TOO_LARGE",
        "HTTP_414_REQUEST_URI_TOO_LONG": "HTTP_414_URI_TOO_LONG",
        "HTTP_416_REQUESTED_RANGE_NOT_SATISFIABLE": "HTTP_416_RANGE_NOT_SATISFIABLE",
        "HTTP_422_UNPROCESSABLE_ENTITY": "HTTP_422_UNPROCESSABLE_CONTENT",
    }
    deprecated = __deprecated__.get(name)
    if deprecated:
        warnings.warn(
            f"'{name}' is deprecated. Use '{deprecation_changes[name]}' instead.",
            category=StarletteDeprecationWarning,
            stacklevel=3,
        )
        return deprecated
    raise AttributeError(f"module 'starlette.status' has no attribute '{name}'")

