  pb.start();
}

public static void safeDelegatingLauncherArrays(String arg, boolean condition)
    throws java.io.IOException {
  new ProcessBuilder(new String[]{"/usr/bin/env", "/bin/cp", arg, "/tmp/destination"}).start(); // GOOD
