    function createExecPromise(cmd) {
        return new Promise((resolve) => {
            resolve(cmd);
        });
    }
    const cmdPromise = createExecPromise(code);
    maybe(null, cmdPromise).then(cmd => {
        cp.exec(cmd); // $ Alert
    });
});

