const pgp = require('pg-promise')();
require('express')().get('/foo', (req, res) => {
  const db = pgp(process.env['DB_CONNECTION_STRING']);
  var query = "SELECT ITEM,PRICE FROM PRODUCT WHERE ITEM_CATEGORY='"
             + req.params.category + "' ORDER BY PRICE"; // $ Source
  db.any(query); // $ Alert
  db.many(query); // $ Alert
  db.manyOrNone(query); // $ Alert
  db.map(query); // $ Alert
  db.multi(query); // $ Alert
  db.multiResult(query); // $ Alert
  db.none(query); // $ Alert
  db.one(query); // $ Alert
  db.oneOrNone(query); // $ Alert
  db.query(query); // $ Alert
  db.result(query); // $ Alert
  db.one({
    text: query // $ Alert
  });
  db.one({
    text: 'SELECT * FROM news where id = $1',
    values: req.params.id,
  });
  db.one({
    text: 'SELECT * FROM news where id = $1:raw',
    values: req.params.id, // $ Alert - interpreted as raw parameter
  });
  db.one({
    text: 'SELECT * FROM news where id = $1^',
    values: req.params.id, // $ Alert
  });
  db.one({
    text: 'SELECT * FROM news where id = $1:raw AND name = $2:raw AND foo = $3',
    values: [
      req.params.id, // $ Alert
      req.params.name, // $ Alert
      req.params.foo, // OK - not using raw interpolation
    ]
  });
  db.one({

  text: 'SELECT * FROM news where id = ${id}:raw AND name = ${name}',
  values: {
    id: req.params.id, // $ Alert
    name: req.params.name, // OK - not using raw interpolation
  }
});
db.one({
  text: "SELECT * FROM news where id = ${id}:value AND name LIKE '%${name}:value%' AND title LIKE \"%${title}:value%\"",
  values: {
    id: req.params.id, // $ Alert
    name: req.params.name, // OK - :value cannot break out of single quotes
    title: req.params.title, // $ Alert - enclosed by wrong type of quote
  }
});

db.task(t => {
    return t.one(query); // $ Alert
});

  db.taskIf(
    { cnd: t => t.one(query) }, // $ Alert
    t => t.one(query) // $ Alert
  );
});

app.post('/v3/rds/all', async (req, res) => {
    const userQuery = req.body.query; // $ Source
    const userQueries = req.body.queries; // $ MISSING: Source
    const client = new RDSDataClient({ region: "us-east-1" });
    const params1 = {
        resourceArn: "arn:aws:rds:us-east-1:123456789012:cluster:my-aurora-cluster",
        secretArn: "arn:aws:secretsmanager:us-east-1:123456789012:secret:my-secret",
        database: "userDatabase",
        sql: userQuery
    };
    await client.send(new ExecuteStatementCommand(params1)); // $ Alert
    const params2 = {
        resourceArn: "arn:aws:rds:us-east-1:123456789012:cluster:my-aurora-cluster",
        secretArn: "arn:aws:secretsmanager:us-east-1:123456789012:secret:my-secret",
        database: "userDatabase",
        parameterSets: userQueries.map(sql => ({ sql }))
    };
    await client.send(new BatchExecuteStatementCommand(params2)); // $ MISSING: Alert
    const params = {
        resourceArn: "...",
        secretArn: "...",
        database: "userDatabase",
        sqlStatements: userQuery
    };
    await client.send(new ExecuteSqlCommand(params)); // $ Alert
    res.end();
});

app.post('/v2/rds/all', async (req, res) => {
    const userQuery = req.body.query; // $ Source
    const userQueries = req.body.queries; // $ Source
    const rdsData = new AWS.RDSDataService({ region: "us-east-1" });
    const params1 = {
        resourceArn: "arn:aws:rds:us-east-1:123456789012:cluster:my-aurora-cluster",
        secretArn: "arn:aws:secretsmanager:us-east-1:123456789012:secret:my-secret",
        database: "userDatabase",
        sql: userQuery // $ Alert
    };
    await rdsData.executeStatement(params1).promise();
    const params2 = {
        resourceArn: "arn:aws:rds:us-east-1:123456789012:cluster:my-aurora-cluster",
        secretArn: "arn:aws:secretsmanager:us-east-1:123456789012:secret:my-secret",
        database: "userDatabase",
        parameterSets: userQueries.map(sql => ({ sql })) // $ Alert
    };
    await rdsData.batchExecuteStatement(params2).promise();
    res.end();
});

app.post('/documents/find', (req, res) => {
    client.set(req.body.key, "value"); // $ Alert
    var key = req.body.key; // $ Source
    if (typeof key === "string") {
        client.set(key, "value");
        client.set(["key", "value"]);
    }  
    client.set(key, "value"); // $ Alert
    client.hmset("key", "field", "value", key, "value2"); // $ Alert
    // chain commands
    client
        .multi()
        .set("constant", "value")
        .set(key, "value") // $ Alert
        .get(key)
        .exec(function (err, replies) { });
    client.duplicate((err, newClient) => {
        newClient.set(key, "value"); // $ Alert
    });
    client.duplicate().set(key, "value"); // $ Alert
});

