export function greySink(data) { // $ Source[js/unsafe-code-construction]
    const str = `
    ---js
    ${data /* $ Alert[js/unsafe-code-construction] */}
    ---
    `
    const res = matter(str);
    console.log(res);
    matter(str, {
        engines: {
            js: function (data) {
                console.log("NOPE");
            }
        }
    });
}

