http.createServer(function onRequest(req, res) {
  var body;
  try {
    body = handleRequest(req);
  }
  catch (err) { // $ Source
    res.statusCode = 500;
    res.setHeader("Content-Type", "text/plain");
    res.end(err.stack); // $ Alert
    return;
  }
  res.statusCode = 200;
  res.setHeader("Content-Type", "application/json");
  res.setHeader("Content-Length", body.length);
  res.end(body);
}).listen(3000);

http.createServer(function onRequest(req, res) {
  try {
    throw new Error();
  } catch (e) { // $ Source
    res.end(e);                        // $ Alert
    fail(res, e);
    res.end(e.message);
    res.end("Caught exception " + e);
    res.end(e.toString());
    res.end(`Caught exception ${e}.`);
  }
});

function fail(res, e) {
  res.end(e.stack);                    // $ Alert
}

