    if (queryString != null) paramLoc = queryString.indexOf(paramval);
    if (paramLoc == -1) {
        response.getWriter()
                .println(
                        "getQueryString() couldn't find expected parameter '"
                                + "BenchmarkTest01637"
                                + "' in query string.");
        return;
    }
    String param =
            queryString.substring(
                    paramLoc
                            + paramval
                                    .length()); // 1st assume "BenchmarkTest01637" param is last
    // parameter in query string.
