@app.route('/benchmark/xxe-00/BenchmarkTest00017', methods=['POST'])
def BenchmarkTest00017_post():
    RESPONSE = ""
    import urllib.parse
    param = urllib.parse.unquote_plus(request.cookies.get("BenchmarkTest00017", "noCookieValueSupplied"))
    bar = "This should never happen"
    if 'should' in bar:
        bar = param
    import xml.dom.minidom
    import xml.sax.handler
    try:
        parser = xml.sax.make_parser()
        # all features are disabled by default
        doc = xml.dom.minidom.parseString(bar, parser)
        out = ''
        processing = [doc.documentElement]
        while processing:
            e = processing.pop(0)
            if e.nodeType == xml.dom.Node.TEXT_NODE:
                out += e.data
            else:
                processing[:0] = e.childNodes
        RESPONSE += (
            f'Your XML doc results are: <br>{escape_for_html(out)}'
        )
    except:
        RESPONSE += (
            f'There was an error reading your XML doc:<br>{escape_for_html(bar)}'
        )
    return RESPONSE

@app.route('/benchmark/xpathi-00/BenchmarkTest00021', methods=['POST'])
def BenchmarkTest00021_post():
    RESPONSE = ""
    import urllib.parse
    param = urllib.parse.unquote_plus(request.cookies.get("BenchmarkTest00021", "noCookieValueSupplied"))
    bar = "This should never happen"
    if 'should' in bar:
        bar = param
    import lxml.etree
    import helpers.utils
    try:
        if '\'' in bar:
            RESPONSE += (
                "Employee ID must not contain apostrophes"
            )
            return RESPONSE
        fd = open(f'{helpers.utils.RES_DIR}/employees.xml', 'rb')
        root = lxml.etree.parse(fd)
        query = f'/Employees/Employee[@emplid=\'{bar}\']'
        nodes = root.xpath(query)
        node_strings = []
        for node in nodes:
            node_strings.append(' '.join([e.text for e in node]))
        RESPONSE += (
            f'Your XPATH query results are: <br>[ {', '.join(node_strings)} ]'
        )
    except:
        RESPONSE += (
            f'Error parsing XPath Query: \'{escape_for_html(query)}\''
        )
    return RESPONSE

