@Override
protected void configure(HttpSecurity http) throws Exception {
    // ruleid: spring-csrf-disabled
    http
        .csrf().disable()
        .authorizeRequests()
            .antMatchers("/", "/home").permitAll()
            .anyRequest().authenticated()
            .and()
        .formLogin()
            .loginPage("/login")
            .permitAll()
            .and()
        .logout()
            .permitAll();
}

