public DeviceController(DeviceFlowService deviceFlowService) {
    this.deviceFlowService = deviceFlowService;
}

@GetMapping("/")
public String index() {
    return "index";
}

@PostMapping("/login-device")
public String startDeviceFlow(Model model) {
    // Call Keycloak
    DeviceResponse response = deviceFlowService.initiateDeviceFlow();
    deviceFlowService.setDeviceCode(response.deviceCode());
    // Pass the Keycloak data to the HTML page
    model.addAttribute("userCode", response.userCode());
    model.addAttribute("verificationUri", response.verificationUri());
    model.addAttribute("verificationUriComplete", response.verificationUriComplete());
    return "device-info";
}

@GetMapping("/check-status")
@ResponseBody
public Map<String, String> checkStatus() {
    String token = deviceFlowService.getAccessToken();
    String error = deviceFlowService.getLastError();
    if (token != null) {
        return Map.of("state", "success");
    } else if (error != null) {
        return Map.of("state", "error", "message", error);
    }
    return Map.of("state", "pending");
}

@GetMapping("/welcome")
public String welcome(Model model) {
    model.addAttribute("token", deviceFlowService.getAccessToken());
    return "welcome";
}

@PostMapping("/logout")
public String logout() {
    deviceFlowService.logout();
    return "redirect:/";
}

private final RestClient restClient;
private final AtomicReference<String> currentDeviceCode = new AtomicReference<>();
private final AtomicReference<String> accessToken = new AtomicReference<>();
private final AtomicReference<String> lastError = new AtomicReference<>();

public DeviceFlowService(RestClient.Builder builder) {
    this.restClient = builder
            .baseUrl("http://localhost:8080/realms/device-flow-quickstart/protocol/openid-connect")
            .build();
}

public void setDeviceCode(String code) {
    this.currentDeviceCode.set(code);
    this.accessToken.set(null);
    this.lastError.set(null);
}

public DeviceResponse initiateDeviceFlow() {
    MultiValueMap<String, String> formData = new LinkedMultiValueMap<>();
    formData.add("client_id", "device-client");
    formData.add("scope", "openid profile");
    return restClient.post()
            .uri("/auth/device")
            .contentType(MediaType.APPLICATION_FORM_URLENCODED)
            .body(formData)
            .retrieve()
            .body(DeviceResponse.class);
}

@Scheduled(fixedDelay = 1000)
public void pollTask() {
    String code = currentDeviceCode.get();
    if (code == null || accessToken.get() != null) return;
    try {
        MultiValueMap<String, String> formData = new LinkedMultiValueMap<>();
        formData.add("grant_type", "urn:ietf:params:oauth:grant-type:device_code");
        formData.add("client_id", "device-client");
        formData.add("device_code", code);
        TokenResponse response = restClient.post()
                .uri("/token")
                .contentType(MediaType.APPLICATION_FORM_URLENCODED)
                .body(formData)
                .retrieve()
                .body(TokenResponse.class);
        if (response != null && response.accessToken() != null) {
            this.accessToken.set(response.accessToken());
            this.currentDeviceCode.set(null);
        }
    } catch (HttpClientErrorException.BadRequest e) {
        TokenResponse errorResponse = e.getResponseBodyAs(TokenResponse.class);
        String error = errorResponse != null ? errorResponse.error() : "unknown_error";
        switch (error) {
            case "authorization_pending" -> { /* Keep polling */ }
            case "slow_down" -> System.out.println("Keycloak requested slower polling.");
            case "access_denied" -> stopPolling("User denied the request.");
            case "expired_token" -> stopPolling("The device code has expired.");
            default -> stopPolling("An error occurred: " + error);
        }
    }
}

private void stopPolling(String reason) {
    this.lastError.set(reason);
    this.currentDeviceCode.set(null);
}

public void logout() {
    this.accessToken.set(null);
    this.currentDeviceCode.set(null);
    this.lastError.set(null);
}

private static final Logger logger = Logger.getLogger(ExternalAppAuthenticator.class);
public static final String DEFAULT_EXTERNAL_APP_URL = "http://127.0.0.1:8080/action-token-responder-example/external-action.jsp?token={TOKEN}";
public static final String DEFAULT_APPLICATION_ID = "application-id";

@Override
public void authenticate(AuthenticationFlowContext context) {
    String externalApplicationUrl = null;
    String applicationId = null;
    if (context.getAuthenticatorConfig() != null) {
        externalApplicationUrl = context.getAuthenticatorConfig().getConfig().get(ExternalAppAuthenticatorFactory.CONFIG_EXTERNAL_APP_URL);
        applicationId = context.getAuthenticatorConfig().getConfig().get(ExternalAppAuthenticatorFactory.CONFIG_APPLICATION_ID);
    }
    if (externalApplicationUrl == null) {
        externalApplicationUrl = DEFAULT_EXTERNAL_APP_URL;
    }
    if (applicationId == null) {
        applicationId = DEFAULT_APPLICATION_ID;
    }
    int validityInSecs = context.getRealm().getActionTokenGeneratedByUserLifespan();
    int absoluteExpirationInSecs = Time.currentTime() + validityInSecs;
    final AuthenticationSessionModel authSession = context.getAuthenticationSession();
    final String clientId = authSession.getClient().getClientId();
    // Create a token used to return back to the current authentication flow
    String token = new ExternalApplicationNotificationActionToken(
      context.getUser().getId(),
      absoluteExpirationInSecs,
      authSession.getParentSession().getId(),
      applicationId
    ).serialize(
      context.getSession(),
      context.getRealm(),
      context.getUriInfo()
    );
    // This URL will be used by the application to submit the action token above to return back to the flow
    String submitActionTokenUrl;
    submitActionTokenUrl = Urls
      .actionTokenBuilder(context.getUriInfo().getBaseUri(), token, clientId, authSession.getTabId(), "")
      .queryParam(Constants.EXECUTION, context.getExecution().getId())
      .queryParam(ExternalApplicationNotificationActionTokenHandler.QUERY_PARAM_APP_TOKEN, "{tokenParameterName}")
      .build(context.getRealm().getName(), "{APP_TOKEN}")
      .toString();
    try {
        Response challenge = Response
          .status(Status.FOUND)
          .header("Location", externalApplicationUrl.replace("{TOKEN}", URLEncoder.encode(submitActionTokenUrl, "UTF-8")))
          .build();
        context.challenge(challenge);
    } catch (UnsupportedEncodingException ex) {
        throw new RuntimeException(ex);
    }
}

@Override
public void action(AuthenticationFlowContext context) {
    final AuthenticationSessionModel authSession = context.getAuthenticationSession();
    if (! Objects.equals(authSession.getAuthNote(ExternalApplicationNotificationActionTokenHandler.INITIATED_BY_ACTION_TOKEN_EXT_APP), "true")) {
        authenticate(context);
        return;
    }
    authSession.removeAuthNote(ExternalApplicationNotificationActionTokenHandler.INITIATED_BY_ACTION_TOKEN_EXT_APP);
    // Update user according to the claims in the application token
    String appTokenString = context.getUriInfo().getQueryParameters().getFirst(QUERY_PARAM_APP_TOKEN);
    UserModel user = authSession.getAuthenticatedUser();
    String applicationId = null;
    if (context.getAuthenticatorConfig() != null) {
        applicationId = context.getAuthenticatorConfig().getConfig().get(ExternalAppAuthenticatorFactory.CONFIG_APPLICATION_ID);
    }
    if (applicationId == null) {
        applicationId = DEFAULT_APPLICATION_ID;
    }
    try {
        JsonWebToken appToken = TokenVerifier.create(appTokenString, JsonWebToken.class).getToken();
        final String appId = applicationId;
        appToken.getOtherClaims()
          .forEach((key, value) -> user.setAttribute(appId + "." + key, Collections.singletonList(String.valueOf(value))));
    } catch (VerificationException ex) {
        logger.error("Error handling action token", ex);
        context.failure(AuthenticationFlowError.INTERNAL_ERROR, context.form()
                .setError(Messages.INVALID_PARAMETER)
                .createErrorPage(Status.INTERNAL_SERVER_ERROR));
    }
    context.success();
}

