    while (itr.hasNext()) {
        if (!itr.next().getAuthDetails().getUserId().equals(authUserId)) {
            itr.remove();
        }
    }
    return this;
}

@Override
public AdminEventQuery resourcePath(String resourcePath) {
    Iterator<AdminEvent> itr = this.adminEvents.iterator();
    while (itr.hasNext()) {
        if(!Pattern.compile(resourcePath).matcher(itr.next().getResourcePath()).find()) {
            itr.remove();
        }
    }
    return (AdminEventQuery) this;
}

public AdminEventQuery fromTime(long fromTime) {
    Iterator<AdminEvent> itr = this.adminEvents.iterator();
    while (itr.hasNext()) {
        if (!(itr.next().getTime() >= fromTime)) {
            itr.remove();
        }
    }
    return this;
}

@Override
public AdminEventQuery firstResult(int result) {
    this.first = result;
    return this;
}

@Override
public AdminEventQuery maxResults(int results) {
    this.max = results;
    return this;
}

@Override
public Stream<AdminEvent> getResultStream() {
    if (adminEvents.size() < first) {
        return Stream.empty();
    }
    int end = first + max <= adminEvents.size() ? first + max : adminEvents.size();
    return adminEvents.subList(first, end).stream();
}

@Override
public AdminEventQuery orderByDescTime() {
    adminEvents.sort((event1, event2) -> MemEventQuery.signum(event1.getTime() - event2.getTime()));
    return this;
}

@Override
public AdminEventQuery orderByAscTime() {
    adminEvents.sort((event1, event2) -> -MemEventQuery.signum(event1.getTime() - event2.getTime()));
    return this;
}

public MemEventQuery(List<Event> events) {
    this.events = events;
}

@Override
public EventQuery type(EventType... types) {
    Iterator<Event> itr = this.events.iterator();
    while (itr.hasNext()) {
        Event next = itr.next();
        boolean include = false;
        for (EventType e : types) {
            if (next.getType().equals(e)) {
                include = true;
                break;
            }
        }
        if (!include) {
            itr.remove();
        }
    }
    return this;
}

@Override
public EventQuery realm(String realmId) {
    Iterator<Event> itr = this.events.iterator();
    while (itr.hasNext()) {
