    return this;
}

public EventQuery fromDate(long fromDate) {
    Iterator<Event> itr = this.events.iterator();
    while (itr.hasNext()) {
        if (!(itr.next().getTime() >= fromDate)) {
            itr.remove();
        }
    }
    return this;
}

@Override
public EventQuery toDate(Date toDate) {
    return toDate(toDate.getTime());
}

public EventQuery toDate(long toDate) {
    Iterator<Event> itr = this.events.iterator();
    while (itr.hasNext()) {
        if (!(itr.next().getTime() <= toDate)) {
            itr.remove();
        }
    }
    return this;
}

@Override
public EventQuery maxResults(int results) {
    this.max = results;
    return this;
}

@Override
public EventQuery orderByDescTime() {
    events.sort((event1, event2) -> signum(event1.getTime() - event2.getTime()));
    return this;
}

@Override
public EventQuery orderByAscTime() {
    events.sort((event1, event2) -> -signum(event1.getTime() - event2.getTime()));
    return this;
}

static int signum(long l1) {
    if (l1 == 0) return 0;
    return (l1 > 0) ? 1 : -1;
}

private final List<Event> events;
private final Set<EventType> excludedEvents;
private final List<AdminEvent> adminEvents;
private final Set<OperationType> excludedOperations;
private final KeycloakSession session;

public MemEventStoreProvider(List<Event> events, Set<EventType> excludedEvents, 
        List<AdminEvent> adminEvents, Set<OperationType> excludedOperations, KeycloakSession session) {
    this.events = events;
    this.excludedEvents = excludedEvents;
    this.adminEvents = adminEvents;
    this.excludedOperations = excludedOperations;
    this.session = session;
}

@Override
public EventQuery createQuery() {
    return new MemEventQuery(new LinkedList<>(events));
}

@Override
public void clear() {
}

@Override
public void clear(RealmModel realm) {
    synchronized(events) {
        Iterator<Event> itr = events.iterator();
        while (itr.hasNext()) {
            if (itr.next().getRealmId().equals(realm.getId())) {
                itr.remove();
            }
        }
    }
}

@Override
public void clear(RealmModel realm, long olderThan) {
    synchronized(events) {
        Iterator<Event> itr = events.iterator();
        while (itr.hasNext()) {
            Event e = itr.next();
            if (e.getRealmId().equals(realm.getId()) && e.getTime() < olderThan) {
                itr.remove();
            }
        }
    }
}

@Override
public void onEvent(Event event) {
    if (excludedEvents == null || !excludedEvents.contains(event.getType())) {
        events.add(0, event);
    }
}

@Override
public AdminEventQuery createAdminQuery() {
    return new MemAdminEventQuery(new LinkedList<>(adminEvents));
}

@Override
public void clearAdmin() {
}

@Override
public void clearAdmin(RealmModel realm) {
    synchronized(adminEvents) {
        Iterator<AdminEvent> itr = adminEvents.iterator();
        while (itr.hasNext()) {
            if (itr.next().getRealmId().equals(realm.getId())) {
                itr.remove();
            }
        }
    }
}

@Override
public void clearAdmin(RealmModel realm, long olderThan) {
    synchronized(adminEvents) {
        Iterator<AdminEvent> itr = adminEvents.iterator();
        while (itr.hasNext()) {
            AdminEvent e = itr.next();
            if (e.getRealmId().equals(realm.getId()) && e.getTime() < olderThan) {
                itr.remove();
            }
        }
    }
}

@Override
public void clearExpiredEvents() {
    session.realms().getRealmsStream().forEach(r -> {
        if (r.getEventsExpiration() > 0) {
            long olderThan = System.currentTimeMillis() - r.getEventsExpiration() * 1000;
            clear(r, olderThan);
        }
    });
}

private List<Event> events;
private Set<EventType> excludedEvents;
private List<AdminEvent> adminEvents;
private Set<OperationType> excludedOperations;

@Override
public EventStoreProvider create(KeycloakSession session) {
    return new MemEventStoreProvider(events, excludedEvents, adminEvents, excludedOperations, session);
}

@Override
public void init(Config.Scope config) {
    events = Collections.synchronizedList(new LinkedList<Event>());
    adminEvents = Collections.synchronizedList(new LinkedList<AdminEvent>());
    String[] excludes = config.getArray("exclude-events");
    if (excludes != null) {
        excludedEvents = new HashSet<>();
        for (String e : excludes) {
            excludedEvents.add(EventType.valueOf(e));
        }
    }
    String excludesOperations = config.get("excludesOperations");
    if (excludesOperations != null) {
        excludedOperations = new HashSet<>();
        for (String e : excludesOperations.split(",")) {
            excludedOperations.add(OperationType.valueOf(e));
        }
    }
}

@Override
public void close() {
    events = null;
    excludedEvents = null;
    adminEvents = null;
    excludedOperations = null;
}

