import {
  AccountEnvironment,
  Page,
  UserRepresentation,
  getPersonalInfo,
  savePersonalInfo,
  useAccountAlerts,
  useEnvironment,
  usePromise,
} from "@keycloak/keycloak-account-ui";
import { ActionGroup, Button, Form, FormGroup, TextInput } from "@patternfly/react-core";
import { useState } from "react";
import { useTranslation } from "react-i18next";

export const MyPage = () => {
  const { t } = useTranslation();
  const context = useEnvironment<AccountEnvironment>();
  const [personalInfo, setPersonalInfo] = useState<UserRepresentation>();
  const { addAlert, addError } = useAccountAlerts();
  usePromise((signal) => getPersonalInfo({ signal, context }), setPersonalInfo);
  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    try {
      await savePersonalInfo(context, personalInfo);
      addAlert(t("myPage.save.success"));
    } catch (error) {
      console.error(error);
      addError("Not able to save personal info", error);
    }
  };
  return (
    <Page
      title={"My personal info page"}
      description={"Example of a personal info page"}
    >
      <Form isHorizontal onSubmit={onSubmit}>
        <FormGroup label={t("email")} fieldId="email">
          <TextInput
            name="email"
            value={personalInfo?.email}
            onChange={(_, value) =>
              setPersonalInfo({ ...personalInfo, email: value })
            }
          />
        </FormGroup>
        <ActionGroup>
          <Button
            data-testid="save"
            type="submit"
            id="save-btn"
            variant="primary"
          >
            {t("save")}
          </Button>
        </ActionGroup>
      </Form>
    </Page>
  );
};

import {
  Nav,
  NavItem,
  NavItemProps,
  NavList,
  PageSidebar,
  PageSidebarBody,
} from "@patternfly/react-core";
import { PropsWithChildren, MouseEvent as ReactMouseEvent, useState } from "react";
import { useTranslation } from "react-i18next";
import { useHref, useLinkClickHandler } from "react-router-dom";
import { routes } from "./routes";
type NavLinkProps = NavItemProps & {
  path?: string;
};

const NavLink = ({
  path,
  isActive,
  children,
  onClick,
}: PropsWithChildren<NavLinkProps>) => {
  const menuItemPath = path!;
  const href = useHref(menuItemPath);
  const handleClick = useLinkClickHandler(menuItemPath);
  return (
    <NavItem
      to={href}
      onClick={(e, itemId, groupId, to) =>
        {
          onClick?.(e, itemId, groupId, to);
          handleClick(
            e as unknown as ReactMouseEvent<HTMLAnchorElement, MouseEvent>
          );
        }
      }
      isActive={isActive}
    >
      {children}
    </NavItem>
  );
};

export const PageNav = () => {
  const { t } = useTranslation();
  const [active, setActive] = useState<string | undefined>();
  return (
    <PageSidebar>
      <PageSidebarBody>
        <Nav>
          <NavList>
            {routes[0].children
              ?.filter((r) => r.path)
              .map(({ path }) => (
                <NavLink
                  key={path}
                  path={path}
                  isActive={path === window.location.pathname || path === active}
                  onClick={() => setActive(path)}
                >
                  {t(path!.substring(path!.lastIndexOf("/") + 1, path!.length))}
                </NavLink>
              ))}
          </NavList>
        </Nav>
      </PageSidebarBody>
    </PageSidebar>
  );
};

