import KeycloakAdminClient from "@keycloak/keycloak-admin-client";
import {
  AccessContextProvider,
  AccountEnvironment,
  AdminClientContext,
  ErrorBoundaryProvider,
  Header,
  initAdminClient,
  RealmContextProvider,
  RecentRealmsProvider,
  ServerInfoProvider,
  SubGroups,
  useEnvironment,
  WhoAmIContextProvider,
} from "@keycloak/keycloak-admin-ui";
import {
  Page,
  PageSection,
  PageSectionVariants,
  Spinner,
} from "@patternfly/react-core";
import { Suspense, useEffect, useState } from "react";
import { Outlet } from "react-router-dom";
import { PageNav } from "./PageNav";
import style from "./App.module.css";
import viteLogo from "/vite.svg";

function App() {
  const { keycloak, environment } = useEnvironment<AccountEnvironment>();
  const [adminClient, setAdminClient] = useState<KeycloakAdminClient>();
  useEffect(() => {
    const init = async () => {
      const client = await initAdminClient(keycloak, environment);
      setAdminClient(client);
    };
    init().catch(console.error);
  }, []);
  if (!adminClient) return <Spinner />;
  return (
    <AdminClientContext.Provider value={{ keycloak, adminClient }}>
      <ErrorBoundaryProvider>
        <RealmContextProvider>
          <ServerInfoProvider>
            <WhoAmIContextProvider>
              <RecentRealmsProvider>
                <AccessContextProvider>
                  <SubGroups>
                    <Page
                      className={style.headerLogo}
                      header={<Header />}
                      sidebar={<PageNav />}
                      isManagedSidebar
                    >
                      <PageSection variant={PageSectionVariants.darker}>
                        <a href="https://vitejs.dev" target="_blank">
                          <img
                            src={viteLogo}
                            className={style.logo}
                            alt="Vite logo"
                          />
                        </a>
                        <h1>extra content</h1>
                      </PageSection>
                      <Suspense fallback={<Spinner />}>
                        <Outlet />
                      </Suspense>
                    </Page>
                  </SubGroups>
                </AccessContextProvider>
              </RecentRealmsProvider>
            </WhoAmIContextProvider>
          </ServerInfoProvider>
        </RealmContextProvider>
      </ErrorBoundaryProvider>
    </AdminClientContext.Provider>
  );
}

export const MyComponent = () => {
  return (
    <div>
      <h1>My Clients Section</h1>
      <Suspense fallback={<KeycloakSpinner />}>
        {ClientsSection.default()}
      </Suspense>
    </div>
  );
};

import { createInstance } from "i18next";
import FetchBackend from "i18next-fetch-backend";
import { initReactI18next } from "react-i18next";
import { environment } from "./environment";
type KeyValue = { key: string; value: string };
export const i18n = createInstance({
  fallbackLng: "en",
  interpolation: {
    escapeValue: false,
  },
  backend: {

loadPath: `${environment.serverBaseUrl}/resources/${environment.realm}/admin/{{lng}}`,
parse: (data: string) => {
  const messages = JSON.parse(data);
  const result: Record<string, string> = {};
  messages.forEach((v: KeyValue) => (result[v.key] = v.value));
  return result;
},

  },
});
i18n.use(FetchBackend);
i18n.use(initReactI18next);

function ErrorBoundary() {
  const error = useRouteError() as Error;
  console.error("Router error:", error);
  return (
    <div style={{ padding: "20px" }}>
      <h1>Error</h1>
      <p>{error?.message || String(error)}</p>
      <pre>{error?.stack}</pre>
    </div>
  );
}

export const ClientsSectionRoute: RouteObject = {
  path: "clients",
  element: <MyComponent />,
};
export const RootRoute: RouteObject = {
  // @ts-ignore
  path: environment.consoleBaseUrl,
  element: <App />,
  errorElement: <ErrorBoundary />,
  children: [
    ClientsSectionRoute,
  ],
};
export const routes: RouteObject[] = [RootRoute];

#!/usr/bin/env node
import { Octokit } from "@octokit/rest";
import gunzip from "gunzip-maybe";
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { pipeline } from "node:stream/promises";
import { fileURLToPath } from "node:url";
import { extract } from "tar-fs";
import { parseArgs } from "node:util";
const DIR_NAME = path.dirname(fileURLToPath(import.meta.url));
const SERVER_DIR = path.resolve(DIR_NAME, "./server");
const LOCAL_QUARKUS = path.resolve(DIR_NAME, "../../../../quarkus/dist/target");
const LOCAL_DIST_NAME = "keycloak-999.0.0-SNAPSHOT.tar.gz";
const SCRIPT_EXTENSION = process.platform === "win32" ? ".bat" : ".sh";
const ADMIN_USERNAME = "admin";
const ADMIN_PASSWORD = "admin";
const options = {
  local: {
    type: "boolean",
  },
  "account-dev": {
    type: "boolean",
  },
  "admin-dev": {
    type: "boolean",
  },
};

async function startServer() {
  let { scriptArgs, keycloakArgs } = handleArgs(process.argv.slice(2));
  await downloadServer(scriptArgs.local);
  const env = {
    KEYCLOAK_ADMIN: ADMIN_USERNAME,
    KEYCLOAK_ADMIN_PASSWORD: ADMIN_PASSWORD,
    ...process.env,
  };
  if (scriptArgs["account-dev"]) {
    env.KC_ACCOUNT_VITE_URL = "http://localhost:5173";
  }
  if (scriptArgs["admin-dev"]) {
    env.KC_ADMIN_VITE_URL = "http://localhost:5174";
  }
  console.info("Starting server…");
  const child = spawn(
    path.join(SERVER_DIR, `bin/kc${SCRIPT_EXTENSION}`),
    [
      "start-dev",
      `--features="login:v2,account:v3,admin-fine-grained-authz:v2,transient-users,oid4vc-vci,organization,declarative-ui,quick-theme,spiffe,kubernetes-service-accounts,workflows"`,
      ...keycloakArgs,
    ],
    {
      shell: true,
      env,
    },
  );
  child.stdout.pipe(process.stdout);
  child.stderr.pipe(process.stderr);
}

