    assertRealmsConfigured();
    if (permissions != null && !permissions.isEmpty()) {
        boolean[] isPermitted = new boolean[permissions.size()];
        int i = 0;
        for (Permission p : permissions) {
            isPermitted[i++] = isPermitted(principals, p);
        }
        return isPermitted;
    }
    return new boolean[0];
}

