private boolean isFileModified() {
    //SHIRO-394: strip file prefix before constructing the File instance:
    String fileNameWithoutPrefix = this.resourcePath.substring(this.resourcePath.indexOf(":") + 1);
    File propertyFile = new File(fileNameWithoutPrefix);
    long currentLastModified = propertyFile.lastModified();
    if (currentLastModified > this.fileLastModified) {
        this.fileLastModified = currentLastModified;
        return true;
    } else {
        return false;
    }
}

private void clearLoadedState() {
    usersLock.writeLock().lock();
    rolesLock.writeLock().lock();
    try {
        users.clear();
        roles.clear();
    } finally {
        rolesLock.writeLock().unlock();
        usersLock.writeLock().unlock();
    }
    // init() would process the previous definitions again, which would bring the dropped entries back
    setUserDefinitions(null);
    setRoleDefinitions(null);
    Stream.of(getAuthenticationCache(), getAuthorizationCache()).filter(Objects::nonNull).forEach(Cache::clear);
}

