private Map<Object, Object> getAttributesLazy() {
    Map<Object, Object> local = attributes;
    if (local == null) {
        synchronized (this) {
            local = attributes;
            if (local == null) {
                local = new ConcurrentHashMap<>();
                attributes = local;
            }
        }
    }
    return local;
}
