@Override
public Session resolveSession() {
    Session session = getSession();
    if (session == null) {
        //try the Subject if it exists:
        Subject existingSubject = getSubject();
        if (existingSubject != null) {
            session = existingSubject.getSession(false);
        }
    }
    return session;
}

@Override
public boolean resolveAuthenticated() {
    Boolean authc = getTypedValue(AUTHENTICATED, Boolean.class);
    if (authc == null) {
        //see if there is an AuthenticationInfo object.  If so, the very presence of one indicates a successful
        //authentication attempt:
        AuthenticationInfo info = getAuthenticationInfo();
        authc = info != null;
    }
    if (!authc) {
        //fall back to a session check:
        Session session = resolveSession();
        if (session != null) {
            Boolean sessionAuthc = (Boolean) session.getAttribute(AUTHENTICATED_SESSION_KEY);
            authc = sessionAuthc != null && sessionAuthc;
        }
    }
    return authc;
}

@Override
public void setAuthenticationInfo(AuthenticationInfo info) {
    nullSafePut(AUTHENTICATION_INFO, info);
}

@Override
public String resolveHost() {
    String host = getHost();
    if (host == null) {
        //check to see if there is an AuthenticationToken from which to retrieve it:
        AuthenticationToken token = getAuthenticationToken();
        if (token instanceof HostAuthenticationToken authenticationToken) {
            host = authenticationToken.getHost();
        }
    }
    if (host == null) {
        Session session = resolveSession();
        if (session != null) {
            host = session.getHost();
        }
    }
    return host;
}

@Override
public boolean isRememberedPrincipals() {
    Boolean remembered = getTypedValue(REMEMBERED_PRINCIPALS, Boolean.class);
    return remembered != null && remembered;
}

protected Session decorate(Session session) {
    if (session == null) {
        throw new IllegalArgumentException("session cannot be null");
    }
    return session instanceof StoppingAwareProxiedSession ? session : new StoppingAwareProxiedSession(session, this);
}

