protected boolean isIpv4Candidate(String host) {
    String[] quads = StringUtils.tokenizeToStringArray(host, ".");
    if (quads == null || quads.length != 4) {
        return false;
    }
    for (String quad : quads) {
        if (!quad.equals("*")) {
            try {
                Integer.parseInt(quad);
            } catch (NumberFormatException nfe) {
                return false;
            }
        }
    }
    return true;
}

