protected Ini getServletContextIniResource(String servletContextPath) {
    String path = WebUtils.normalize(servletContextPath);
    if (getServletContext() != null) {
        InputStream is = getServletContext().getResourceAsStream(path);
        if (is != null) {
            Ini ini = new Ini();
            ini.load(is);
            if (CollectionUtils.isEmpty(ini)) {
                LOGGER.warn("ServletContext INI resource '" + servletContextPath + "' exists, but it did not contain "
                        + "any data.");
            }
            return ini;
        }
    }
    return null;
}

