    String reqBody = restTemplate.getForObject("http://catalog.partner.com/api/products", String.class);
    List<Product> products = mapper.readValue(reqBody, new TypeReference<List<Product>>() {});
    productRepository.saveAll(products);
}

public void syncCatalog() {
    String input = restTemplate.getForObject("http://catalog.partner.com/api/products", String.class);
    List<Product> products = mapper.readValue(input, new TypeReference<List<Product>>() {});
    productRepository.saveAll(products);
}

public void syncCatalog() {
    ProductPage page = webClient.get().uri("https://catalog.partner.com/api/products")
            .retrieve().bodyToMono(ProductPage.class).timeout(Duration.ofSeconds(5)).block();
    List<Product> products = page.items().stream().filter(validator::isValid).map(Product::from).toList();
    productRepository.saveAll(products);
}

