@ExceptionHandler(Exception.class)
public ResponseEntity<Map<String, Object>> handle(Exception ex) {
    Map<String, Object> reqBody = new HashMap<>();
    reqBody.put("error", ex.getMessage());
    reqBody.put("trace", Arrays.toString(ex.getStackTrace()));
    return ResponseEntity.status(500).body(reqBody);
}

@ExceptionHandler(Exception.class)
public ResponseEntity<Map<String, Object>> handle(Exception ex) {
    Map<String, Object> body = new HashMap<>();
    body.put("error", ex.getMessage());
    body.put("trace", Arrays.toString(ex.getStackTrace()));
    return ResponseEntity.status(500).body(body);
}

@ExceptionHandler(Exception.class)
public ResponseEntity<Map<String, Object>> handle(Exception ex) {
    Map<String, Object> input = new HashMap<>();
    input.put("error", ex.getMessage());
    input.put("trace", Arrays.toString(ex.getStackTrace()));
    return ResponseEntity.status(500).body(input);
}

@ExceptionHandler(Exception.class)
public ResponseEntity<Map<String, Object>> handle(Exception ex) {
    log.error("Unhandled error", ex);
    return ResponseEntity.status(500).body(Map.of("error", "Internal error"));
}

