public String getSHA512Hash8(byte[] passphrase) throws NoSuchAlgorithmException, ClassNotFoundException, IllegalAccessException, InstantiationException {
    Class c = Class.forName("SHA512");
    HASH sha512 = (HASH) (c.newInstance());
    byte[] tmp = new byte[4];
    byte[] key = new byte[32 * 2];
    for (int i = 0; i < 2; i++) {
        sha512.init();
        tmp[3] = (byte) i;
        sha512.update(passphrase, 0, passphrase.length);
        System.arraycopy(sha512.digest(), 0, key, i * 32, 32);
    }
    return Base64.getEncoder().encodeToString(key);
}

@GetMapping("/product/vuln/path-injection")
public ResponseEntity<String> vulnerablePathInjection(@RequestParam("path") String path) throws IOException { // $ Source[java/path-injection]
    // Intentionally vulnerable for SAST testing: user-controlled path reaches file read sink.
    try (FileInputStream stream = new FileInputStream(path)) { // $ Alert[java/path-injection]
        byte[] fileContents = stream.readNBytes(1024);
        return ResponseEntity.ok(new String(fileContents, StandardCharsets.UTF_8));
    }
}

public void sendUserFile(Socket sock, String user) throws IOException {
    BufferedReader filenameReader =
            new BufferedReader(new InputStreamReader(sock.getInputStream(), "UTF-8")); // $ Source[java/path-injection]
    String filename = filenameReader.readLine();
    // BAD: read from a file without checking its path
    BufferedReader fileReader = new BufferedReader(new FileReader(filename)); // $ Alert[java/path-injection]
    String fileLine = fileReader.readLine();
    while (fileLine != null) {
        sock.getOutputStream().write(fileLine.getBytes());
        fileLine = fileReader.readLine();
    }
}

public void sendUserFileGood(Socket sock, String user) throws IOException {
    BufferedReader filenameReader =
            new BufferedReader(new InputStreamReader(sock.getInputStream(), "UTF-8"));
    String filename = filenameReader.readLine();
    // GOOD: ensure that the file is in a designated folder in the user's home directory
    if (!filename.contains("..") && filename.startsWith("/home/" + user + "/public/")) {
        BufferedReader fileReader = new BufferedReader(new FileReader(filename));
        String fileLine = fileReader.readLine();
        while (fileLine != null) {
            sock.getOutputStream().write(fileLine.getBytes());
            fileLine = fileReader.readLine();
        }
    }
}

public void sendUserFileGood2(Socket sock, String user) throws Exception {
    BufferedReader filenameReader =
            new BufferedReader(new InputStreamReader(sock.getInputStream(), "UTF-8"));
    String filename = filenameReader.readLine();
    Path publicFolder = Paths.get("/home/" + user + "/public").normalize().toAbsolutePath();
    Path filePath = publicFolder.resolve(filename).normalize().toAbsolutePath();
    // GOOD: ensure that the path stays within the public folder
    if (!filePath.startsWith(publicFolder + File.separator)) {
        throw new IllegalArgumentException("Invalid filename");
    }
    BufferedReader fileReader = new BufferedReader(new FileReader(filePath.toString()));
    String fileLine = fileReader.readLine();
    while (fileLine != null) {
        sock.getOutputStream().write(fileLine.getBytes());
        fileLine = fileReader.readLine();
    }
}

public void sendUserFileGood3(Socket sock, String user) throws Exception {
    BufferedReader filenameReader =
            new BufferedReader(new InputStreamReader(sock.getInputStream(), "UTF-8"));
    String filename = filenameReader.readLine();
    // GOOD: ensure that the filename has no path separators or parent directory references
    if (filename.contains("..") || filename.contains("/") || filename.contains("\\")) {
        throw new IllegalArgumentException("Invalid filename");
    }
    BufferedReader fileReader = new BufferedReader(new FileReader(filename));
    String fileLine = fileReader.readLine();
    while (fileLine != null) {
        sock.getOutputStream().write(fileLine.getBytes());
        fileLine = fileReader.readLine();
    }
}

public void sendUserFileGood5(Socket sock, String user) throws Exception {
    BufferedReader filenameReader =
            new BufferedReader(new InputStreamReader(sock.getInputStream(), "UTF-8"));
    String filename = filenameReader.readLine();
    Path publicFolder = Paths.get("/home/" + user + "/public").toRealPath();
    Path filePath = publicFolder.resolve(filename).toRealPath();
    // GOOD: toRealPath() normalizes the path (resolves ".." and symlinks),
    // equivalent to File.getCanonicalPath()
    if (!filePath.startsWith(publicFolder + File.separator)) {
        throw new IllegalArgumentException("Invalid filename");
    }
    BufferedReader fileReader = new BufferedReader(new FileReader(filePath.toString()));
    String fileLine = fileReader.readLine();
    while (fileLine != null) {
        sock.getOutputStream().write(fileLine.getBytes());
        fileLine = fileReader.readLine();
    }
}

public void sendUserFileBad2(Socket sock, String user) throws IOException {
    BufferedReader filenameReader =
            new BufferedReader(new InputStreamReader(sock.getInputStream(), "UTF-8")); // $ Source[java/path-injection]
    String filename = filenameReader.readLine();
    File file = new File(filename);
    String baseName = file.getName();
    // BAD: `getName()` strips directory separators but does not remove a `..`
    // component (`new File("..").getName()` returns ".."), so it is not a
    // complete path injection sanitizer.
    BufferedReader fileReader = new BufferedReader(new FileReader(baseName)); // $ Alert[java/path-injection]
    String fileLine = fileReader.readLine();
    while (fileLine != null) {
        sock.getOutputStream().write(fileLine.getBytes());
        fileLine = fileReader.readLine();
    }
}

public void sendUserFileGood4(Socket sock, String user) throws IOException {
    BufferedReader filenameReader =
            new BufferedReader(new InputStreamReader(sock.getInputStream(), "UTF-8"));
    String filename = filenameReader.readLine();
    File file = new File(filename);
