@property
def token(self):
    """Generate a JWT token for the user."""
    now = datetime.utcnow()
    exp = (now + timedelta(seconds=DISPATCH_JWT_EXP)).timestamp()
    data = {
        "exp": exp,
        "email": self.email,
    }
    return jwt.encode(data, DISPATCH_JWT_SECRET, algorithm=DISPATCH_JWT_ALG)

