@overdue.expression
def overdue(cls):
    """SQL expression for checking if the evergreen reminder is overdue."""
    return (
        func.date_part("day", func.now() - cls.evergreen_last_reminder_at)
        >= cls.evergreen_reminder_interval  # noqa
    )

