async def parse_request(request: Request):
    request_body_form = await request.form()
    try:
        request = json.loads(request_body_form.get("payload"))
    except Exception:
        raise HTTPException(
            status_code=HTTPStatus.BAD_REQUEST, detail=[{"msg": "Bad Request"}]
        ) from None
    return request

