def check_for_tag_change(
    previous_incident_tags: list[Tag], current_incident_tags: list[Tag]
) -> tuple[str, dict]:
    """Determines if there is any tag change and builds the description string and details if so"""
    added_tags = []
    removed_tags = []
    description = ""
    details = {}
    for tag in previous_incident_tags:
        if tag.id not in [t.id for t in current_incident_tags]:
            removed_tags.append(f"{tag.tag_type.name}/{tag.name}")
    for tag in current_incident_tags:
        if tag.id not in [t.id for t in previous_incident_tags]:
            added_tags.append(f"{tag.tag_type.name}/{tag.name}")
    if added_tags:
        description = f"added {len(added_tags)} tag{'s' if len(added_tags) > 1 else ''}"
        details.update({"added tags": ", ".join(added_tags)})
        if removed_tags:
            description += " and "
    if removed_tags:
        description += f"removed {len(removed_tags)} tag{'s' if len(removed_tags) > 1 else ''}"
        details.update({"removed tags": ", ".join(removed_tags)})
    return (description, details)

def create_correlation_dataframe(dataframe):
    """Create the correlation dataframe based on the boolean dataframe."""
    unique_tags = list(dataframe.columns)
    correlation_matrix_dict = {}
    for tag_a in unique_tags:
        correlation_matrix_dict[tag_a] = correlate_with_every_tag(dataframe, tag_a)
    correlated_dataframe = pd.DataFrame(correlation_matrix_dict)
    correlated_dataframe["index"] = unique_tags
    return correlated_dataframe.set_index("index")

def update(*, db_session, tag: Tag, tag_in: TagUpdate) -> Tag:
    """Updates an existing tag."""
    tag_data = tag.dict()
    update_data = tag_in.dict(exclude_unset=True, exclude={"tag_type"})
    for field in tag_data:
        if field in update_data:
            setattr(tag, field, update_data[field])
    if tag_in.tag_type is not None:
        tag_type = tag_type_service.get_by_name_or_raise(
            db_session=db_session, project_id=tag.project.id, tag_type_in=tag_in.tag_type
        )
        tag.tag_type = tag_type
    db_session.commit()
    return tag

