        route: getOsEnv('MONITOR_ROUTE'),
        username: getOsEnv('MONITOR_USERNAME'),
        password: getOsEnv('MONITOR_PASSWORD'),
    },
};

export function banner(log: Logger): void {
    if (env.app.banner) {
        const route = () => `${env.app.schema}://${env.app.host}:${env.app.port}`;
        log.info(``);
        log.info(`Aloha, your app is ready on ${route()}${env.app.routePrefix}`);
        log.info(`To shut it down, press <CTRL> + C at any time.`);
        log.info(``);
        log.info('-------------------------------------------------------');
        log.info(`Environment  : ${env.node}`);
        log.info(`Version      : ${env.app.version}`);
        log.info(``);
        log.info(`API Info     : ${route()}${env.app.routePrefix}`);
        if (env.graphql.enabled) {
            log.info(`GraphQL      : ${route()}${env.graphql.route}`);
        }
        if (env.swagger.enabled) {
            log.info(`Swagger      : ${route()}${env.swagger.route}`);
        }
        if (env.monitor.enabled) {
            log.info(`Monitor      : ${route()}${env.monitor.route}`);
        }
        log.info('-------------------------------------------------------');
        log.info('');
    } else {
        log.info(`Application is up and running.`);
    }
}

export function getOsEnv(key: string): string {
    if (typeof process.env[key] === 'undefined') {
        throw new Error(`Environment variable ${key} is not set.`);
    }
    return process.env[key] as string;
}

export function getOsEnvOptional(key: string): string | undefined {
    return process.env[key];
}

export function getPath(path: string): string {
    return (process.env.NODE_ENV === 'production')
        ? join(process.cwd(), path.replace('src/', 'dist/').slice(0, -3) + '.js')
        : join(process.cwd(), path);
}

export function getPaths(paths: string[]): string[] {
    return paths.map(p => getPath(p));
}

export function getOsPath(key: string): string {
    return getPath(getOsEnv(key));
}

export function getOsPaths(key: string): string[] {
    return getPaths(getOsEnvArray(key));
}

export function getOsEnvArray(key: string, delimiter: string = ','): string[] {
    return process.env[key] && process.env[key].split(delimiter) || [];
}

export function toNumber(value: string): number {
    return parseInt(value, 10);
}

export function toBool(value: string): boolean {
    return value === 'true';
}

export function normalizePort(port: string): number | string | boolean {
    const parsedPort = parseInt(port, 10);
    if (isNaN(parsedPort)) { // named pipe
        return port;
    }
    if (parsedPort >= 0) { // port number
        return parsedPort;
    }
    return false;
}

import { GraphQLObjectType, GraphQLSchema } from 'graphql';
import * as uuid from 'uuid';
import { env } from '../../env';
import { Logger } from '../../lib/logger';
// This feature is a copy from https://github.com/kadirahq/graphql-errors
const logger = new Logger('app:errors');
// Mark field/type/schema
export const Processed = Symbol();
// Used to identify UserErrors
export const IsUserError = Symbol();
// UserErrors will be sent to the user

constructor(...args: any[]) {
    super(args[0]);
    this.name = 'Error';
    this.message = args[0];
    this[IsUserError] = true;
    Error.captureStackTrace(this);
}

export let defaultHandler = (err?) => {
    if (err[IsUserError]) {
        return err;
    }
    const errId = uuid.v4();
    err.message = `${err.message}: ${errId}`;
    if (!env.isTest) {
        console.error(err && err.stack || err);
    }
    if (env.isProduction) {
        logger.error(err);
    }
    err.message = `500: Internal Error: ${errId}`;
    return err;
};

const maskField = (field, fn) => {
    const resolveFn = field.resolve;
    if (field[Processed] || !resolveFn) {
        return;
    }
    field[Processed] = true;
    field.resolve = async (...args) => {
        try {
            const out = resolveFn.call(undefined, ...args);
            return await Promise.resolve(out);
        } catch (e) {
            throw fn(e);
        }
    };
    // save the original resolve function
    field.resolve._resolveFn = resolveFn;
};

const maskType = (type, fn) => {
    if (type[Processed] || !type.getFields) {
        return;
    }
    const fields = type.getFields();
    for (const fieldName in fields) {
        if (!Object.hasOwnProperty.call(fields, fieldName)) {
            continue;
        }
        maskField(fields[fieldName], fn);
    }
};

const maskSchema = (schema, fn) => {
    const types = schema.getTypeMap();
    for (const typeName in types) {
        if (!Object.hasOwnProperty.call(types, typeName)) {
            continue;
        }
        maskType(types[typeName], fn);
    }
};

export const setDefaultHandler = (handlerFn) => {
    defaultHandler = handlerFn;
};

export const handlingErrors = (thing, fn = defaultHandler) => {
    if (thing instanceof GraphQLSchema) {
        maskSchema(thing, fn);
    } else if (thing instanceof GraphQLObjectType) {
        maskType(thing, fn);
    } else {
        maskField(thing, fn);
    }
};

export const getErrorCode = (message: string): string => {
    if (hasErrorCode(message)) {
        return message.substring(0, 3);
    }
    return '500'; // unkown error code
};

export const getErrorMessage = (message: string): string => {
    if (hasErrorCode(message)) {
        return message.substring(5);
    }
    return message;
};

export const hasErrorCode = (error: any): boolean => {
    let message = error;
    if (error.message) {
        message = error.message;
    }
    const reg = new RegExp('^[0-9]{3}: ');
    return reg.test(message);
};

method?: string;
key?: string;
multiple?: boolean;

/**
 * Creates a new dataloader with the typorm repository
 */
export function createDataLoader<T>(obj: ObjectType<T>, options: CreateDataLoaderOptions = {}): DataLoader<any, any> {
    let repository;
    try {
        repository = getCustomRepository<Repository<any>>(obj);
    } catch (errorRepo) {
        try {
            repository = getRepository(obj);
        } catch (errorModel) {
            throw new Error('Could not create a dataloader, because obj is nether model or repository!');
        }
    }

return new DataLoader(async (ids: number[]) => {
    let items = [];
    if (options.method) {
        items = await repository[options.method](ids);
    } else {
        items = await repository.findByIds(ids);
    }
    const handleBatch = (arr: any[]) => options.multiple === true ? arr : arr[0];
    return ids.map(id => handleBatch(items.filter(item => item[options.key || 'id'] === id)));
});

public static DEFAULT_SCOPE = 'app';
private static parsePathToScope(filepath: string): string {
    if (filepath.indexOf(path.sep) >= 0) {
        filepath = filepath.replace(process.cwd(), '');
        filepath = filepath.replace(`${path.sep}src${path.sep}`, '');
        filepath = filepath.replace(`${path.sep}dist${path.sep}`, '');
        filepath = filepath.replace('.ts', '');
        filepath = filepath.replace('.js', '');
        filepath = filepath.replace(path.sep, ':');
    }
    return filepath;
}
private scope: string;

private static parsePathToScope(filepath: string): string {
    if (filepath.indexOf(path.sep) >= 0) {
        filepath = filepath.replace(process.cwd(), '');
        filepath = filepath.replace(`${path.sep}src${path.sep}`, '');
        filepath = filepath.replace(`${path.sep}dist${path.sep}`, '');
        filepath = filepath.replace('.ts', '');
        filepath = filepath.replace('.js', '');
        filepath = filepath.replace(path.sep, ':');
    }
    return filepath;
}

constructor(scope?: string) {
    this.scope = Logger.parsePathToScope((scope) ? scope : Logger.DEFAULT_SCOPE);
}

public debug(message: string, ...args: any[]): void {
    this.log('debug', message, args);
}

public info(message: string, ...args: any[]): void {
    this.log('info', message, args);
}

public warn(message: string, ...args: any[]): void {
    this.log('warn', message, args);
}

public error(message: string, ...args: any[]): void {
    this.log('error', message, args);
}

private log(level: string, message: string, args: any[]): void {
    if (winston) {
        winston[level](`${this.formatScope()} ${message}`, args);
    }
}

private formatScope(): string {
    return `[${this.scope}]`;
}

