        # Reset change tracking for the next save of this instance

class Cable(PrimaryModel):
            self.update_terminations(force=force_terminations)
        super().save(*args, force_update=True, **save_kwargs)
        # Discard the pre-termination snapshot so that a later save of this instance takes a fresh one
        if adding:
            self.__dict__.pop('_prechange_snapshot', None)
        try:
            trace_paths.send(Cable, instance=self, created=_created, status_written=status_written)
        except UnsupportedCablePath as e:
            raise AbortRequest(e)
        # Reset change tracking for the next save of this instance
        if status_written:
            self._orig_status = self.status
        if profile_written:
            self._orig_profile = self.profile
        self._terminations_modified = False
    def delete(self, *args, **kwargs):
        # Cache the PK locally because super().delete() clears self.pk before the finally block runs; the
        # finally also guarantees the PK is discarded if the delete raises. CableQuerySet.delete() tracks
        # the same way for a queryset delete, which never calls this.
        pk = self.pk
        Cable._track_deletion(pk)
        try:
            return super().delete(*args, **kwargs)
        finally:
            Cable._untrack_deletion(pk)
    @classmethod
    def _track_deletion(cls, pk):
        """
        Track a Cable as being deleted, so that the post_delete handler for its cascaded CableTerminations can
        record the disconnect on each terminating object and skip redundant path retracing (retrace_cable_paths()
        retraces each affected path once, after the Cable itself is deleted). The tracking set lives on a
        threading.local() to isolate concurrent deletions across threads.
        """
        if not hasattr(cls._deletion_tracking, 'pks'):
            cls._deletion_tracking.pks = set()
        cls._deletion_tracking.pks.add(pk)
    @classmethod
    def _untrack_deletion(cls, pk):
        if hasattr(cls._deletion_tracking, 'pks'):
            cls._deletion_tracking.pks.discard(pk)

def _get_x_terminations(self, side):
    """
    Return the terminating objects for the given cable end (A or B).
    """
    if side not in (CableEndChoices.SIDE_A, CableEndChoices.SIDE_B):
        raise ValueError(f"Unknown cable side: {side}")
    attr = f'_{side.lower()}_terminations'
    if hasattr(self, attr):
        # Return a copy so a caller mutating the result cannot defeat change detection
        return list(getattr(self, attr))
    if not self.pk:
        return []
    return [
        # Query self.terminations.all() to leverage cached results
        ct.termination for ct in self.terminations.all() if ct.cable_end == side
    ]

@property
def color_name(self):
    color_name = ""
    for hex_code, label in ColorChoices.CHOICES:
        if hex_code.lower() == self.color.lower():
            color_name = str(label)
    return color_name

def get_terminations(self):
    """
    Return two dictionaries mapping A & B side terminating objects to their corresponding CableTerminations
    for this Cable.
    """
    a_terminations = {}
    b_terminations = {}
    for ct in CableTermination.objects.filter(cable=self).prefetch_related('termination'):
        if ct.cable_end == CableEndChoices.SIDE_A:
            a_terminations[ct.termination] = ct
        else:
            b_terminations[ct.termination] = ct
    return a_terminations, b_terminations

def get_asymmetric_nodes(self):
    """
    Return all available next segments in a split cable path.
    """
    from circuits.models import CircuitTermination
    asymmetric_nodes = []
    for nodes in self.path_objects:
        if type(nodes[0]) in [RearPort, FrontPort, CircuitTermination]:
            asymmetric_nodes.extend([node for node in nodes if node.link is None])
    return asymmetric_nodes

@staticmethod
def _resolve_vc_position(value: str, device) -> str:
    """
    Resolves {vc_position} and {vc_position:X} tokens.
    If the device has a vc_position, replaces the token with that value.
    Otherwise uses the explicit fallback X if given, else '0'.
    """
    def replacer(match):
        explicit_fallback = match.group(1)
        if (
            device is not None
            and device.virtual_chassis is not None
            and device.vc_position is not None
        ):
            return str(device.vc_position)
        return explicit_fallback if explicit_fallback is not None else '0'
    return VC_POSITION_RE.sub(replacer, value)

