def to_representation(self, data):
    cf_field = self.child.fields.get('custom_fields')
    if isinstance(cf_field, CustomFieldsDataField):
        object_type_cfs = [
            cf for cf in cf_field._get_custom_fields()
            if cf.type in (CustomFieldTypeChoices.TYPE_OBJECT, CustomFieldTypeChoices.TYPE_MULTIOBJECT)
        ]
        pks_by_model = {}
        for cf in object_type_cfs:
            pks = pks_by_model.setdefault(cf.related_object_type.model_class(), set())
            for item in data:
                raw = item.custom_field_data.get(cf.name)
                if raw is not None:
                    if cf.type == CustomFieldTypeChoices.TYPE_MULTIOBJECT:
                        pks.update(raw)
                    else:
                        pks.add(raw)
        cache = {}
        for model, pks in pks_by_model.items():
            objects = list(model.objects.filter(pk__in=pks))
            # A target model may lack a REST serializer, so plan only for found targets
            if objects:
                serializer_class = get_serializer_for_model(model)
                # Targets render with their nested (brief) representation
                fields = getattr(serializer_class.Meta, 'brief_fields', None)
                prefetch_related_objects(objects, *get_prefetches_for_serializer(serializer_class, fields=fields))
            for obj in objects:
                cache[(model, obj.pk)] = obj
        self.child.context['cf_object_cache'] = cache
    return super().to_representation(data)

def render_configtemplate(self, request, configtemplate, context):
    try:
        output = configtemplate.render(context=context)
    except Exception as e:
        detail = configtemplate.format_render_error(e)
        if request.accepted_renderer.format == 'txt':
            return Response(detail, status=HTTP_500_INTERNAL_SERVER_ERROR)
        return Response({'detail': detail}, status=HTTP_500_INTERNAL_SERVER_ERROR)
    # If the client has requested "text/plain", return the raw content.
    if request.accepted_renderer.format == 'txt':
        return Response(output)
    serializer = RenderedConfigSerializer(
        instance={'configtemplate': configtemplate, 'content': output},
        context={'request': request},
    )
    return Response(serializer.data)

def get_permissions(self):
    # For render_config action, check only token write ability (not model permissions)
    if self.action == 'render_config':
        return [TokenWritePermission()]
    return super().get_permissions()

