def get_extra_context(self, request, instance):
    # Paginate choices list
    per_page = get_paginate_count(request)
    try:
        page_number = request.GET.get('page', 1)
    except ValueError:
        page_number = 1
    choice_rows = [
        {
            'value': value,
            'label': label,
            'color': instance.get_choice_color(value),
        }
        for value, label in instance.choices
    ]
    paginator = EnhancedPaginator(choice_rows, per_page)
    try:
        choices = paginator.page(page_number)
    except EmptyPage:
        choices = paginator.page(paginator.num_pages)
    return {
        'paginator': paginator,
        'choices': choices,
    }

