@staticmethod
def _get_serializer_class(view):
    if hasattr(view, 'get_serializer_class'):
        return view.get_serializer_class()
    return view.serializer_class

def to_representation(self, instance, **kwargs):
    if instance is None:
        return None
    context = {'request': self.context['request']}
    if instance.__class__ not in self._serializer_cache:
        try:
            serializer = get_serializer_for_model(instance)(nested=True, context=context)
        except SerializerNotFound:
            if not self.allow_missing_serializer:
                raise
            serializer = None
        self._serializer_cache[instance.__class__] = serializer
    else:
        serializer = self._serializer_cache[instance.__class__]
    if serializer is None:
        return None
    return serializer.to_representation(instance)

def validate(self, data):
    if data.get('tags') and (data.get('add_tags') or data.get('remove_tags')):
        raise serializers.ValidationError({
            'tags': 'Cannot specify "tags" together with "add_tags" or "remove_tags".'
        })
    if self.instance is None and data.get('remove_tags'):
        raise serializers.ValidationError({
            'remove_tags': 'Cannot use "remove_tags" when creating a new object.'
        })
    if data.get('add_tags') and data.get('remove_tags'):
        add_pks = {t.pk for t in data['add_tags']}
        remove_pks = {t.pk for t in data['remove_tags']}
        overlap = [t for t in data['add_tags'] if t.pk in (add_pks & remove_pks)]
        if overlap:
            raise serializers.ValidationError({
                'remove_tags':
                    f'Tags may not be present in both "add_tags" and "remove_tags": '
                    f'{", ".join(t.name for t in overlap)}'
            })
    # Pop add_tags/remove_tags before calling super() to prevent them from being passed
    # to the model constructor during ValidatedModelSerializer validation
    add_tags = data.pop('add_tags', None)
    remove_tags = data.pop('remove_tags', None)
    data = super().validate(data)
    # Restore for use in create()/update()
    if add_tags is not None:
        data['add_tags'] = add_tags
    if remove_tags is not None:
        data['remove_tags'] = remove_tags
    return data

def get_invalid_entries_response(entry_errors, total):
    """
    Return a structured error Response for the entries of a bulk request which could not be
    interpreted, or None if every entry was interpretable.
    The bulk update and delete actions first check that each entry identifies an object, before any
    entry has been matched to one. A failure at that stage -- a missing or non-numeric `id`, or an
    entry which is not an object at all -- is reported against the entry's position in the request
    rather than against an object ID, since no object has been identified yet. This is the same
    correlation bulk create uses throughout, for the same reason.
    Passing this stage is what allows every later error to be correlated by `id` instead.
    :param entry_errors: The `errors` of a BulkOperationSerializer bound to a list. These are
        reported as a mapping of the position of each uninterpretable entry in the request to that
        entry's errors; the entries which were interpretable are omitted.
    :param total: The number of entries in the request, for the summary message.
    """
    # Ignore any error not correlated to a position, as it does not pertain to a single entry
    indexed_errors = {
        index: item_errors
        for index, item_errors in entry_errors.items()
        if isinstance(index, int)
    }
    errors = [
        {'index': index, 'errors': _as_field_errors(item_errors)}
        for index, item_errors in sorted(indexed_errors.items())
    ]
    if not errors:
        return None
    return Response(
        {
            'detail': _('{failed_count} of {total} objects failed validation.').format(
                failed_count=len(errors),
                total=total,
            ),
            'errors': errors,
        },
        status=status.HTTP_400_BAD_REQUEST,
    )

def list(self, request, *args, **kwargs):
    if 'export' in request.GET:
        object_type = ObjectType.objects.get_for_model(self.get_serializer_class().Meta.model)
        et = ExportTemplate.objects.restrict(request.user, 'view').filter(
            object_types=object_type,
            name=request.GET['export'],
        ).first()
        if et is None:
            raise Http404
        queryset = self.filter_queryset(self.get_queryset())
        return et.render_to_response(queryset=queryset)
    return super().list(request, *args, **kwargs)

class BulkDestroyModelMixin:
    """
    Support bulk deletion of objects using the list endpoint for a model. Accepts a DELETE action with a list of one
    or more JSON objects, each specifying the numeric ID of an object to be deleted. For example:
    DELETE /api/dcim/sites/
    [
        {"id": 123},
        {"id": 456}
    ]
    """

def __init__(self):
    self._populate_from_cache()
    # Only consult the database when the cache has genuinely never been populated. A cached
    # empty config (no ConfigRevision) is authoritative and must not trigger a re-query.
    if self._cache_miss:
        self._populate_from_db()
    self.defaults = {param.name: param.default for param in PARAMS}

def __getattr__(self, item):
    # Check for hard-coded configuration in settings.py
    if hasattr(settings, item):
        return getattr(settings, item)
    # Return config value from cache
    if item in self.config:
        return self.config[item]
    # Fall back to the parameter's default value
    if item in self.defaults:
        return self.defaults[item]
    raise AttributeError(_("Invalid configuration parameter: {item}").format(item=item))

def get_event_type_choices():
    return [
        Choice(event.name, event.text) for event in registry['event_types'].values()
    ]

@classmethod
def get_filters(cls):
    """
    Override filter generation to support dynamic lookup expressions for certain filter types.
    For specific filter types, new filters are created based on defined lookup expressions in
    the form `<field_name>__<lookup_expr>`
    """
    filters = super().get_filters()
    additional_filters = {}
    for existing_filter_name, existing_filter in filters.items():
        additional_filters.update(cls.get_additional_lookups(existing_filter_name, existing_filter))
    filters.update(additional_filters)
    return filters

def filter_by_request(self, queryset, name, value):
    content_type = ContentType.objects.get_for_model(self.Meta.model)
    action = {
        'created_by_request': Q(action=ObjectChangeActionChoices.ACTION_CREATE),
        'updated_by_request': Q(action=ObjectChangeActionChoices.ACTION_UPDATE),
        'modified_by_request': Q(
            action__in=[ObjectChangeActionChoices.ACTION_CREATE, ObjectChangeActionChoices.ACTION_UPDATE]
        ),
    }.get(name)
    request_id = value
    pks = ObjectChange.objects.filter(
        action,
        changed_object_type=content_type,
        request_id=request_id,
    ).values_list('changed_object_id', flat=True)
    return queryset.filter(pk__in=pks)

def normalize_query(document):
    """
    Return the given GraphQL document as a single line, with its literal argument values replaced by placeholders.
    """
    return strip_ignored_characters(print_ast(visit(document, LiteralValueStripper())))

def get_filter(self):
    for field in self.__strawberry_definition__.fields:
        value = getattr(self, field.name, None)
        if value is not strawberry.UNSET:
            return value
    return None

@strawberry_django.field(annotate={
    'ltree_level': ExpressionWrapper(
        Func(F('path'), function='nlevel', output_field=IntegerField()) - Value(1),
        output_field=IntegerField(),
    )
})
def level(self) -> int:
    ltree_level = getattr(self, 'ltree_level', None)
    if ltree_level is not None:
        return ltree_level
    path = getattr(self, 'path', '') or ''
    return str(path).count('.')

@classproperty
def name(cls):
    return getattr(cls.Meta, 'name', cls.__name__)

def clean(self):
    super().clean()
    from extras.models import CustomField
    # Fields still being provisioned are fetched alongside the active ones, but are not live:
    # their stored data belongs to the job acting on it, so it is neither validated below nor
    # pruned as stale -- while remaining subject to the defaults applied in save(), which draws
    # on this same set of statuses. Only active fields are validated or enforced as required.
    assigned_fields = CustomField.objects.get_for_model(
        self, statuses=CustomFieldStatusChoices.DATA_STATUSES
    )
    custom_fields = {
        cf.name: cf for cf in assigned_fields
        if cf.status == CustomFieldStatusChoices.STATUS_ACTIVE
    }
    # Remove any stale custom field data
    assigned_names = {cf.name for cf in assigned_fields}
    self.custom_field_data = {
        k: v for k, v in self.custom_field_data.items() if k in assigned_names
    }
    # Validate all field values
    for field_name, value in self.custom_field_data.items():
        if (cf := custom_fields.get(field_name)) is None:
            # The field is not live; its value is left to the job which is provisioning it
            continue
        try:
            cf.validate(value)
        except ValidationError as e:
            raise ValidationError(_("Invalid value for custom field '{name}': {error}").format(
                name=field_name, error=e.message
            ))
        # Validate uniqueness if enforced
        if cf.unique and value not in CUSTOMFIELD_EMPTY_VALUES:
            if self._meta.model.objects.exclude(pk=self.pk).filter(**{
                f'custom_field_data__{field_name}': value
            }).exists():
                raise ValidationError(_("Custom field '{name}' must have a unique value.").format(
                    name=field_name
                ))
    # Check for missing required values
    for cf in custom_fields.values():
        if cf.required and cf.name not in self.custom_field_data:
            raise ValidationError(_("Missing required custom field '{name}'.").format(name=cf.name))

@property
def is_synced(self):
    return self.data_file and self.data_synced >= self.data_file.last_updated

