function setSelectionControlsDisabled(stickyActions: HTMLElement, disabled: boolean): void {
  for (const control of stickyActions.querySelectorAll(selectionControlSelector)) {
    if (
      control instanceof HTMLButtonElement ||
      control instanceof HTMLInputElement ||
      control instanceof HTMLSelectElement ||
      control instanceof HTMLTextAreaElement
    ) {
      control.disabled = disabled;
    } else if (control instanceof HTMLAnchorElement) {
      control.classList.toggle('disabled', disabled);
      control.setAttribute('aria-disabled', String(disabled));
      if (disabled) {
        control.tabIndex = -1;
      } else {
        control.removeAttribute('tabindex');
      }
    }
  }
}

function updateElements(targetMode: ColorMode): void {
  document.documentElement.setAttribute('data-bs-theme', targetMode);
  for (const elevation of getElements<HTMLObjectElement>('.rack_elevation')) {
    const svg = elevation.firstElementChild ?? null;
    if (svg !== null && svg.nodeName == 'svg') {
      svg.setAttribute(`data-bs-theme`, targetMode);
    }
  }
}

function initializeFromURL(form: HTMLFormElement): void {
  const urlParams = new URLSearchParams(window.location.search);
  const modifierGroups = form.querySelectorAll('.filter-modifier-group');
  for (const group of modifierGroups) {
    const modifierSelect = group.querySelector<HTMLSelectElement>('.modifier-select');
    const wrapper = group.querySelector('.filter-value-container');
    if (!wrapper) continue;
    const valueInput = wrapper.querySelector<
      HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement
    >('input, select, textarea');
    if (!modifierSelect || !valueInput) continue;
    const baseFieldName = valueInput.name;
    // Special handling for empty - check if field__empty exists in URL
    const emptyParam = `${baseFieldName}__empty`;
    if (urlParams.has(emptyParam)) {
      const emptyValue = urlParams.get(emptyParam);
      const modifier = emptyValue === 'true' ? MODIFIER_EMPTY_TRUE : MODIFIER_EMPTY_FALSE;
      modifierSelect.value = modifier;
      continue; // Don't set value input for empty
    }
    for (const option of modifierSelect.options) {
      const lookup = option.value;
      // Skip empty_true/false as they're handled above
      if (lookup === MODIFIER_EMPTY_TRUE || lookup === MODIFIER_EMPTY_FALSE) continue;
      const paramName = lookup === 'exact' ? baseFieldName : `${baseFieldName}__${lookup}`;
      if (urlParams.has(paramName)) {
        modifierSelect.value = lookup;
        if (valueInput instanceof HTMLSelectElement && valueInput.multiple) {
          const values = urlParams.getAll(paramName);
          for (const option of valueInput.options) {
            option.selected = values.includes(option.value);
          }
        } else {
          valueInput.value = urlParams.get(paramName) || '';
        }
        break;
      }
    }
  }
}

const GUARD_ATTRIBUTE = 'data-disable-on-submit';
// Forms with a guarded submission in flight, mapped to the buttons the guard marked.
const pendingForms = new Map<HTMLFormElement, HTMLButtonElement[]>();
/**
 * Dim the form's enabled submit buttons for handleSubmit(). Class and ARIA only, since `disabled`
 * drops the submitter and survives a Firefox reload.
 */

function markButtons(form: HTMLFormElement): HTMLButtonElement[] {
  const marked: HTMLButtonElement[] = [];
  for (const button of form.querySelectorAll<HTMLButtonElement>('button[type="submit"]')) {
    if (button.disabled || button.classList.contains('disabled')) continue;
    button.classList.add('disabled');
    button.setAttribute('aria-disabled', 'true');
    marked.push(button);
  }
  return marked;
}

export function initMessages(): void {
  const elements = document.querySelectorAll<HTMLDivElement>(
    'body > div#django-messages > div.toast',
  );
  for (const element of elements) {
    if (element !== null) {
      const toast = new Toast(element);
      if (!toast.isShown()) {
        toast.show();
      }
    }
  }
}

load(value: string, preserveValue?: string | string[]) {
  const self = this;
  // Record which request this is. Incremented unconditionally, before any early return
  // below, so that an already-in-flight request from a previous call is always correctly
  // invalidated by any newer call to load() -- even one that itself aborts early (e.g. no
  // valid URL). If another load() call starts before this one's response comes back,
  // `self.loadSequence` will have moved on and this response is stale -- it must be
  // discarded rather than applied.
  self.loadSequence += 1;
  const sequence = self.loadSequence;
  // Remember any value that still needs to be restored, without erasing a value captured
  // by an earlier, still-in-flight call. If this particular call has nothing new to
  // preserve (e.g. its dependency was already cleared by a cascaded change), an earlier
  // call's pending value should still get a chance to be restored by whichever request
  // ends up winning. An empty array (e.g. a multi-select cleared by clear()) doesn't count
  // as something worth preserving.
  const hasValue = Array.isArray(preserveValue)
    ? preserveValue.length > 0
    : preserveValue !== undefined;
  if (hasValue) {
    self.pendingRestoreValue = preserveValue;
  }
  // No API endpoint is configured yet (e.g. a generic object selector before a content type
  // is chosen). No options can be shown under this state, so any pending value carried from
  // an earlier call is no longer relevant to restore here.
  if (!self.api_url) {
    self.pendingRestoreValue = undefined;
    return;
  }
  // Automatically clear any cached options. (Only options included
  // in the API response should be present.)
  self.clearOptions();
  // Populate the null option (if any) if not searching
  if (self.nullOption && !value) {
    self.addOption(self.nullOption);
  }
  // Get the API request URL. If none is provided, abort as no request can be made. No
  // options can be shown for this field under its current (invalid) filter, so any
  // pending value carried from an earlier call is no longer relevant to restore here.
  const url = self.getRequestUrl(value);

async function beginLogin(form: HTMLFormElement): Promise<void> {
  const body = new URLSearchParams();
  for (const [name, value] of new FormData(form).entries()) {
    if (typeof value === 'string') {
      body.append(name, value);
    }
  }
  // Browsers predating AbortSignal.timeout() issue the request without a deadline, which is no
  // worse than the behavior they had before it was imposed.
  const signal =
    typeof AbortSignal.timeout === 'function' ? AbortSignal.timeout(REQUEST_TIMEOUT) : null;
  const res = await fetch(form.action, {
    method: 'POST',
    headers: { Accept: 'application/json' },
    body,
    credentials: 'same-origin',
    signal,
  });
  if (!res.ok || !(res.headers.get('Content-Type') ?? '').includes('application/json')) {
    throw new Error(`The login request returned an unexpected response (HTTP ${res.status})`);
  }
  const { url, html } = (await res.json()) as { url?: string; html?: string };
  if (typeof url === 'string') {
    window.location.assign(url);
  } else if (typeof html === 'string') {
    // The backend renders its own HTML (an auto-submitting form, for instance) instead of
    // redirecting. That document has already been generated by the request above, so render it in
    // place; submitting the form to fetch it again would initiate the login a second time. Note
    // that this does not evade `form-action`: the document is written into NetBox's own, so the
    // form it carries is submitted under NetBox's policy exactly as it would have been otherwise.
    document.open();
    document.write(html);
    document.close();
  } else {
    throw new Error('The login response contained neither a URL nor a document');
  }
}

  if (this.options.persist) {
    this.save();
  }
}
/**
 * Access the full instance.
 *
 * @returns StateManager instance.
 */
public all(): T {
  return this.proxy;
}
/**
 * Access all state keys.
 */
public keys(): K[] {
  return Object.keys(this.proxy) as K[];
}
/**
 * Access all state values.
 */
public values(): T[K][] {
  return Object.values(this.proxy) as T[K][];
}
/**
 * Serialize and save the current state to localStorage.
 */
private save(): void {
  const value = JSON.stringify(this.proxy);
  localStorage.setItem(this.key, value);
}
/**
 * Retrieve the serialized state object from localStorage.
 *
 * @returns Parsed state object.
 */

export function resetSelect<S extends HTMLSelectElement>(select: S): void {
  for (const option of select.options) {
    if (option.selected) {
      option.selected = false;
    }
  }
  select.value = '';
}

