def parse_alphanumeric_range(string):
    """
    Expand an alphanumeric range (continuous or not) into a list.
    'a-d,f' => [a, b, c, d, f]
    '0-3,a-d' => [0, 1, 2, 3, a, b, c, d]
    """
    values = []
    for value in string.split(','):
        if '-' not in value:
            # Item is not a range
            values.append(value)
            continue
        # Find the range's beginning & end values
        try:
            begin, end = value.split('-')
            vals = begin + end
            # Break out of loop if there's an invalid pattern to return an error
            if (not (vals.isdigit() or vals.isalpha())) or (vals.isalpha() and not (vals.isupper() or vals.islower())):
                return []
        except ValueError:
            raise forms.ValidationError(_('Range "{value}" is invalid.').format(value=value))
        # Numeric range
        if begin.isdigit() and end.isdigit():
            if int(begin) >= int(end):
                raise forms.ValidationError(
                    _('Invalid range: Ending value ({end}) must be greater than beginning value ({begin}).').format(
                        begin=begin, end=end
                    )
                )
            for n in list(range(int(begin), int(end) + 1)):
                values.append(n)
        # Alphanumeric range
        else:
            # Not a valid range (more than a single character)
            if not len(begin) == len(end) == 1:
                raise forms.ValidationError(_('Range "{value}" is invalid.').format(value=value))
            if ord(begin) >= ord(end):
                raise forms.ValidationError(_('Range "{value}" is invalid.').format(value=value))
            for n in list(range(ord(begin), ord(end) + 1)):
                values.append(chr(n))
    return values

def _process_query_param(self, key, value) -> None:
    """
    Based on query param value's type and value, update instance's dynamic/static params.
    """
    if isinstance(value, str):
        # Coerce `True` boolean.
        if value.lower() == 'true':
            value = True
        # Coerce `False` boolean.
        elif value.lower() == 'false':
            value = False
        # Query parameters cannot have a `None` (or `null` in JSON) type, convert
        # `None` types to `'null'` so that ?key=null is used in the query URL.
        elif value is None:
            value = 'null'
    # Check type of `value` again, since it may have changed.
    if isinstance(value, str):
        if value.startswith('$'):
            # A value starting with `$` indicates a dynamic query param, where the
            # initial value is unknown and will be updated at the JavaScript layer
            # as the related form field's value changes.
            field_name = value.strip('$')
            self.dynamic_params[field_name] = key
        else:
            # A value _not_ starting with `$` indicates a static query param, where
            # the value is already known and should not be changed at the JavaScript
            # layer.
            if key in self.static_params:
                current = self.static_params[key]
                self.static_params[key] = [v for v in set([*current, value])]
            else:
                self.static_params[key] = [value]
    else:
        # Any non-string values are passed through as static query params, since
        # dynamic query param values have to be a string (in order to start with
        # `$`).
        if key in self.static_params:
            current = self.static_params[key]
            self.static_params[key] = [v for v in set([*current, value])]
        else:
            self.static_params[key] = [value]

def _process_query_params(self, query_params):
    """
    Process an entire query_params dictionary, and handle primitive or list values.
    """
    for key, value in query_params.items():
        if isinstance(value, (list, tuple)):
            # If value is a list/tuple, iterate through each item.
            for item in value:
                self._process_query_param(key, item)
        else:
            self._process_query_param(key, value)

def highlight(value, highlight, trim_pre=None, trim_post=None, trim_placeholder='...'):
    """
    Highlight a string within a string and optionally trim the pre/post portions of the original string.
    Args:
        value: The body of text being searched against
        highlight: The string of compiled regex pattern to highlight in `value`
        trim_pre: Maximum length of pre-highlight text to include
        trim_post: Maximum length of post-highlight text to include
        trim_placeholder: String value to swap in for trimmed pre/post text
    """
    # Split value on highlight string
    try:
        if type(highlight) is re.Pattern:
            pre, match, post = highlight.split(value, maxsplit=1)
        else:
            highlight = re.escape(highlight)
            pre, match, post = re.split(fr'({highlight})', value, maxsplit=1, flags=re.IGNORECASE)
    except ValueError:
        # Match not found
        return escape(value)
    # Trim pre/post sections to length
    if trim_pre and len(pre) > trim_pre:
        pre = trim_placeholder + pre[-trim_pre:]
    if trim_post and len(post) > trim_post:
        post = post[:trim_post] + trim_placeholder
    return f'{escape(pre)}<mark>{escape(match)}</mark>{escape(post)}'

@property
def field_class(self):
    """
    Resolve the property's type (and string format, if specified) to the appropriate field class.
    """
    if self.type == PropertyTypeEnum.ARRAY.value and self.items.get('enum'):
        return forms.MultipleChoiceField
    if self.enum:
        if self.type == PropertyTypeEnum.ARRAY.value:
            return forms.MultipleChoiceField
        return forms.TypedChoiceField
    if self.type == PropertyTypeEnum.STRING.value and self.format is not None:
        try:
            return STRING_FORM_FIELDS[self.format]
        except KeyError:
            raise ValueError(f"Unsupported string format type: {self.format}")
    try:
        return FORM_FIELDS[self.type]
    except KeyError:
        raise ValueError(f"Unknown property type: {self.type}")

def __init__(self, object_list, per_page, orphans=None, **kwargs):
    # Determine the page size
    try:
        per_page = int(per_page)
        if per_page < 1:
            per_page = get_config().PAGINATE_COUNT
    except ValueError:
        per_page = get_config().PAGINATE_COUNT
    # Set orphans count based on page size
    if orphans is None and per_page <= 50:
        orphans = 5
    elif orphans is None:
        orphans = 10
    super().__init__(object_list, per_page, orphans=orphans, **kwargs)

def get_paginate_count(request):
    """
    Determine the desired length of a page, using the following in order:
        1. per_page URL query parameter
        2. Saved user preference
        3. PAGINATE_COUNT global setting.
    Return the lesser of the calculated value and MAX_PAGE_SIZE.
    """
    config = get_config()
    def _max_allowed(page_size):
        if config.MAX_PAGE_SIZE:
            return min(page_size, config.MAX_PAGE_SIZE)
        return page_size
    if 'per_page' in request.GET:
        try:
            per_page = int(request.GET.get('per_page'))
            return _max_allowed(per_page)
        except ValueError:
            pass
    if request.user.is_authenticated:
        per_page = request.user.config.get('pagination.per_page') or config.PAGINATE_COUNT
        return _max_allowed(per_page)
    return _max_allowed(config.PAGINATE_COUNT)

def __post_init__(self):
    if not self.name:
        raise ValueError("Action name must not be empty.")
    if self.name in RESERVED_ACTIONS:
        raise ValueError(f"'{self.name}' is a reserved action and cannot be registered.")

@property
def name(self):
    return f"NetBox {self.edition} v{self.full_version}"

@register.filter()
def bettertitle(value):
    """
    Alternative to the builtin title(). Ensures that the first letter of each word is uppercase but retains the
    original case of all others.
    """
    return title(value)

@register.filter('json')
def render_json(value):
    """
    Render a dictionary as formatted JSON. This filter is invoked as "json":
        {{ data_dict|json }}
    """
    return json.dumps(value, ensure_ascii=False, indent=4, sort_keys=True)

@register.filter()
def kg_to_pounds(n):
    """
    Convert a weight from kilograms to pounds.
    """
    return float(n) * 2.204623

@register.inclusion_tag("navigation/menu.html", takes_context=True)
def nav(context):
    """
    Render the navigation menu.
    """
    user = context['request'].user
    nav_items = []
    # Construct the navigation menu based upon the current user's permissions
    for menu in get_menus():
        groups = []
        for group in menu.groups:
            items = []
            for item in group.items:
                if getattr(item, 'auth_required', False) and not user.is_authenticated:
                    continue
                if not user.has_perms(item.permissions):
                    continue
                if item.staff_only and not user.is_superuser:
                    continue
                buttons = [
                    button for button in item.buttons if user.has_perms(button.permissions)
                ]
                items.append((item, buttons))
            if items:
                groups.append((group, items))
        if groups:
            nav_items.append((menu, groups))
    return {
        'nav_items': nav_items,
    }

def get_schema_type_classes(self):
    """Return {type_class: model} for every model-backed root query type (cached per instance)."""
    cached = getattr(self, '_schema_type_classes', None)
    if cached is not None:
        return cached
    type_classes = {}
    for field in self.get_graphql_schema().query_type.fields.values():
        type_class = self.get_schema_field_type_class(field)
        if type_class is None:
            continue
        model = self.get_graphql_type_model(type_class)
        if model is None:
            continue
        type_classes[type_class] = model
    self._schema_type_classes = type_classes
    return type_classes

def dispatch(self, request, *args, **kwargs):
    # Attempt to authenticate the user using a DRF token, if provided
    if settings.LOGIN_REQUIRED and not request.user.is_authenticated:
        authenticator = TokenAuthentication()
        try:
            if (auth_info := authenticator.authenticate(request)) is not None:
                request.user = auth_info[0]  # User object
                request.auth = auth_info[1]
        except AuthenticationFailed:
            return HttpResponseForbidden("Invalid token")
    return super().dispatch(request, *args, **kwargs)

def clean(self):
    super().clean()
    # If the Cluster is assigned to a Site or Location, all Devices must be assigned to that same scope.
    if self.cluster.scope is not None:
        for device in self.cleaned_data.get('devices', []):
            for scope_field in ['site', 'location']:
                device_scope = getattr(device, scope_field)
                if (
                    self.cluster.scope_type.model_class() == apps.get_model('dcim', scope_field) and
                        device_scope != self.cluster.scope
                ):
                    raise ValidationError({
                        'devices': _(
                            "{device} belongs to a different {scope_field} ({device_scope}) than the "
                            "cluster ({cluster_scope})"
                        ).format(
                            device=device,
                            scope_field=scope_field,
                            device_scope=device_scope,
                            cluster_scope=self.cluster.scope
                        )
                    })

