public boolean saferMacCheck(Socket socket) throws Exception {
    try (InputStream is = socket.getInputStream()) {
        Mac mac = Mac.getInstance("HmacSHA256");
        byte[] data = new byte[1024];
        is.read(data);
        byte[] actualMac = mac.doFinal(data);
        byte[] expectedMac = is.readNBytes(32);
        return MessageDigest.isEqual(expectedMac, actualMac);
    }
}

public boolean saferCheckSignatures(Socket socket, PrivateKey key) throws Exception {
    try (InputStream is = socket.getInputStream()) {
        Signature engine = Signature.getInstance("SHA256withRSA");
        engine.initSign(key);
        byte[] data = socket.getInputStream().readAllBytes();
        engine.update(data);
        byte[] signature = engine.sign();
        byte[] expected = is.readNBytes(256);
        return MessageDigest.isEqual(expected, signature);
    }
}

public boolean saferCheckCiphertext(Socket socket, Key key) throws Exception {
    try (InputStream is = socket.getInputStream()) {
        byte[] plaintext = is.readNBytes(200);
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        byte[] hash = MessageDigest.getInstance("SHA-256").digest(plaintext);
        byte[] tag = cipher.doFinal(hash);
        byte[] expected = socket.getInputStream().readAllBytes();
        return MessageDigest.isEqual(expected, tag);
    }
}

public boolean compareMacWithConstant(Socket socket) throws Exception {
    try (InputStream is = socket.getInputStream()) {
        Mac mac = Mac.getInstance("HmacSHA256");
        byte[] data = new byte[1024];
        socket.getInputStream().read(data);
        byte[] actualMac = mac.doFinal(data);
        return "constant".equals(new String(actualMac));
    }
}

public boolean safeMacCheckWithLoop(Socket socket) throws Exception {
    try (InputStream is = socket.getInputStream()) {
        byte[] data = new byte[256];
        byte[] tag = new byte[32];
        is.read(data);
        is.read(tag);
        Mac mac = Mac.getInstance("Hmac256");
        byte[] computedTag = mac.doFinal(data);
        int result = 0;
        for (int i = 0; i < computedTag.length; i++) {
            result |= computedTag[i] ^ tag[i];
        }
        return result == 0;
    }
}

private static void badUsage() {
    Browser browser = new Browser(); // $ Alert
    browser.loadURL("https://example.com");
    // no further calls
    // BAD: The browser ignores any certificate error by default!
}

private static void goodUsage() {
    Browser browser = new Browser();
    browser.setLoadHandler(new LoadHandler() {
        public boolean onLoad(LoadParams params) {
            return true;
        }
        public boolean onCertificateError(CertificateErrorParams params) {
            return true; // GOOD: This means that loading will be cancelled on certificate errors
        }
    }); // GOOD: A secure `LoadHandler` is used.
    browser.loadURL("https://example.com");
}

public void disableRevocationChecking() {
  flag = false; // $ Alert
}

public void validate(KeyStore cacerts, CertPath certPath) throws Exception {
  CertPathValidator validator = CertPathValidator.getInstance("PKIX");
  PKIXParameters params = new PKIXParameters(cacerts);
  params.setRevocationEnabled(flag); // $ Sink
  validator.validate(certPath, params);
}

public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
    try {
        String ip = request.getParameter("srcIP");
        InetAddress addr = InetAddress.getByName(ip);
        String userId = request.getRemoteUser();
        Integer.parseInt(userId);  // Integer.parse(String) throws RuntimeException
    } catch (UnknownHostException uhex) {
        uhex.printStackTrace();
    } catch (RuntimeException re) {
        re.printStackTrace();    
    }
}

public void doPut(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
    String ip = "10.100.10.81";
    InetAddress addr = InetAddress.getByName(ip); // GOOD: hard-coded variable value or system property not controlled by attacker
}

public void doDelete(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
    try {
        String ip = request.getParameter("srcIP");
        InetAddress addr = InetAddress.getByName(ip);
    } catch (UnknownHostException uhex) {
        throw new IOException("Host not found "+uhex.getMessage());
    }
}

public void doHead(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
    doGet(request, response);
}

public void doTrace(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
    try {
        try {
            String ip = request.getParameter("srcIP");
            InetAddress addr = null;
            try {
                addr = InetAddress.getByName(ip);
                String userId = request.getRemoteUser();
                Integer.parseInt(userId);  // Integer.parse(String) throws RuntimeException        
            } catch (UnknownHostException uhex) {
                throw new UnknownHostException("Got exception "+uhex.getMessage());
            }
        } catch (IOException ie) {
            ie.printStackTrace();
        }
    } catch (RuntimeException re) {
        re.printStackTrace();
    }
}

