export default function UseQueriesComponent() {
  const results = useQueries({
    queries: [
      {
        queryKey: ['repoData'],
        queryFn: fetchRepoData,
      },
      {
        queryKey: ['repoData'],
        queryFn: () => fetchPost,
      },
    ],
  });
